INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('evolv3ai/claude-skills-archive/cloudflare-python-workers', 'cloudflare-python-workers', 'evolv3ai', 'claude-skills-archive', 'community', 'cloudflare-python-workers evolv3ai claude-skills-archive community Cloudflare Python Workers 是一个生产就绪的技能，支持 Cloudflare、React、Tailwind v4 和 AI 集成 Cloudflare Python Workers は、Cloudflare、React、Tailwind v4、AI 統合をサポートするプロダクションレディのスキルです Cloudflare Python Workers는 Cloudflare, React, Tailwind v4 및 AI 통합을 지원하는生产就绪 스킬입니다 Los trabajadores de Python de Cloudflare permiten ejecutar código Python en el borde de la red Les workers Python de Cloudflare permettent d''exécuter du code Python au bord du réseau Die Cloudflare Python Worker ermöglichen die Ausführung von Python-Code am Netzwerkrand Os trabalhadores Python Cloudflare são uma habilidade de produção pronta para o Claude Code CLI Работники Python Cloudflare - это производительная способность для Claude Code CLI عاملو بایتون كلاودفلير هي مهارة جاهزة للإنتاج ل كلود كود سي ال آي Production-ready skills for Claude Code CLI - Cloudflare, React, Tailwind v4, and AI integrations Cloudflare Python Workers Pyodide Python 运行时环境 Cloudflare React Tailwind v4 AI 集成 开发和部署 Production-ready skills for Claude Code CLI - Cloudflare, React, Tailwind v4, and AI integrations');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('majiayu000/claude-skill-registry/vercel-deploy', 'community', 'majiayu000', 'claude-skill-registry', 'majiayu000/claude-skill-registry', 'vercel-deploy', 0, 0, 50, '2026-02-20T04:13:19.581Z', '2026-02-20T05:13:13.904Z', '22878a184192800486298174d524851ddfbfbcd182714e9e20637582278f5c7d', '{"id":"majiayu000/claude-skill-registry/vercel-deploy","name":"vercel-deploy","description":{"zh":"Vercel 部署技能是用于部署 Next.js 应用、设置边缘函数和服务器端渲染的综合技能","ja":"Vercel デプロイ スキルは、Next.js アプリケーションのデプロイ、エッジ関数の設定、サーバーレスの設定を行うための包括的なスキルです","ko":"버셀 배포 스킬은 Next.js 애플리케이션을 배포하고 에지 함수를 설정하고 서버리스를 설정하는ための 포괄적인 스킬입니다","es":"El skill de despliegue en Vercel permite desplegar aplicaciones con funciones de edge, servidor menos y regeneración estática incremental","fr":"Le skill de déploiement sur Vercel permet de déployer des applications avec des fonctions de edge, serveurless et régénération statique incrémentale","de":"Das Vercel-Deploy-Skill ermöglicht das Bereitstellen von Anwendungen mit Edge-Funktionen, Serverless und inkrementeller statischer Regeneration","pt":"Vercel Deploy é uma habilidade que permite implantar aplicações com funções de bordo, sem servidor e regeneração estática incremental","ru":"Vercel Deploy — это навык, который позволяет развертывать приложения с функциями Edge, серверless и инкрементальной статической регенерации","ar":"Vercel Deploy هو مهارة يسمح بنشر التطبيقات مع وظائف الحافة وبدون خادم وتجديد استاتيكي متزايد","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"seo":{"title":{"zh":"Vercel 部署技能","ja":"Vercel デプロイ スキル","ko":"버셀 배포 스킬","es":"Despliegue en Vercel con funciones de edge y servidor menos","fr":"Déployer sur Vercel avec des fonctions de edge et serveur...","de":"Vercel Deploy mit Edge-Funktionen und Serverless","pt":"Implantação de Aplicati