INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ngxtm/devkit/vercel-deploy', 'vercel-deploy', 'ngxtm', 'devkit', 'community', 'vercel-deploy ngxtm devkit community Vercel 部署是一种无服务器部署解决方案，支持边缘函数和 ISR，适用于 Next.js 应用程序 Vercel デプロイは、エッジ関数と ISR をサポートするサーバーレス デプロイ ソリューションであり、Next.js アプリケーションに適しています 버셀 배포는 에지 함수와 ISR을 지원하는 서버리스 배포 솔루션으로 Next.js 애플리케이션에 적합 El despliegue en Vercel permite implementar aplicaciones con funciones de borde y servidor menos. Es ideal para aplicaciones Next.js y configuraciones de ISR Le déploiement sur Vercel permet de mettre en œuvre des applications avec des fonctions de bord et serveurless. Il est idéal pour les applications Next.js et les configurations ISR Das Bereitstellen auf Vercel ermöglicht die Implementierung von Anwendungen mit Edge-Funktionen und Serverless. Es ist ideal für Next.js-Anwendungen und ISR-Konfigurationen O Vercel Deploy é uma habilidade de implantação de aplicativos que permite o uso de funções de edge, servidores sem estado e ISR para melhorar o desempenho e a escalabilidade. Vercel Deploy — это навык развертывания приложений, который позволяет использовать функции edge, серверную часть и ISR для улучшения производительности и масштабируемости. توزيع Vercel هو مهارة لتوزيع التطبيقات التي تمكن من استخدام دوال الحافة وخادم بدون حالة و ISR لتحسين الأداء وتوسيع نطاق التطبيقات. Unified multi-agent skill system for AI coding assistants (Claude Code, Cursor, Copilot, Gemini) with 414+ skills, 38 agents, and 57 commands. Features smart tech detection, per-project installation, and auto-sync from upstream sources. Vercel 部署 边缘函数 无服务器 ISR Next.js 服务器less 自动同步 智能技术检测 Unified multi-agent skill system for AI coding assistants (Claude Code, Cursor, Copilot, Gemini) with 414+ skills, 38 agents, and 57 commands. Features smart tech detection, per-project installation, and auto-sync from upstream sources.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('majiayu000/claude-skill-registry/db', 'community', 'majiayu000', 'claude-skill-registry', 'majiayu000/claude-skill-registry', 'db', 0, 0, 50, '2026-02-20T04:13:19.574Z', '2026-03-01T07:22:06.245Z', '2d1e2b34174a9da5ab7a6451ec7365625668226ab46986c6204384f2c6383856', '{"id":"majiayu000/claude-skill-registry/db","name":"db","description":{"zh":"db 是一个 AI 智能工具，用于管理 Prisma 模式和 Motivia 迁移。使用 PostgreSQL 和 Prisma ORM。","ja":"db は、Prisma スキーマと Motivia 移行を管理する AI エージェントです。PostgreSQL と Prisma ORM を使用します。","ko":"db는 Prisma 스키마 및 Motivia 마이그레이션을 관리하는 AI 에이전트입니다. PostgreSQL 및 Prisma ORM을 사용합니다.","es":"db es una herramienta de AI que gestiona esquemas Prisma y migraciones de Motivia con PostgreSQL y Prisma ORM.","fr":"db est un agent IA qui gère les schémas Prisma et les migrations de Motivia avec PostgreSQL et Prisma ORM.","de":"db ist ein KI-Tool, das Prisma-Schemata und Motivia-Migrationen mit PostgreSQL und Prisma ORM verwaltet.","pt":"O skill db gerencia esquemas Prisma e migrations, permitindo a modificação de bancos de dados com PostgreSQL e Prisma ORM.","ru":"Навык db управляет схемами Prisma и миграциями,允яя изменять базы данных с помощью PostgreSQL и Prisma ORM.","ar":"مهارة db تدير مخططات Prisma والترحيلات، مما يسمح بتعديل قواعد البيانات باستخدام PostgreSQL و Prisma ORM.","en":"Gère le schéma Prisma et les migrations de Motivia. Utilise ce skill quand lutilisateur demande de modifier la base de données, ajouter une table, un champ, une relation, ou effectuer une migration. PostgreSQL avec Prisma ORM."},"seo":{"title":{"zh":"AI智能工具 db - 管理Prisma模式和Motivia迁移","ja":"AIエージェント db - PrismaスキーマとMotivia移行を管理","ko":"AI 에이전트 db - Prisma 스키마 및 Motivia 마이그레이션 관리","es":"Herramientas de AI: db - Gestión de esquema Prisma","fr":"Agents IA: db - Gestion du schéma Prisma","de":"KI-Tools: db - Prisma-Schema-Verwaltung","pt":"Ferramentas de IA: db - Prisma e Migrations","ru":"ИИ Агенты: db - Prisma и Миграции","ar":"أدوات الذكاء الاصطناعي: db - Prisma وترحيلات","en":"db"},"description":{"zh":"db 是一个 AI 智能工具，用于管理 Prisma 模式和 Motivia 迁移。使用 PostgreSQL 和 Prisma ORM。","ja":"db は、Prisma スキーマと Motivia 移行を管理する AI エージェントです。PostgreSQL と Prisma ORM を使用します。","ko":"db는 Prisma 스키마 및 Motivia 마이그레이션을 관리하는 AI 에이전트입니다. PostgreSQL 및 Prisma ORM을 사용합니다.","es":"db es una herramienta de AI que gestiona esquemas Prisma y migraciones de Motivia con PostgreSQL y Prisma ORM.","fr":"db est un agent IA qui gère les schémas Prisma et les migrations de Motivia avec PostgreSQL et Prisma ORM.","de":"db ist ein KI-Tool, das Prisma-Schemata und Motivia-Migrationen mit PostgreSQL und Prisma ORM verwaltet.","pt":"O skill db gerencia esquemas Prisma e migrations, permitindo a modificação de bancos de dados com PostgreSQL e Prisma ORM.","ru":"Навык db управляет схемами Prisma и миграциями,允яя изменять базы данных с помощью PostgreSQL и Prisma ORM.","ar":"مهارة db تدير مخططات Prisma والترحيلات، مما يسمح بتعديل قواعد البيانات باستخدام PostgreSQL و Prisma ORM.","en":"Gère le schéma Prisma et les migrations de Motivia. Utilise ce skill quand lutilisateur demande de modifier la base de données, ajouter une table, un champ, ..."},"definition":{"en":"Gère le schéma Prisma et les migrations de Motivia. Utilise ce skill quand lutilisateur demande de modifier la base de données, ajouter une table, un champ, une relation, ou effectuer une migration. PostgreSQL avec Prisma ORM."},"features":{"zh":["管理 Prisma 模式","执行 Motivia 迁移","支持 PostgreSQL","使用 Prisma ORM","简化数据库管理","高效的迁移处理"],"ja":["Prisma スキーマの管理","Motivia 移行の実行","PostgreSQL のサポート","Prisma ORM の使用","データベース管理の簡素化","効率的な移行処理"],"ko":["Prisma 스키마 관리","Motivia 마이그레이션 실행","PostgreSQL 지원","Prisma ORM 사용","데이터베이스 관리 간소화","효율적인 마이그레이션 처리"],"es":["Gestión de esquemas Prisma","Migraciones de Motivia","Integración con PostgreSQL","Uso de Prisma ORM","Modificación de bases de datos","Creación de tablas y campos"],"fr":["Gestion du schéma Prisma","Migrations de Motivia","Intégration avec PostgreSQL","Utilisation de Prisma ORM","Modification de bases de données","Création de tables et de champs"],"de":["Verwaltung von Prisma-Schemata","Migrationen von Motivia","Integration mit PostgreSQL","Verwendung von Prisma ORM","Modifizierung von Datenbanken","Erstellung von Tabellen und Feldern"],"pt":["Gerenciamento de esquemas Prisma","Migrations de bancos de dados","Utilização de PostgreSQL com Prisma ORM","Modificação de tabelas e campos","Criação de relações entre tabelas","Suporte a migrations de Motivia"],"ru":["Управление схемами Prisma","Миграции баз данных","Использование PostgreSQL с Prisma ORM","Изменение таблиц и полей","Создание отношений между таблицами","Поддержка миграций Motivia"],"ar":["إدارة مخططات Prisma","ترحيلات قواعد البيانات","استخدام PostgreSQL مع Prisma ORM","تعديل الجداول والحقول","إنشاء علاقات بين الجداول","دعم ترحيلات Motivia"]},"keywords":{"zh":["如何使用 db","什么是 Prisma","db 替代品","db 与 Prisma ORM","PostgreSQL 数据库管理","如何安装 db","db 设置指南","AI 智能工具 db"],"ja":["db の使い方","Prisma とは","db の代替","db と Prisma ORM","PostgreSQL データベース管理","db のインストール方法","db の設定ガイド","AI エージェント db"],"ko":["db 사용方法","Prisma란","db 대체품","db와 Prisma ORM","PostgreSQL 데이터베이스 관리","db 설치 방법","db 설정 가이드","AI 에이전트 db"],"es":["herramientas de AI","gestión de bases de datos","Prisma ORM","PostgreSQL","migraciones de Motivia","cómo usar Prisma","alternativas a Prisma","Prisma vs TypeORM","instalación de Prisma","guía de configuración de Prisma"],"fr":["agents IA","gestion de bases de données","Prisma ORM","PostgreSQL","migrations de Motivia","comment utiliser Prisma","alternatives à Prisma","Prisma vs TypeORM","installation de Prisma","guide de configuration de Prisma"],"de":["KI-Tools","Verwaltung von Datenbanken","Prisma ORM","PostgreSQL","Migrationen von Motivia","wie man Prisma verwendet","Alternativen zu Prisma","Prisma vs TypeORM","Installation von Prisma","Konfigurationsanleitung für Prisma"],"pt":["como usar Prisma","o que é Prisma ORM","alternativas ao Prisma","Prisma vs Sequelize","instalar Prisma","guia de configuração do Prisma","migrations de bancos de dados","gerenciamento de esquemas"],"ru":["как использовать Prisma","что такое Prisma ORM","альтернативы Prisma","Prisma vs Sequelize","установить Prisma","руководство по настройке Prisma","миграции баз данных","управление схемами"],"ar":["كيفية استخدام Prisma","ما هو Prisma ORM","بديلات Prisma","Prisma مقابل Sequelize","تثبيت Prisma","دليل إعداد Prisma","ترحيلات قواعد البيانات","إدارة مخططات"]}},"owner":"majiayu000","repo":"claude-skill-registry","repoPath":"majiayu000/claude-skill-registry","stars":0,"forks":0,"updatedAt":"2026-02-20T04:13:19.574Z","topics":[],"category":"community","skillMd":{"name":"db","description":"Gère le schéma Prisma et les migrations de Motivia. Utilise ce skill quand lutilisateur demande de modifier la base de données, ajouter une table, un champ, une relation, ou effectuer une migration. PostgreSQL avec Prisma ORM.","bodyPreview":"# Base de Données Motivia\n\n## Stack technique\n\n- **ORM**: Prisma\n- **BDD**: PostgreSQL (Neon)\n- **Fichier schema**: `prisma/schema.prisma`\n\n## Commandes Prisma\n\n```bash\n# Développement\npnpm prisma generate          # Générer le client Prisma\npnpm prisma migrate dev       # Créer et appliquer une migration\npnpm prisma migrate dev --name add_feature  # Migration nommée\npnpm prisma db push           # Push direct (dev seulement)\n\n# Production\npnpm prisma migrate deploy    # Appliquer les migrations","body":"# Base de Données Motivia\n\n## Stack technique\n\n- **ORM**: Prisma\n- **BDD**: PostgreSQL (Neon)\n- **Fichier schema**: `prisma/schema.prisma`\n\n## Commandes Prisma\n\n```bash\n# Développement\npnpm prisma generate          # Générer le client Prisma\npnpm prisma migrate dev       # Créer et appliquer une migration\npnpm prisma migrate dev --name add_feature  # Migration nommée\npnpm prisma db push           # Push direct (dev seulement)\n\n# Production\npnpm prisma migrate deploy    # Appliquer les migrations\n\n# Utilitaires\npnpm prisma studio            # Interface graphique\npnpm prisma db seed           # Exécuter le seed\npnpm prisma format            # Formater le schema\n```\n\n## Modèles existants\n\n### User (central)\n\n```prisma\nmodel User {\n  id                String             @id @default(cuid())\n  email             String             @unique\n  name              String             @default(\"\")\n  firstName         String?\n  lastName          String?\n  profileTitle      String?\n  localisation      String?\n  image             String?\n  emailVerified     Boolean            @default(false)\n  freeLetters       Int                @default(5)\n  keyAchievements   String[]\n  softSkills        String[]\n  technicalSkills   String[]\n  createdAt         DateTime           @default(now())\n  updatedAt         DateTime           @updatedAt\n\n  // Relations\n  accounts          Account[]\n  sessions          Session[]\n  apiKeys           ApiKey[]\n  experiences       Experience[]\n  degrees           Degree[]\n  links             Link[]\n  projects          Project[]\n  motivationLetters MotivationLetter[]\n  userCV            UserCV?\n}\n```\n\n### Entités métier\n\n| Modèle | Description | Relation |\n|--------|-------------|----------|\n| Experience | Expériences pro | User 1:N |\n| Degree | Diplômes | User 1:N |\n| Project | Projets portfolio | User 1:N |\n| Link | Liens sociaux | User 1:N |\n| MotivationLetter | Lettres générées | User 1:N |\n| UserCV | CV PDF uploadé | User 1:1 |\n| ApiKey | Clés API providers | User 1:N |\n\n### Auth (Better Auth)\n\n| Modèle | Description |\n|--------|-------------|\n| Account | Comptes OAuth/credentials |\n| Session | Sessions utilisateur |\n| Verification | Tokens de vérification |\n| Authenticator | WebAuthn |\n\n## Conventions de schéma\n\n### Champs obligatoires\n\n```prisma\nmodel NouveauModele {\n  id        String   @id @default(cuid())\n  // ... champs métier\n  userId    String\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n}\n```\n\n### Types courants\n\n| Usage | Type Prisma |\n|-------|-------------|\n| ID | `String @id @default(cuid())` |\n| Email | `String @unique` |\n| Texte court | `String` |\n| Texte long | `String` (pas de @db.Text nécessaire) |\n| Date | `DateTime` |\n| Date optionnelle | `DateTime?` |\n| Booléen | `Boolean @default(false)` |\n| Entier | `Int @default(0)` |\n| Liste de strings | `String[]` |\n\n### Relations\n\n```prisma\n// 1:N (User a plusieurs Experience)\nmodel User {\n  experiences Experience[]\n}\n\nmodel Experience {\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\n// 1:1 (User a un CV)\nmodel User {\n  userCV UserCV?\n}\n\nmodel UserCV {\n  userId String @unique\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n```\n\n### Enum\n\n```prisma\nenum ApiProvider {\n  OPENAI\n  GOOGLE\n  ANTHROPIC\n  MISTRAL\n  XAI\n}\n\nmodel ApiKey {\n  provider ApiProvider\n}\n```\n\n## Workflow modification de schéma\n\n### 1. Modifier le schéma\n\n```prisma\n// prisma/schema.prisma\nmodel User {\n  // Ajouter un nouveau champ\n  newField String?\n}\n```\n\n### 2. Créer la migration\n\n```bash\npnpm prisma migrate dev --name add_new_field\n```\n\n### 3. Mettre à jour le code\n\n- Server actions dans `app/actions/`\n- Schémas Zod dans `utils/schemas.ts`\n\n## Ajouter un nouveau modèle\n\n### 1. Définir le modèle\n\n```prisma\nmodel NewEntity {\n  id          String   @id @default(cuid())\n  name        String\n  description String?\n  isActive    Boolean  @default(true)\n  userId      String\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n  user        User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n}\n```\n\n### 2. Ajouter la relation dans User\n\n```prisma\nmodel User {\n  // ... existing fields\n  newEntities NewEntity[]\n}\n```\n\n### 3. Créer la migration\n\n```bash\npnpm prisma migrate dev --name add_new_entity\n```\n\n### 4. Créer les server actions\n\nCréer `app/actions/new-entity.ts` avec le pattern habituel.\n\n## Bonnes pratiques\n\n### Indexes\n\n```prisma\n@@index([userId])          // Toujours indexer les FK\n@@index([createdAt])       // Si tri fréquent\n@@unique([userId, name])   // Contrainte d''unicité\n```\n\n### Cascade\n\nToujours utiliser `onDelete: Cascade` pour les relations avec User afin de supprimer les données orphelines.\n\n### Migrations en production\n\n1. Tester localement avec `migrate dev`\n2. Commit des fichiers de migration\n3. En production: `migrate deploy` (via script build)\n\n## Checklist nouvelle table\n\n1. [ ] ID avec `@id @default(cuid())`\n2. [ ] `createdAt` et `updatedAt`\n3. [ ] `userId` avec relation et `onDelete: Cascade`\n4. [ ] `@@index([userId])`\n5. [ ] Relation ajoutée dans User\n6. [ ] Migration créée et testée\n7. [ ] Server actions créées\n8. [ ] Schéma Zod ajouté\n"},"lastSynced":"2026-03-01T07:22:06.245Z","agentAnalysis":{"suitability":{"en":"Perfect for Data Management Agents requiring robust PostgreSQL database operations with Prisma ORM integration.","zh":"非常适合需要强大的PostgreSQL数据库操作并集成Prisma ORM的数据管理代理。","ja":"PostgreSQLデータベース操作を強力に実行し、Prisma ORMを統合するデータ管理エージェントに最適です。","ko":"강력한 PostgreSQL 데이터베이스操作과 Prisma ORM 통합이 필요한 데이터 관리 에이전트에 적합합니다.","es":"Perfecto para Agentes de Gestión de Datos que requieren operaciones de base de datos PostgreSQL robustas con integración de Prisma ORM.","fr":"Parfait pour les agents de gestion de données nécessitant des opérations de base de données PostgreSQL robustes avec une intégration Prisma ORM.","de":"Perfekt für Data Management Agents, die robuste PostgreSQL-Datenbankoperationen mit Prisma-ORM-Integration erfordern.","pt":"Perfeito para Agentes de Gerenciamento de Dados que exigem operações robustas de banco de dados PostgreSQL com integração do Prisma ORM.","ru":"Идеально подходит для агентов управления данными, требующих надежных операций с базой данных PostgreSQL с интеграцией Prisma ORM.","ar":"مثالي لعمليات وكيل إدارة البيانات التي تتطلب عمليات قاعدة بيانات PostgreSQL قوية مع دمج Prisma ORM."},"recommendation":{"en":"Enables direct database interaction through Prisma ORM with PostgreSQL (Neon) support. Provides schema management, migration deployment, and database push capabilities for both development and production environments.","zh":"通过Prisma ORM启用PostgreSQL（Neon）支持的直接数据库交互。为开发和生产环境提供模式管理、迁移部署和数据库推送功能。","ja":"Prisma ORMを使用したPostgreSQL（Neon）サポートによる直接データベース操作を可能にします。開発環境と生産環境の両方でスキーマ管理、移行デプロイ、データベースプッシュ機能を提供します。","ko":"Prisma ORM을 사용하여 PostgreSQL(Neon) 지원에 대한 직접 데이터베이스 상호 작용을 활성화합니다. 개발 환경과生产 환경 모두에서 스키마 관리, 마이그레이션 배포 및 데이터베이스 푸시 기능을 제공합니다.","es":"Habilita la interacción directa con la base de datos a través de Prisma ORM con soporte para PostgreSQL (Neon). Proporciona administración de esquemas, implementación de migraciones y capacidades de envío de base de datos para entornos de desarrollo y producción.","fr":"Permet une interaction directe avec la base de données via Prisma ORM avec une prise en charge de PostgreSQL (Neon). Fournit une gestion de schémas, un déploiement de migrations et des capacités de publication de base de données pour les environnements de développement et de production.","de":"Ermöglicht die direkte Interaktion mit der Datenbank über Prisma ORM mit PostgreSQL- (Neon-) Unterstützung. Bietet Schema-Verwaltung, Migration-Deploying und Datenbank-Push-Funktionen für Entwicklung- und Produktionsumgebungen.","pt":"Permite interação direta com o banco de dados por meio do Prisma ORM com suporte a PostgreSQL (Neon). Fornece gerenciamento de esquema, implantação de migração e capacidades de push de banco de dados para ambientes de desenvolvimento e produção.","ru":"Позволяет осуществлять прямое взаимодействие с базой данных через Prisma ORM с поддержкой PostgreSQL (Neon). Обеспечивает управление схемой, развертывание миграции и возможности push-базы данных как для среды разработки, так и для производственной среды.","ar":"يسمح بالتفاعل المباشر مع قاعدة البيانات من خلال Prisma ORM مع دعم PostgreSQL (Neon). يوفر إدارة مخطط ، وتحديث التوزيع ، وقدرات دفع قاعدة البيانات لأنظمة التطوير والإنتاج."},"useCases":{"en":["Executing Prisma migrations in development","Deploying database migrations to production","Pushing schema changes directly to database","Generating Prisma client for database operations"],"zh":["在开发环境中执行Prisma迁移","将数据库迁移部署到生产环境","直接将模式更改推送到数据库","为数据库操作生成Prisma客户端"],"ja":["開発環境でPrisma移行を実行する","データベース移行を生産環境にデプロイする","スキーマの変更を直接データベースにプッシュする","データベース操作のためのPrismaクライアントを生成する"],"ko":["개발 환경에서 Prisma 마이그레이션을 실행하는 것","데이터베이스 마이그레이션을 생산 환경에 배포하는 것","스키마 변경을 직접 데이터베이스에 푸시하는 것","데이터베이스操作을 위한 Prisma 클라이언트를 생성하는 것"],"es":["Ejecutar migraciones de Prisma en desarrollo","Implementar migraciones de base de datos en producción","Enviar cambios de esquema directamente a la base de datos","Generar cliente de Prisma para operaciones de base de datos"],"fr":["Exécuter les migrations Prisma en développement","Déployer les migrations de base de données en production","Envoyer des modifications de schéma directement à la base de données","Générer un client Prisma pour les opérations de base de données"],"de":["Prisma-Migrationen in der Entwicklung ausführen","Datenbankmigrationen in der Produktion bereitstellen","Schemäänderungen direkt an die Datenbank übertragen","Prisma-Client für Datenbankoperationen generieren"],"pt":["Executar migrações do Prisma em desenvolvimento","Implantar migrações de banco de dados para produção","Fazer push de alterações de esquema diretamente para o banco de dados","Gerar cliente do Prisma para operações de banco de dados"],"ru":["Выполнение миграций Prisma в разработке","Развертывание миграций базы данных в производстве","Отправка изменений схемы напрямую в базу данных","Генерация клиента Prisma для операций с базой данных"],"ar":["تنفيذ هجرات Prisma في التطوير","نشر هجرات قاعدة البيانات إلى الإنتاج","دفع تغييرات مخطط مباشرة إلى قاعدة البيانات","توليد عميل Prisma لعملية قاعدة البيانات"]},"limitations":{"en":["PostgreSQL (Neon) specific only","Requires Prisma schema file","Database push recommended for development only"],"zh":["仅限PostgreSQL（Neon）","需要Prisma模式文件","建议仅在开发环境中使用数据库推送"],"ja":["PostgreSQL（Neon）のみ","Prismaスキーマファイルが必要","データベースプッシュは開発環境でのみ推奨"],"ko":["PostgreSQL(Neon)만 해당","Prisma 스키마 파일이 필요함","데이터베이스 푸시는 개발 환경에서만 권장"],"es":["Específico de PostgreSQL (Neon) solo","Requiere archivo de esquema de Prisma","Se recomienda envío de base de datos solo para desarrollo"],"fr":["Spécifique à PostgreSQL (Neon) uniquement","Nécessite un fichier de schéma Prisma","La publication de la base de données est recommandée uniquement pour le développement"],"de":["Nur spezifisch für PostgreSQL (Neon)","Benötigt Prisma-Schema-Datei","Datenbank-Push wird nur für die Entwicklung empfohlen"],"pt":["Específico apenas para PostgreSQL (Neon)","Exige arquivo de esquema do Prisma","Push de banco de dados recomendado apenas para desenvolvimento"],"ru":["Только для PostgreSQL (Neon)","Требует файла схемы Prisma","Push-базы данных рекомендуется только для разработки"],"ar":["محدد فقط لبرنامج PostgreSQL (Neon)","يتطلب ملف مخطط Prisma","دفع قاعدة البيانات موصى به فقط للتطوير"]},"version":3},"contentHash":"2d1e2b34174a9da5ab7a6451ec7365625668226ab46986c6204384f2c6383856","qualityScore":50}');
