INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Faizan1421/skills-Ai/react-native-best-practices', 'community', 'Faizan1421', 'skills-Ai', 'Faizan1421/skills-Ai', 'react-native-best-practices', 0, 0, 50, '2026-03-06T06:23:00.226Z', '2026-03-06T08:35:17.608Z', 'b0db741dc9bdcd5ca922d4c1026e231b16d7ac273b5fa281171e88072507f086', '{"id":"Faizan1421/skills-Ai/react-native-best-practices","name":"react-native-best-practices","description":{"en":"The react-native-best-practices skill provides a comprehensive performance optimization guide for React Native applications, covering JavaScript, Native, and bundling optimizations, benefiting developers and engineers.","zh":"React Native 优化最佳实践指南，涵盖 JavaScript、Native 和 bundling 优化","ja":"React Native 最適化ベストプラクティスガイド。JavaScript、Native、バンドリングの最適化をカバーしています","ko":"React Native 최적화 최고의 실践 가이드. JavaScript, Native, 번들링 최적화를 다룹니다","es":"Mejores prácticas para optimizar el rendimiento de aplicaciones React Native, cubriendo JavaScript, React y optimizaciones de bundling","fr":"Meilleures pratiques pour optimiser les performances des applications React Native, couvrant JavaScript, React et optimisations de bundling","de":"Beste Praktiken für die Leistungsoptimierung von React-Native-Anwendungen, umfassend JavaScript, React und Bundling-Optimierungen","pt":"Otimização de desempenho para aplicativos React Native, cobrindo JavaScript/React, nativo (iOS/Android) e otimizações de empacotamento","ru":"Оптимизация производительности для приложений React Native, покрывающая JavaScript/React, родной (iOS/Android) и оптимизации пакетирования","ar":"تحسين الأداء لتطبيقات React Native، تغطية JavaScript/React، الأصلية (iOS/Android) وتحسينات التعبئة"},"seo":{"title":{"en":"react-native-best-practices: Performance Optimization Gui...","zh":"React Native 优化最佳实践指南","ja":"React Native 最適化ベストプラクティスガイド","ko":"React Native 최적화 최고의 실践 가이드","es":"Gu