INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Faizan1421/skills-Ai/react-native-best-practices', 'react-native-best-practices', 'Faizan1421', 'skills-Ai', 'community', 'react-native-best-practices Faizan1421 skills-Ai community The react-native-best-practices skill provides a comprehensive performance optimization guide for React Native applications, covering JavaScript, Native, and bundling optimizations, benefiting developers and engineers. React Native 优化最佳实践指南，涵盖 JavaScript、Native 和 bundling 优化 React Native 最適化ベストプラクティスガイド。JavaScript、Native、バンドリングの最適化をカバーしています React Native 최적화 최고의 실践 가이드. JavaScript, Native, 번들링 최적화를 다룹니다 Mejores prácticas para optimizar el rendimiento de aplicaciones React Native, cubriendo JavaScript, React y optimizaciones de bundling Meilleures pratiques pour optimiser les performances des applications React Native, couvrant JavaScript, React et optimisations de bundling Beste Praktiken für die Leistungsoptimierung von React-Native-Anwendungen, umfassend JavaScript, React und Bundling-Optimierungen Otimização de desempenho para aplicativos React Native, cobrindo JavaScript/React, nativo (iOS/Android) e otimizações de empacotamento Оптимизация производительности для приложений React Native, покрывающая JavaScript/React, родной (iOS/Android) и оптимизации пакетирования تحسين الأداء لتطبيقات React Native، تغطية JavaScript/React، الأصلية (iOS/Android) وتحسينات التعبئة how to use react-native-best-practices react-native-best-practices setup guide react-native performance optimization techniques react-native-best-practices vs react-native-optimization react-native-best-practices install what is react-native-best-practices react-native-best-practices alternative react-native optimization guide react-native-best-practices tutorial react-native performance improvement React Native 优化 JavaScript 优化 Native 优化 bundling 优化 React Native 最佳实践 AIエージェント Provides Quick Pattern code snippets for immediate pattern matching Includes Quick Command shell commands for process and measurement Covers JavaScript and React performance optimizations Offers Native (iOS/Android) performance optimization techniques Includes bundling optimizations for improved app performance Follows a hybrid format for fast lookup and deep understanding react-native-best-practices is a set of guidelines and techniques for optimizing the performance of React Native applications, including JavaScript, Native, and bundling optimizations.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('wix/react-native-navigation/rnn-codebase', 'community', 'wix', 'react-native-navigation', 'wix/react-native-navigation', 'rnn-codebase', 13170, 2653, 49, '2026-03-05T07:50:20Z', '2026-03-06T06:24:08.377Z', '310e9e0ceb062a862c78f3d06071ad02e1a919093620fd36baa35133c4b2285f', '{"id":"wix/react-native-navigation/rnn-codebase","name":"rnn-codebase","description":{"en":"The rnn-codebase skill provides a complete native navigation solution for React Native, benefiting developers who need efficient navigation commands. It enables smooth navigation through JS/TS, TurboModule, and native iOS and Android layers.","zh":"rnn-codebase是一个React Native的原生导航解决方案，具有三层架构：JS/TS、TurboModule和iOS/Android原生层。","ja":"rnn-codebaseは、React Native用のネイティブナビゲーションソリューションです。JS/TS、TurboModule、iOS/Androidネイティブ層の3層アーキテクチャを備えています - AIエージェント","ko":"rnn-codebase는 React Native용 네이티브 네비게이션 솔루션으로, JS/TS, TurboModule 및 iOS/Android 네이티브 레이어의 3계층 아키텍처를 갖추고 있습니다.","es":"rnn-codebase es una solución de navegación nativa completa para React Native, con una arquitectura de tres capas que incluye JS/TS, TurboModule y capas nativas para iOS y Android.","fr":"rnn-codebase est une solution de navigation native complète pour React Native, avec une architecture à trois couches comprenant JS/TS, TurboModule et des couches natives pour iOS et Android.","de":"rnn-codebase ist eine komplette native Navigationslösung für React Native, mit einer dreischichtigen Architektur, die JS/TS, TurboModule und native Schichten für iOS und Android umfasst.","pt":"O RNN-Codebase é uma solução de navegação nativa para React Native, com três camadas que espelham umas às outras: JS/TS, TurboModule e nativo para iOS e Android.","ru":"RNN-Codebase — это полное решение для навигации в React Native, состоящее из трёх слоев: JS/TS, TurboModule и родной для iOS и Android, использующее ИИ Агенты","ar":"RNN-Codebase هو حل كامل للتنقل في React Native، يتكون من ثلاث طبقات تتطابق مع بعضها البعض: JS/TS و TurboModule و الأصلي لنظامي iOS و Android باستخدام أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"rnn-codebase: Native Navigation Setup Guide | AI Agent Skill","zh":"rnn-codebase导航解决方案设置指南","ja":"rnn-codebaseナビゲーションソリューションのベストプラクティス - AIエージェント","ko":"rnn-codebase 네비게이션 솔루션 구축 가이드","es":"Guía de Configuración de rnn-codebase para Navegación en ...","fr":"Guide de Mise en Place de rnn-codebase pour la Navigation...","de":"Einrichtungsleitfaden für rnn-codebase zur Navigation in ...","pt":"Guia de Configuração do RNN-Codebase para Navegação em Re...","ru":"Настройка RNN-Codebase для навигации в React Native: ИИ А...","ar":"دليل إعداد RNN-Codebase للتنقل في React Native باستخدام أ..."},"description":{"en":"Discover how to integrate rnn-codebase for seamless React Native navigation. Get started with our expert guide and optimize your mobile app''s user experience.","zh":"了解rnn-codebase的技术架构和导航功能，优化您的React Native应用","ja":"rnn-codebaseのナビゲーションソリューションを使用して、React Nativeアプリのパフォーマンスを向上させる - AIエージェント","ko":"rnn-codebase를 사용하여 React Native 애플리케이션의 네비게이션을 최적화하십시오","es":"Aprende a utilizar rnn-codebase para una navegación nativa completa en React Native. Descubre su arquitectura y características clave.","fr":"Découvrez comment utiliser rnn-codebase pour une navigation native complète dans React Native. Explorez son architecture et ses fonctionnalités clés.","de":"Erfahren Sie, wie Sie rnn-codebase für eine komplette native Navigation in React Native verwenden. Entdecken Sie seine Architektur und wichtigsten Funktionen.","pt":"Aprenda a configurar o RNN-Codebase para navegação em React Native com nossa guia passo a passo","ru":"Узнайте, как настроить RNN-Codebase для навигации в React Native с нашей пошаговой инструкцией и ИИ Агентами","ar":"تعلم كيفية إعداد RNN-Codebase للتنقل في React Native باستخدام أدوات الذكاء الاصطناعي و دليل خطوة بخطوة"},"definition":{"en":"rnn-codebase is a React Native navigation solution with a three-layer architecture, facilitating navigation commands through JS/TS, TurboModule bridge, and native iOS and Android modules.","zh":"rnn-codebase是一个用于React Native的原生导航解决方案","ja":"rnn-codebaseは、React Native用のネイティブナビゲーションソリューションです - AIエージェント","ko":"rnn-codebase는 React Native용 네이티브 네비게이션 솔루션입니다","es":"rnn-codebase es un conjunto de código para la navegación en aplicaciones de React Native, que proporciona una solución nativa completa.","fr":"rnn-codebase est un ensemble de code pour la navigation dans les applications React Native, qui fournit une solution native complète.","de":"rnn-codebase ist ein Codebasist für die Navigation in React-Native-Anwendungen, der eine komplette native Lösung bietet.","pt":"O que é RNN-Codebase? Uma solução de navegação nativa para React Native com arquitetura em três camadas","ru":"Что такое RNN-Codebase? Полное решение для навигации в React Native с трёхслойной архитектурой, использующее ИИ Агенты","ar":"ما هو RNN-Codebase؟ حل كامل للتنقل في React Native مع архيتيكتور في ثلاث طبقات باستخدام أدوات الذكاء الاصطناعي"},"features":{"en":["Utilizes TurboModule bridge for efficient communication between JS/TS and native modules","Supports navigation commands through `Navigation.push()` and `NativeCommandsSender.ts`","Employs `RNNTurboModule` for iOS and `NavigationTurboModule.kt` for Android","Processes navigation commands through a pipeline in `Commands.ts`","Integrates with `RNNCommandsHandler` and `RNNViewController` for native iOS navigation"],"zh":["JS/TS、TurboModule和iOS/Android原生层的三层架构","支持React Native导航命令，例如push和pop","使用TurboModule实现高性能的导航","兼容iOS和Android平台","提供Navigation.push()和Navigation.pop()等API"],"ja":["JS/TS、TurboModule、iOS/Androidネイティブ層の3層アーキテクチャ","React Nativeのナビゲーションコマンドをサポート、例：pushとpop","TurboModuleを使用して高性能のナビゲーションを実現","iOSとAndroidプラットフォームをサポート","Navigation.push()とNavigation.pop()などのAPIを提供"],"ko":["JS/TS, TurboModule 및 iOS/Android 네이티브 레이어의 3계층 아키텍처","React Native 네비게이션 명령어 지원, 예: push와 pop","TurboModule을 사용하여 고성능 네비게이션 구현","iOS 및 Android 플랫폼 지원","Navigation.push()와 Navigation.pop() 등의 API 제공"],"es":["Arquitectura de tres capas: JS/TS, TurboModule y capas nativas","Soporte para navegación en iOS y Android","Integración con React Native","Comandos de navegación personalizados","Procesamiento de comandos a través de Commands.ts y NativeCommandsSender.ts"],"fr":["Architecture à trois couches : JS/TS, TurboModule et couches natives","Prise en charge de la navigation sur iOS et Android","Intégration avec React Native","Commandes de navigation personnalisées","Traitement des commandes via Commands.ts et NativeCommandsSender.ts"],"de":["Dreischichtige Architektur: JS/TS, TurboModule und native Schichten","Unterstützung für die Navigation auf iOS und Android","Integration mit React Native","Benutzerdefinierte Navigationsbefehle","Verarbeitung von Befehlen über Commands.ts und NativeCommandsSender.ts"],"pt":["Arquitetura em três camadas: JS/TS, TurboModule e nativo para iOS e Android","Suporte a navegação com comandos como push e pop","Integração com TurboModule para melhor desempenho","Compatibilidade com React Native para iOS e Android","Código-fonte aberto e personalizável"],"ru":["Трёхслойная архитектура: JS/TS, TurboModule и родной для iOS и Android","Поддержка навигации с командами như push и pop, использующими ИИ Агенты","Интеграция с TurboModule для лучшей производительности","Совместимость с React Native для iOS и Android","Открытый и настраиваемый исходный код"],"ar":["هيكل ثلاثي الطبقات: JS/TS و TurboModule و الأصلي لنظامي iOS و Android","دعم التنقل مع أوامر مثل push و pop باستخدام أدوات الذكاء الاصطناعي","التكامل مع TurboModule لتحسين الأداء","التوافق مع React Native لنظامي iOS و Android","كود مفتوح و قابل للتعديل"]},"keywords":{"en":["how to use rnn-codebase","rnn-codebase setup guide","react native navigation solution","rnn-codebase alternative","rnn-codebase vs react navigation","native navigation for react native","rnn-codebase install","react native turbo module"],"zh":["rnn-codebase","React Native导航","原生导航解决方案","JS/TS","TurboModule","iOS","Android","导航命令","高性能导航"],"ja":["rnn-codebase","React Nativeナビゲーション","ネイティブナビゲーションソリューション","JS/TS","TurboModule","iOS","Android","ナビゲーションコマンド","高性能ナビゲーション","AIエージェント"],"ko":["rnn-codebase","React Native 네비게이션","네이티브 네비게이션 솔루션","JS/TS","TurboModule","iOS","Android","네비게이션 명령어","고성능 네비게이션","AI 툴"],"es":["rnn-codebase","navegación en React Native","solución de navegación nativa","arquitectura de tres capas","TurboModule","iOS","Android","React Native","navegación personalizada"],"fr":["rnn-codebase","navigation dans React Native","solution de navigation native","architecture à trois couches","TurboModule","iOS","Android","React Native","navigation personnalisée"],"de":["rnn-codebase","Navigation in React Native","native Navigationslösung","dreischichtige Architektur","TurboModule","iOS","Android","React Native","benutzerdefinierte Navigation"],"pt":["RNN-Codebase","navegação em React Native","solução de navegação nativa","React Native para iOS e Android","TurboModule","navegação com comandos","código-fonte aberto","personalização de navegação"],"ru":["RNN-Codebase","навигация в React Native","полное решение для навигации","React Native для iOS и Android","TurboModule","навигация с командами","открытый исходный код","настройка навигации","ИИ Агенты"],"ar":["RNN-Codebase","التنقل في React Native","حل كامل للتنقل","React Native لنظامي iOS و Android","TurboModule","التنقل مع أوامر","كود مفتوح","تخصيص التنقل","أدوات الذكاء الاصطناعي"]}},"owner":"wix","repo":"react-native-navigation","repoPath":"wix/react-native-navigation","stars":13170,"forks":2653,"updatedAt":"2026-03-05T07:50:20Z","topics":["hacktoberfest","navigation","navigator","react-native","react-native-navigation"],"category":"community","skillMd":{"name":"rnn-codebase","description":"Navigate and work with the react-native-navigation (RNN) codebase. Use when fixing bugs, adding features, tracing command flows, understanding options resolution, or working across JS/iOS/Android layers in this repo.","bodyPreview":"# React Native Navigation Codebase\n\n## Architecture Overview\n\nRNN has three layers that mirror each other:\n\n```\nJS/TS (src/)  →  TurboModule bridge  →  iOS native (ios/)\n                                     →  Android native (android/)\n```\n\nA navigation command (e.g. `push`) flows:\n1. `Navigation.push()` → `Commands.ts` → processing pipeline → `NativeCommandsSender.ts`\n2. TurboModule: `RNNTurboModule` (iOS) / `NavigationTurboModule.kt` (Android)\n3. iOS: `RNNCommandsHandler` → `RNNViewControllerF","body":"# React Native Navigation Codebase\n\n## Architecture Overview\n\nRNN has three layers that mirror each other:\n\n```\nJS/TS (src/)  →  TurboModule bridge  →  iOS native (ios/)\n                                     →  Android native (android/)\n```\n\nA navigation command (e.g. `push`) flows:\n1. `Navigation.push()` → `Commands.ts` → processing pipeline → `NativeCommandsSender.ts`\n2. TurboModule: `RNNTurboModule` (iOS) / `NavigationTurboModule.kt` (Android)\n3. iOS: `RNNCommandsHandler` → `RNNViewControllerFactory` → UIKit controllers\n4. Android: `Navigator` → `LayoutFactory` → View-based controllers (no Fragments)\n\nRead [ARCHITECTURE.md](../../ARCHITECTURE.md) for the full overview.\n\n## Key Cross-Layer Mappings\n\n### Layout Types → Native Controllers\n\n| JS Layout Type | iOS Controller | Android Controller |\n|----------------|---------------|-------------------|\n| `component` | `RNNComponentViewController` | `ComponentViewController` |\n| `stack` | `RNNStackController` (UINavigationController) | `StackController` |\n| `bottomTabs` | `RNNBottomTabsController` (UITabBarController) | `BottomTabsController` |\n| `sideMenu` | `RNNSideMenuViewController` (MMDrawerController) | `SideMenuController` (DrawerLayout) |\n| `topTabs` | `RNNTopTabsViewController` | `TopTabsController` (ViewPager) |\n| `splitView` | `RNNSplitViewController` | N/A (iOS only) |\n| `externalComponent` | `RNNExternalViewController` | `ExternalComponentViewController` |\n\n### Options → Presenters\n\nEach controller type has a Presenter that applies options to views:\n\n| iOS Controller | iOS Presenter | Android Presenter |\n|----------------|--------------|-------------------|\n| `RNNComponentViewController` | `RNNComponentPresenter` | `ComponentPresenter` |\n| `RNNStackController` | `RNNStackPresenter` + `TopBarPresenter` | `StackPresenter` |\n| `RNNBottomTabsController` | `RNNBottomTabsPresenter` | `BottomTabsPresenter` |\n| `RNNSideMenuViewController` | `RNNSideMenuPresenter` | `SideMenuPresenter` |\n\n### Events (same names both platforms)\n\n| Event | Trigger |\n|-------|---------|\n| `RNN.ComponentDidAppear` | Screen becomes visible |\n| `RNN.ComponentDidDisappear` | Screen hidden |\n| `RNN.NavigationButtonPressed` | TopBar button tap |\n| `RNN.BottomTabSelected` | Tab changed |\n| `RNN.ModalDismissed` | Modal dismissed |\n| `RNN.ScreenPopped` | Screen popped from stack |\n| `RNN.CommandCompleted` | Any command finished |\n\n## Where to Find Things\n\n### By task: \"I need to fix/change X\"\n\n| Task | JS File(s) | iOS File(s) | Android File(s) |\n|------|-----------|------------|----------------|\n| Command execution | `src/commands/Commands.ts` | `ios/RNNCommandsHandler.mm` | `react/NavigationTurboModule.kt` |\n| Layout creation | `src/commands/LayoutTreeParser.ts` | `ios/RNNViewControllerFactory.mm` | `options/LayoutFactory.java` |\n| Options processing | `src/commands/OptionsProcessor.ts` | `ios/RNNNavigationOptions.mm` | `options/Options.java` |\n| Options application | — | `ios/*Presenter.mm` | `viewcontrollers/*Presenter.java` |\n| TopBar | `src/interfaces/Options.ts` (TopBarOptions) | `ios/TopBarPresenter.mm`, `ios/RNNUIBarButtonItem.mm` | `views/stack/topbar/` |\n| Bottom tabs | `src/interfaces/Options.ts` (BottomTabsOptions) | `ios/RNNBottomTabsPresenter.mm` | `viewcontrollers/bottomtabs/` |\n| Modals | `src/commands/Commands.ts` | `ios/RNNModalManager.mm` | `viewcontrollers/modal/ModalStack.java` |\n| Overlays | `src/commands/Commands.ts` | `ios/RNNOverlayManager.mm` | `viewcontrollers/overlay/OverlayManager.kt` |\n| Animations | `src/interfaces/Options.ts` (AnimationOptions) | `ios/ScreenAnimationController.mm` | `viewcontrollers/stack/StackAnimator.kt` |\n| React view rendering | — | `ios/RNNReactView.mm` | `react/ReactView.java` |\n| Events to JS | `src/adapters/NativeEventsReceiver.ts` | `ios/RNNEventEmitter.mm` | `react/events/EventEmitter.java` |\n| Component registration | `src/components/ComponentRegistry.ts` | — | — |\n\n### By directory\n\n- **`src/`** — JS public API, commands, processing pipeline. See [src/ARCHITECTURE.md](../../src/ARCHITECTURE.md)\n- **`ios/`** — All Obj-C/C++ native code. See [ios/ARCHITECTURE.md](../../ios/ARCHITECTURE.md)\n- **`ios/TurboModules/`** — New architecture entry points (`RNNTurboModule`, `RNNTurboManager`, `RNNTurboCommandsHandler`)\n- **`android/src/main/java/com/reactnativenavigation/`** — All Java/Kotlin native code. See [android/ARCHITECTURE.md](../../android/ARCHITECTURE.md)\n- **`playground/`** — Demo app for development and E2E tests\n- **`playground/src/screens/`** — Test screens exercising every feature\n- **`playground/e2e/`** — Detox E2E tests\n\n## Options Resolution Order\n\nOptions are applied in ascending priority:\n1. Default options (from `Navigation.setDefaultOptions()`) — lowest priority\n2. Static options (from component class or `Navigation.registerComponent`)\n3. Options passed in the layout call (e.g. `push`, `setRoot`)\n4. `mergeOptions()` — runtime override, highest priority\n\n## JS Processing Pipeline (exact order)\n\n```\nAPI layout → OptionsCrawler.crawl() → LayoutProcessor.process()\n  → LayoutTreeParser.parse() → LayoutTreeCrawler.crawl()\n  → OptionsProcessor (colors, assets, custom) → NativeCommandsSender\n```\n\n## iOS Patterns\n\n- All controllers conform to `RNNLayoutProtocol`\n- `RNNBasePresenter` subclasses apply options — `applyOptionsOnInit:`, `applyOptions:`, `mergeOptions:resolvedOptions:`\n- Commands run on main thread (`RCTExecuteOnMainQueue`)\n- React views: `RNNReactView` wraps `RCTSurfaceHostingView` (new arch)\n- Overlays use separate `UIWindow` instances (`RNNOverlayWindow`)\n- `RNNReactComponentRegistry` caches React component instances\n\n## Android Patterns\n\n- View-based, NOT Fragment-based\n- All commands dispatched via `UiThread.post()`\n- `ViewController<T extends ViewGroup>` is the base — `createView()` is abstract\n- `ParentController` extends `ChildController` extends `ViewController`\n- Bottom tabs use `AHBottomNavigation` library\n- Three root layouts in `NavigationActivity`: rootLayout, modalsLayout, overlaysLayout\n- Tab attachment modes: `Together`, `OnSwitchToTab`, `AfterInitialTab`\n\n## Development Workflow\n\n### Playground app\n- `yarn start` — Metro bundler\n- `yarn xcode` — Open iOS project\n- `yarn studio` — Open Android project\n- `yarn pod-install` — Install iOS pods\n\n### Testing\n- `yarn test-js` — Jest unit tests\n- `yarn test-unit-ios` — iOS native unit tests (XCTest)\n- `yarn test-unit-android` — Android native unit tests (JUnit + Robolectric)\n- `yarn test-e2e-ios-ci` / `yarn test-e2e-android-ci` — Detox E2E tests\n\n### Building\n- `yarn prepare` — Builds `src/` → `lib/` (ESM + types)\n- Codegen config: `rnnavigation` in `package.json`\n\n## Common Gotchas\n\n- iOS uses UIKit subclasses (UINavigationController, UITabBarController); Android uses custom View hierarchy\n- `splitView` is iOS-only\n- Side menu: iOS uses MMDrawerController (3rd party); Android uses DrawerLayout (native)\n- Options that exist in JS types may not be implemented on both platforms — check the presenter\n- `passProps` are stored in JS `Store`, not sent to native (cleared before bridge crossing)\n- The `lib/` folder is generated — never edit it, edit `src/` instead\n"},"lastSynced":"2026-03-06T06:24:08.377Z","agentAnalysis":{"suitability":{"en":"Ideal for Mobile App Agents requiring seamless React Native navigation integration.","zh":"适用于需要无缝React Native导航集成的移动应用代理。","ja":"React Nativeナビゲーションのシームレスな統合を必要とするモバイルアプリエージェントに適しています。","ko":"무결점한 React Native 네비게이션 통합을 필요로 하는 모바일 앱 에이전트에 적합합니다.","es":"Ideal para Agentes de Aplicaciones Móviles que requieren una integración de navegación React Native sin problemas.","fr":"Idéal pour les agents d''applications mobiles nécessitant une intégration de navigation React Native transparente.","de":"Ideal für Mobile App-Agents, die eine nahtlose React Native Navigation-Integration benötigen.","pt":"Ideal para Agentes de Aplicativos Móveis que exigem integração de navegação React Native sem interrupções.","ru":"Идеально для Мобильных Приложений Агентов, требующих бесшовную интеграцию навигации React Native.","ar":"مثالي للوكلاء التطبيق المحمول الذين يتطلبون تكامل الملاحة React Native بدون انقطاع."},"recommendation":{"en":"Empowers agents to navigate through JS/TS, TurboModule, and native iOS and Android layers using React Native Navigation commands, enabling smooth processing pipelines via NativeCommandsSender.ts and RNNTurboModule.","zh":"赋予代理通过React Native Navigation命令导航JS/TS、TurboModule和原生iOS和Android层的能力，通过NativeCommandsSender.ts和RNNTurboModule实现平滑的处理流水线。","ja":"エージェントに、React Native Navigationコマンドを使用してJS/TS、TurboModule、およびネイティブのiOSとAndroidレイヤーをナビゲートする能力を与え、NativeCommandsSender.tsとRNNTurboModuleを介してスムーズな処理パイプラインを実現します。","ko":"에이전트에 React Native Navigation 명령을 사용하여 JS/TS, TurboModule 및 네이티브 iOS 및 Android 레이어를 탐색할 수 있는 능력을 부여하여 NativeCommandsSender.ts 및 RNNTurboModule을 통해 평滑한 처리 파이프라인을 구현합니다.","es":"Habilita a los agentes para navegar a través de JS/TS, TurboModule y capas nativas de iOS y Android utilizando comandos de navegación de React Native, lo que permite flujos de procesamiento suaves a través de NativeCommandsSender.ts y RNNTurboModule.","fr":"Permet aux agents de naviguer à travers JS/TS, TurboModule et les couches natives d''iOS et d''Android en utilisant des commandes de navigation React Native, ce qui permet des flux de traitement fluide via NativeCommandsSender.ts et RNNTurboModule.","de":"Ermächtigt Agenten, durch JS/TS, TurboModule und native iOS- und Android-Schichten zu navigieren, indem React Native Navigation-Befehle verwendet werden, was eine reibungslose Verarbeitung über NativeCommandsSender.ts und RNNTurboModule ermöglicht.","pt":"Habilita agentes a navegar por JS/TS, TurboModule e camadas nativas iOS e Android usando comandos de navegação React Native, permitindo pipelines de processamento suaves via NativeCommandsSender.ts e RNNTurboModule.","ru":"Наделяет агентов возможностью навигации по JS/TS, TurboModule и родным слоям iOS и Android с помощью команд навигации React Native, что обеспечивает гладкие потоки обработки через NativeCommandsSender.ts и RNNTurboModule.","ar":"يمنح الوكلاء القدرة على الملاحة خلال JS/TS و TurboModule وطبقات الأجهزة الأصلية لنظامي التشغيل iOS و Android باستخدام أوامر الملاحة React Native، مما يتيح خطوط أنابيب معالجة سلسة عبر NativeCommandsSender.ts و RNNTurboModule."},"useCases":{"en":["Implementing native navigation for React Native apps","Debugging navigation issues across JS/TS and native layers","Optimizing navigation performance using TurboModule"],"zh":["为React Native应用实现原生导航","跨JS/TS和原生层调试导航问题","使用TurboModule优化导航性能"],"ja":["React Nativeアプリのネイティブナビゲーションの実装","JS/TSとネイティブレイヤー間のナビゲーション問題のデバッグ","TurboModuleを使用したナビゲーションパフォーマンスの最適化"],"ko":["React Native 앱의 네이티브 네비게이션 구현","JS/TS 및 네이티브 레이어 간의 네비게이션 문제 디버깅","TurboModule을 사용한 네비게이션 성능 최적화"],"es":["Implementación de navegación nativa para aplicaciones React Native","Depuración de problemas de navegación en JS/TS y capas nativas","Optimización del rendimiento de la navegación utilizando TurboModule"],"fr":["Mise en œuvre de la navigation native pour les applications React Native","Débogage des problèmes de navigation entre JS/TS et les couches natives","Optimisation des performances de navigation à l''aide de TurboModule"],"de":["Implementierung der nativen Navigation für React Native-Apps","Debuggen von Navigationsproblemen über JS/TS und native Schichten","Optimierung der Navigationsleistung unter Verwendung von TurboModule"],"pt":["Implementar navegação nativa para aplicativos React Native","Depurar problemas de navegação em camadas JS/TS e nativas","Otimizar o desempenho da navegação usando TurboModule"],"ru":["Реализация родной навигации для приложений React Native","Отладка проблем навигации на уровнях JS/TS и родных слоев","Оптимизация производительности навигации с помощью TurboModule"],"ar":["تنفيذ الملاحة الأصلية لتطبيقات React Native","تصحيح أخطاء الملاحة عبر طبقات JS/TS والأجهزة الأصلية","تحسين أداء الملاحة باستخدام TurboModule"]},"limitations":{"en":["Requires React Native environment","Limited to iOS and Android platforms"],"zh":["需要React Native环境","仅限iOS和Android平台"],"ja":["React Native環境が必要","iOSとAndroidプラットフォームのみに限定"],"ko":["React Native 환경이 필요","iOS 및 Android 플랫폼만 해당"],"es":["Requiere entorno React Native","Limitado a plataformas iOS y Android"],"fr":["Nécessite un environnement React Native","Limité aux plateformes iOS et Android"],"de":["Benötigt React Native-Umgebung","Begrenzt auf iOS- und Android-Plattformen"],"pt":["Exige ambiente React Native","Limitado às plataformas iOS e Android"],"ru":["Требует среды React Native","Ограничен платформами iOS и Android"],"ar":["يتطلب بيئة React Native","محدود منصات iOS و Android"]},"version":4},"contentHash":"310e9e0ceb062a862c78f3d06071ad02e1a919093620fd36baa35133c4b2285f","qualityScore":49}');
