INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dartsim/dart/dart-contribute', 'dart-contribute', 'dartsim', 'dart', 'community', 'dart-contribute dartsim dart community collision-detection computer-animation constraint-dynamics dartpy dynamics gazebo inverse-kinematics kinematics lie-group mjcf multibody-dynamics physics-engine python-bindings rigid-body-dynamics robotics sdf simulation urdf The dart-contribute skill provides a C++20 physics engine for robotics and animation, supporting collision detection, constraints, and Python bindings. It benefits developers working with DART, gazebo, and urdf. DART-Contribute 是一个 C++20 物理引擎，为机器人和动画提供碰撞、约束和 Python 绑定 DART-Contribute は、C++20 物理エンジンで、ロボットとアニメーションに対する衝突、制約、および Python バインディングを提供します DART-Contribute는 로봇과 애니메이션을 위한 충돌, 제약 및 Python 바인딩을 제공하는 C++20 물리 엔진입니다 dart-contribute es un motor de física C++20 para robótica y animación con detección de colisiones y enlaces de Python dart-contribute est un moteur de physique C++20 pour la robotique et l''animation avec détection de collision et liens Python dart-contribute ist ein C++20-Physik-Motor für Robotik und Animation mit Kollisionsdetektion und Python-Bindings O DART Contribute é um fluxo de trabalho para contribuir com código para o motor de física DART, com recursos como detecção de colisão e vinculação Python. DART Contribute - это рабочий процесс для участия в разработке физического движка DART, с функциями обнаружения столкновений и Python-биндингов. أداة DART Contribute هو تدفق عمل للمساهمة في كود محرك الفيزياء DART، مع ميزات مثل كشف الاصطدام وربط بايثون. how to use dart-contribute dart-contribute vs gazebo dart-contribute setup guide what is dart-contribute dart-contribute alternative dart-contribute install C++20 physics engine python bindings for DART collision detection in robotics dart-contribute for animation DART-Contribute C++20 物理引擎 机器人开发 动画开发 碰撞检测 约束 Python 绑定 分支命名 代码风格指南 Supports branch naming conventions for feature and bug fix contributions Provides a contributing guide with documentation on onboarding and code style Includes Python bindings for easy integration with DART Enables collision detection and constraints for realistic simulations Works with gazebo and urdf for robotics and animation applications Follows a standard workflow for loading and contributing to DART dart-contribute is a C++20 physics engine skill for robotics and animation, featuring collision detection, constraints, and Python bindings for DART contributors.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dotCMS/core/triage', 'community', 'dotCMS', 'core', 'dotCMS/core', 'triage', 936, 481, 49, '2026-02-25T07:45:00Z', '2026-03-06T06:27:08.463Z', 'd0655da305e66634744aecb1ea3031d692afa7e7f7c6b89bd875291062995971', '{"id":"dotCMS/core/triage","name":"triage","description":{"en":"Triage is a Visual Headless Content Management System for Enterprises, enabling developers to automate issue management with GitHub and GraphQL. It benefits developers and enterprises seeking efficient content management.","zh":"AI Issue Triage 是一个用于自动化问题解决的工具，支持 GraphQL、Java 和开源技术。","ja":"AI エージェントの Triage は、問題解決を自動化するツールで、GraphQL、Java、オープンソース技術をサポートしています。","ko":"AI 이슈 트라이어지는 문제 해결을 자동화하는 도구로, GraphQL, Java, 오픈소스 기술을 지원합니다.","es":"Triage es un sistema de gestión de contenido headless para empresas que utiliza GitHub y GraphQL para optimizar los flujos de trabajo de desarrollo. Con Triage, los desarrolladores pueden automatizar tareas y mejorar la colaboración","fr":"Triage est un système de gestion de contenu headless pour les entreprises qui utilise GitHub et GraphQL pour optimiser les flux de travail de développement. Avec Triage, les développeurs peuvent automatiser des tâches et améliorer la collaboration","de":"Triage ist ein headless Content-Management-System für Unternehmen, das GitHub und GraphQL verwendet, um Entwicklungsworkflows zu optimieren. Mit Triage können Entwickler Aufgaben automatisieren und die Zusammenarbeit verbessern","pt":"O triage é uma ferramenta de gerenciamento de conteúdo headless para empresas, que executa verificações de ambiente e análise de argumentos para identificar problemas","ru":"Triage - это инструмент управления контентом headless для предприятий, который выполняет проверки окружения и анализ аргументов для выявления проблем","ar":"تراياج هو أداة إدارة المحتوى بدون رأس للشركات، التي تقوم بفحص البيئة وتحليل الحجج لتحديد المشكلات"},"seo":{"title":{"en":"Triage: Automated Issue Management Setup Guide | AI Agent...","zh":"AI Issue Triage 设置指南 - 基于云的内容管理系统","ja":"AI エージェントの Triage セットアップガイド - ヘッドレス CMS","ko":"AI 이슈 트라이어지 설정 가이드 - 클라우드 기반 콘텐츠 관리 시스템","es":"Configuración de Triage: Guía de Implementación para Desa...","fr":"Mise en place de Triage: Guide d''Installation pour les Dé...","de":"Triage-Setup: Einrichtungsleitfaden für Entwickler","pt":"Guia de Configuração do Triage para Desenvolvedores","ru":"Настройка Triage: ИИ Агенты для Разработчиков","ar":"إعداد تراياج للطورين: أدوات ذكاء اصطناعي"},"description":{"en":"Discover how to streamline issue triage with AI-powered automation - learn to set up and use triage with GitHub and GraphQL","zh":"了解如何设置 AI Issue Triage 以自动化问题解决。支持 GraphQL、Java 和开源技术。","ja":"AI エージェントの Triage を設定して問題解決を自動化する方法を学びます。GraphQL、Java、オープンソース技術をサポートしています。","ko":"AI 이슈 트라이어지를 설정하여 문제 해결을 자동화하는 방법을 알아보세요. GraphQL, Java, 오픈소스 기술을 지원합니다.","es":"Aprende a configurar Triage, el sistema de gestión de contenido headless para empresas, y optimiza tus flujos de trabajo de desarrollo con GitHub y GraphQL","fr":"Découvrez comment configurer Triage, le système de gestion de contenu headless pour les entreprises, et optimisez vos flux de travail de développement avec G...","de":"Erfahren Sie, wie Sie Triage, das headless Content-Management-System für Unternehmen, einrichten und Ihre Entwicklungsworkflows mit GitHub und GraphQL optimi...","pt":"Aprenda a configurar o triage para desenvolvedores com esse guia passo a passo, incluindo verificações de ambiente e análise de argumentos","ru":"Узнайте, как настроить Triage для разработчиков с помощью этого пошагового руководства, включая проверки окружения и анализ аргументов","ar":"تعلم كيفية إعداد تراياج للطورين مع هذا الدليل خطوة بخطوة، بما في ذلك فحص البيئة وتحليل الحجج"},"definition":{"en":"Triage is an AI-powered issue management system that automates environment checks, parses arguments, and extracts issue numbers using GitHub commands and GraphQL.","zh":"AI Issue Triage 是一个自动化问题解决的过程，用于识别和解决问题。","ja":"AI エージェントの Triage は、問題を自動的に識別して解決するプロセスです。","ko":"AI 이슈 트라이어지는 문제를 자동으로 식별하고 해결하는 프로세스입니다.","es":"Triage es un sistema de gestión de contenido headless que utiliza tecnologías como GitHub y GraphQL para automatizar tareas y mejorar la colaboración entre desarrolladores","fr":"Triage est un système de gestion de contenu headless qui utilise des technologies comme GitHub et GraphQL pour automatiser des tâches et améliorer la collaboration entre les développeurs","de":"Triage ist ein headless Content-Management-System, das Technologien wie GitHub und GraphQL verwendet, um Aufgaben zu automatisieren und die Zusammenarbeit zwischen Entwicklern zu verbessern","pt":"O que é triage? É uma ferramenta de gerenciamento de conteúdo headless que executa verificações de ambiente e análise de argumentos","ru":"Что такое Triage? Это инструмент управления контентом headless, который выполняет проверки окружения и анализ аргументов","ar":"ما هو تراياج؟ هو أداة إدارة المحتوى بدون رأس التي تقوم بفحص البيئة وتحليل الحجج"},"features":{"en":["Runs environment checks using GitHub commands (gh --version, gh auth status)","Parses arguments and extracts issue numbers using --issue <number> syntax","Utilizes GraphQL for querying repository data (gh repo view --json nameWithOwner)","Supports automated issue triage with Java and dotCMS integration","Performs checks to ensure the repository is dotCMS/core"],"zh":["支持 GraphQL 查询","基于 Java 的开源技术","自动化问题解决过程","集成 dotCMS/core 仓库","使用 gh 命令行工具进行环境检查"],"ja":["GraphQL クエリをサポート","Java ベースのオープンソース技術","問題解決プロセスを自動化","dotCMS/core リポジトリとの統合","gh コマンドラインツールを使用した環境チェック"],"ko":["GraphQL 쿼리 지원","Java 기반 오픈소스 기술","문제 해결 프로세스 자동화","dotCMS/core 저장소 통합","gh 명령줄 도구를 사용한 환경 확인"],"es":["Integración con GitHub para automatizar tareas","Uso de GraphQL para optimizar los flujos de trabajo de desarrollo","Compatibilidad con dotCMS y DXP","Soporte para Java y otros lenguajes de programación","Capacidad para parsear argumentos y obtener números de incidencia","Implementación de comandos de CLI para simplificar la configuración"],"fr":["Intégration avec GitHub pour automatiser des tâches","Utilisation de GraphQL pour optimiser les flux de travail de développement","Compatibilité avec dotCMS et DXP","Prise en charge de Java et d''autres langages de programmation","Capacité à parser des arguments et à obtenir des numéros d''incidence","Mise en œuvre de commandes de CLI pour simplifier la configuration"],"de":["Integration mit GitHub für die Automatisierung von Aufgaben","Verwendung von GraphQL für die Optimierung von Entwicklungsworkflows","Kompatibilität mit dotCMS und DXP","Unterstützung für Java und andere Programmiersprachen","Fähigkeit, Argumente zu parsen und Fehlerzahlen zu erhalten","Implementierung von CLI-Befehlen für die Vereinfachung der Konfiguration"],"pt":["Verificação de ambiente com gh --version e gh auth status","Análise de argumentos com --issue <number>","Suporte a GraphQL e Java","Integração com dotCMS/core","Execução de comandos bash para verificação de ambiente","Suporte a opensource"],"ru":["Проверка окружения с gh --version и gh auth status","Анализ аргументов с --issue <number>","Поддержка GraphQL и Java","Интеграция с dotCMS/core","Выполнение команд bash для проверки окружения","Поддержка opensource"],"ar":["فحص البيئة مع gh --version و gh auth status","تحليل الحجج مع --issue <number>","دعم GraphQL و Java","تكامل مع dotCMS/core","تشغيل أوامر bash لفحص البيئة","دعم opensource"]},"keywords":{"en":["how to use triage","what is triage","triage alternative","triage vs dotCMS","triage install guide","triage setup for GitHub","automated issue management with GraphQL","triage for enterprises","GitHub issue triage automation"],"zh":["AI Issue Triage","云内容管理系统","GraphQL","Java","开源技术","dotCMS/core","问题解决自动化"],"ja":["AI エージェントの Triage","ヘッドレス CMS","GraphQL","Java","オープンソース技術","dotCMS/core","問題解決自動化"],"ko":["AI 이슈 트라이어지","클라우드 콘텐츠 관리 시스템","GraphQL","Java","오픈소스 기술","dotCMS/core","문제 해결 자동화"],"es":["triage ai","herramientas de desarrollo","sistemas de gestión de contenido headless","github para desarrolladores","graphql en la empresa","dotcms y dxp","java para desarrolladores","automatización de tareas","colaboración en el desarrollo"],"fr":["triage ia","outils de développement","systèmes de gestion de contenu headless","github pour les développeurs","graphql dans l''entreprise","dotcms et dxp","java pour les développeurs","automatisation de tâches","collaboration dans le développement"],"de":["triage künstliche intelligenz","entwicklertools","headless content management systeme","github für entwickler","graphql im unternehmen","dotcms und dxp","java für entwickler","automatisierung von aufgaben","zusammenarbeit im entwicklungsteam"],"pt":["triage para desenvolvedores","guias de configuração","ferramentas de gerenciamento de conteúdo headless","dotCMS/core","GraphQL","Java","opensource","verificação de ambiente","análise de argumentos"],"ru":["Triage для разработчиков","руководства по настройке","инструменты управления контентом headless","dotCMS/core","GraphQL","Java","opensource","проверка окружения","анализ аргументов"],"ar":["تراياج للطورين","دلائل الإعداد","أدوات إدارة المحتوى بدون رأس","dotCMS/core","GraphQL","Java","opensource","فحص البيئة","تحليل الحجج"]}},"owner":"dotCMS","repo":"core","repoPath":"dotCMS/core","stars":936,"forks":481,"updatedAt":"2026-02-25T07:45:00Z","topics":["cloud","cms","content","content-management-system","dotcms","dxp","graphql","headless-cms","java","opensouce"],"category":"community","skillMd":{"name":"triage","description":"Triage GitHub issues using the AI triage pipeline. Fetches the next issue from the Needs Triage project column (or a specific issue), creates an agent team to validate completeness, detect duplicates, and research the codebase in parallel, then presents a triage proposal for human approval before posting anything to GitHub.","bodyPreview":"# AI Issue Triage\n\nYou are now the triage orchestrator. Follow these steps exactly.\n\n## Step 1: Environment check\n\nRun these checks. Stop with an error message if any fail:\n```bash\ngh --version\ngh auth status\ngh repo view --json nameWithOwner --jq ''.nameWithOwner''\n```\nThe repo must be `dotCMS/core`. If not, stop and tell the user to run this from the repo root.\n\n## Step 2: Parse arguments and get issue number\n\nArguments received: `$ARGUMENTS`\n\n**If `--issue <number>` is present**, extract the is","body":"# AI Issue Triage\n\nYou are now the triage orchestrator. Follow these steps exactly.\n\n## Step 1: Environment check\n\nRun these checks. Stop with an error message if any fail:\n```bash\ngh --version\ngh auth status\ngh repo view --json nameWithOwner --jq ''.nameWithOwner''\n```\nThe repo must be `dotCMS/core`. If not, stop and tell the user to run this from the repo root.\n\n## Step 2: Parse arguments and get issue number\n\nArguments received: `$ARGUMENTS`\n\n**If `--issue <number>` is present**, extract the issue number and skip to Step 3.\n\n**If no arguments**, fetch the next issue from the queue:\n```bash\ngh issue list --repo dotCMS/core --search \"is:issue no:assignee -label:\\\"Team : Falcon\\\",\\\"Team : Platform\\\",\\\"Team : Scout\\\",\\\"Team : Maintenance\\\",\\\"Team : Modernization\\\",\\\"Team : Enablement\\\",\\\"Flakey Test\\\" no:parent-issue -linked:pr state:open type:Task,Bug sort:updated-asc\" --json title,number,url --limit 1\n```\n\nExtract the `number` from the first result. If the array is empty, stop and tell the user: \"No issues need triage — queue is empty.\"\n\n## Step 3: Fetch the issue\n\n```bash\ngh issue view <number> --repo dotCMS/core --json number,title,body,labels,assignees,url,projectItems\n```\n\n## Step 4: Pre-flight check\n\nSkip and stop if:\n- Issue has any assignee\n- Issue has any label starting with `Team :`\n- Issue has a parent issue\n\n## Step 5: Create agent team and run three teammates IN PARALLEL\n\n### 5a. Create the team\n\n```\nTeamCreate(team_name: \"triage-<number>\", description: \"Triage pipeline for issue #<number>\")\n```\n\n### 5b. Create the task list\n\nCreate four tasks using `TaskCreate`. The team-router task must be blocked by the code-researcher task.\n\n- Task A: \"Validate issue #<number> completeness\" (assign to validator)\n- Task B: \"Detect duplicates for issue #<number>\" (assign to dup-detector)\n- Task C: \"Research codebase for issue #<number>\" (assign to researcher) — save the task ID\n- Task D: \"Route issue #<number> to team\" (assign to router) — set `addBlockedBy: [Task C ID]`\n\n### 5c. Spawn three teammates in a SINGLE message (parallel)\n\nYou MUST make THREE Task tool calls in a single response. Do not do any research yourself.\n\n**Teammate 1** — `subagent_type: issue-validator`, `team_name: \"triage-<number>\"`, `name: \"validator\"`\nPass the full issue content. Tell it to mark Task A as in_progress, complete it when done, and send results back to you via SendMessage.\n\n**Teammate 2** — `subagent_type: duplicate-detector`, `team_name: \"triage-<number>\"`, `name: \"dup-detector\"`\nPass issue number, title, body, and 3-5 keywords. Tell it to mark Task B as in_progress, complete it when done, and send results back to you via SendMessage.\n\n**Teammate 3** — `subagent_type: code-researcher`, `team_name: \"triage-<number>\"`, `name: \"researcher\"`\nPass issue number, title, full body, inferred type, and repo path (current working directory). Tell it to mark Task C as in_progress, complete it when done, and send results (especially the `Relevant Files` list) back to you via SendMessage.\n\nWait for all three teammates to send their results via SendMessage.\n\n### 5d. Spawn team-router after researcher completes\n\nOnce you receive the researcher''s SendMessage with the `Relevant Files` list, spawn the router teammate:\n\n**Teammate 4** — `subagent_type: team-router`, `team_name: \"triage-<number>\"`, `name: \"router\"`\nPass the `Relevant Files` list from the researcher''s message directly in the prompt. Do not ask it to search for files. Tell it to mark Task D as in_progress, complete it when done, and send the suggested team back to you via SendMessage.\n\nWait for the router to send its result via SendMessage.\n\n### 5e. Shut down teammates and delete team\n\nAfter all four teammates have reported their results:\n\n1. Send `SendMessage(type: \"shutdown_request\")` to all four teammates.\n2. Wait for shutdown confirmations.\n3. Call `TeamDelete()` to clean up the team.\n\n## Step 6: Synthesize and present proposal\n\nCombine the four results into a triage proposal. Use the `Suggested Team` from team-router, complexity from code-researcher.\n\nThe team-router always returns a team — use it as-is. Do not re-check the triage config or do your own routing.\n\nFor priority, map severity to these exact label names:\n- Critical / Show Stopper → `Priority : 1 Show Stopper`\n- High → `Priority : 2 High`\n- Medium / Average → `Priority : 3 Average`\n- Low → `Priority : 4 Low`\n\nShow the full proposal to the user and ask: **Approve? yes / no / edit**\n\n## Step 7: Execute on approval\n\nOn `yes`, run these steps in order:\n\n### 7a. Post the triage comment\n```bash\ngh issue comment <number> --repo dotCMS/core --body \"...\"\n```\n\n### 7b. Add labels (use exact label names from Step 6)\n```bash\ngh issue edit <number> --repo dotCMS/core --add-label \"Team : X\" --add-label \"Priority : X X X\"\n```\n\n### 7c. Add issue to the AI Triage Pipeline project and set status to Triaged\n\nFirst, get the project number from the repo variable:\n```bash\ngh variable get TRIAGE_PROJECT_NUMBER --repo dotCMS/core\n```\n\nThen get the item ID and field metadata using that number:\n```bash\ngh api graphql -f query=''\nquery {\n  organization(login: \"dotCMS\") {\n    projectV2(number: <TRIAGE_PROJECT_NUMBER>) {\n      id\n      fields(first: 20) {\n        nodes {\n          ... on ProjectV2SingleSelectField {\n            id\n            name\n            options { id name }\n          }\n        }\n      }\n      items(first: 5) { nodes { id } }\n    }\n  }\n}''\n```\n\nThen add the issue to the project:\n```bash\ngh api graphql -f query=''\nmutation {\n  addProjectV2ItemById(input: {\n    projectId: \"<project-id>\"\n    contentId: \"<issue-node-id>\"\n  }) {\n    item { id }\n  }\n}''\n```\n\nGet the issue node ID with:\n```bash\ngh issue view <number> --repo dotCMS/core --json id --jq ''.id''\n```\n\nThen set the Status field to \"Triaged\" using the item ID and field/option IDs discovered above:\n```bash\ngh api graphql -f query=''\nmutation {\n  updateProjectV2ItemFieldValue(input: {\n    projectId: \"<project-id>\"\n    itemId: \"<item-id>\"\n    fieldId: \"<status-field-id>\"\n    value: { singleSelectOptionId: \"<triaged-option-id>\" }\n  }) {\n    projectV2Item { id }\n  }\n}''\n```\n"},"lastSynced":"2026-03-06T06:27:08.463Z","agentAnalysis":{"suitability":{"en":"Perfect for GitHub-focused AI Agents needing automated issue management and GraphQL integration.","zh":"非常适合需要自动化问题管理和 GraphQL 集成的 GitHub 专注 AI Agents。","ja":"GitHub に焦点を当てた自動化された問題管理と GraphQL 統合を必要とする AI エージェントに最適です。","ko":"자동화된 문제 관리 및 GraphQL 통합이 필요한 GitHub 중심의 AI 에이전트에 적합합니다.","es":"Perfecto para agentes de inteligencia artificial centrados en GitHub que necesitan una gestión de problemas automatizada y una integración con GraphQL.","fr":"Parfait pour les agents d''intelligence artificielle axés sur GitHub nécessitant une gestion automatisée des problèmes et une intégration GraphQL.","de":"Perfekt für GitHub-fokussierte KI-Agents, die eine automatisierte Problemmeldungsverwaltung und eine GraphQL-Integration benötigen.","pt":"Perfeito para Agentes de IA focados no GitHub que precisam de gerenciamento de problemas automatizado e integração com GraphQL.","ru":"Идеально подходит для агентов ИИ, ориентированных на GitHub, которым требуется автоматизированное управление проблемами и интеграция с GraphQL.","ar":"مثالي للوكلاء الذكية التي تركز على GitHub وتحتاج إلى إدارة مشاكل تلقائية وتكامل مع GraphQL."},"recommendation":{"en":"Empowers agents to automate issue triage with GitHub and GraphQL, providing efficient content management and streamlined developer workflows through commands like `gh repo view` and `gh auth status`.","zh":"赋予代理人使用 GitHub 和 GraphQL 自动执行问题分类的能力，通过命令如 `gh repo view` 和 `gh auth status` 提供高效的内容管理和简化的开发者工作流程。","ja":"GitHub と GraphQL を使用して問題のトリアージを自動化するエージェントを強化し、`gh repo view` や `gh auth status` などのコマンドを使用して効率的なコンテンツ管理と開発者のワークフローを簡素化します。","ko":"에이전트가 GitHub 및 GraphQL을 사용하여 문제 분류를 자동화 할 수 있게 함으로써 `gh repo view` 및 `gh auth status`와 같은 명령을 통해 효율적인 콘텐츠 관리 및 개발자 워크플로를 간소화합니다.","es":"Habilita a los agentes a automatizar la clasificación de problemas con GitHub y GraphQL, proporcionando una gestión de contenido eficiente y flujos de trabajo de desarrollo optimizados a través de comandos como `gh repo view` y `gh auth status`.","fr":"Permet aux agents d''automatiser la classification des problèmes avec GitHub et GraphQL, offrant une gestion de contenu efficace et des flux de travail de développement rationalisés via des commandes comme `gh repo view` et `gh auth status`.","de":"Ermächtigt Agents, die Problemmeldungszuweisung mit GitHub und GraphQL zu automatisieren, wodurch eine effiziente Inhaltsverwaltung und optimierte Entwickler-Workflows durch Befehle wie `gh repo view` und `gh auth status` bereitgestellt werden.","pt":"Habilita agentes a automatizar a triagem de problemas com o GitHub e o GraphQL, fornecendo gerenciamento de conteúdo eficiente e fluxos de trabalho de desenvolvedores otimizados por meio de comandos como `gh repo view` e `gh auth status`.","ru":"Наделяет агентов возможностью автоматизировать распределение проблем с помощью GitHub и GraphQL, обеспечивая эффективное управление контентом и оптимизированные рабочие процессы разработчиков посредством команд như `gh repo view` и `gh auth status`.","ar":"يمنح الوكلاء القدرة على توفير تلقائي لتحديد الأولويات للمشاكل مع GitHub وGraphQL، وتوفير إدارة المحتوى الفعال وجداول عمل مطورين مجهزة من خلال أوامر مثل `gh repo view` و `gh auth status`."},"useCases":{"en":["Automating issue assignment with GitHub API","Parsing arguments for issue number extraction","Validating repository authenticity with `gh repo view --json nameWithOwner`"],"zh":["使用 GitHub API 自动分配问题","解析参数以提取问题编号","使用 `gh repo view --json nameWithOwner` 验证仓库的真实性"],"ja":["GitHub API を使用した問題の自動割り当て","問題番号の抽出のための引数の解析","`gh repo view --json nameWithOwner` を使用したリポジトリの真実性の検証"],"ko":["GitHub API를 사용한 문제 자동 할당","문제 번호 추출을 위한 인수 해석","`gh repo view --json nameWithOwner`를 사용한 저장소 진위성 검증"],"es":["Automatización de la asignación de problemas con GitHub API","Análisis de argumentos para la extracción del número de problema","Validación de la autenticidad del repositorio con `gh repo view --json nameWithOwner`"],"fr":["Automatisation de l''attribution des problèmes avec l''API GitHub","Analyse des arguments pour l''extraction du numéro de problème","Validation de l''authenticité du référentiel avec `gh repo view --json nameWithOwner`"],"de":["Automatisierung der Problemmeldungszuweisung mit GitHub API","Argumentanalyse zur Extraktion der Problemmeldungsnummer","Validierung der Repository-Authentizität mit `gh repo view --json nameWithOwner`"],"pt":["Automatizar a atribuição de problemas com GitHub API","Analisar argumentos para extração de número de problema","Validar a autenticidade do repositório com `gh repo view --json nameWithOwner`"],"ru":["Автоматизировать назначение проблем с помощью GitHub API","Парсить аргументы для извлечения номера проблемы","Проверить аутентичность репозитория с помощью `gh repo view --json nameWithOwner`"],"ar":["توفير تلقائي لتعيين المشاكل باستخدام GitHub API","تحليل الحجج لاستخراج رقم المشكلة","التحقق من صحة المخزن باستخدام `gh repo view --json nameWithOwner`"]},"limitations":{"en":["Requires GitHub authentication and authorization","Limited to repositories with GraphQL support","Must be run from the repository root directory"],"zh":["需要 GitHub 身份验证和授权","仅限于支持 GraphQL 的仓库","必须从仓库根目录运行"],"ja":["GitHub の認証と認可が必要","GraphQL をサポートするリポジトリのみ","リポジトリのルートディレクトリから実行する必要がある"],"ko":["GitHub 인증 및 권한 부여가 필요","GraphQL을 지원하는 저장소만 해당","저장소 루트 디렉토리에서 실행해야 함"],"es":["Requiere autenticación y autorización de GitHub","Limitado a repositorios con soporte GraphQL","Debe ejecutarse desde el directorio raíz del repositorio"],"fr":["Nécessite une authentification et une autorisation GitHub","Limité aux référentiels avec une prise en charge GraphQL","Doit être exécuté à partir du répertoire racine du référentiel"],"de":["Erfordert GitHub-Authentifizierung und Autorisierung","Begrenzt auf Repositorys mit GraphQL-Unterstützung","Muss im Repository-Stammdirectory ausgeführt werden"],"pt":["Requer autenticação e autorização do GitHub","Limitado a repositórios com suporte a GraphQL","Deve ser executado a partir do diretório raiz do repositório"],"ru":["Требует аутентификации и авторизации GitHub","Ограничен репозиториями с поддержкой GraphQL","Должно быть запущено из корневого каталога репозитория"],"ar":["يتطلب مصادقة وت�权ية GitHub","محدود بالمخازن التي تدعم GraphQL","يجب تشغيله من دليل الجذر للمخزن"]},"version":4},"contentHash":"d0655da305e66634744aecb1ea3031d692afa7e7f7c6b89bd875291062995971","qualityScore":49}');
