INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dotCMS/core/triage', 'triage', 'dotCMS', 'core', 'community', 'triage dotCMS core community cloud cms content content-management-system dotcms dxp graphql headless-cms java opensouce Triage is a Visual Headless Content Management System for Enterprises, enabling developers to automate issue management with GitHub and GraphQL. It benefits developers and enterprises seeking efficient content management. AI Issue Triage 是一个用于自动化问题解决的工具，支持 GraphQL、Java 和开源技术。 AI エージェントの Triage は、問題解決を自動化するツールで、GraphQL、Java、オープンソース技術をサポートしています。 AI 이슈 트라이어지는 문제 해결을 자동화하는 도구로, GraphQL, Java, 오픈소스 기술을 지원합니다. Triage es un sistema de gestión de contenido headless para empresas que utiliza GitHub y GraphQL para optimizar los flujos de trabajo de desarrollo. Con Triage, los desarrolladores pueden automatizar tareas y mejorar la colaboración Triage est un système de gestion de contenu headless pour les entreprises qui utilise GitHub et GraphQL pour optimiser les flux de travail de développement. Avec Triage, les développeurs peuvent automatiser des tâches et améliorer la collaboration Triage ist ein headless Content-Management-System für Unternehmen, das GitHub und GraphQL verwendet, um Entwicklungsworkflows zu optimieren. Mit Triage können Entwickler Aufgaben automatisieren und die Zusammenarbeit verbessern O triage é uma ferramenta de gerenciamento de conteúdo headless para empresas, que executa verificações de ambiente e análise de argumentos para identificar problemas Triage - это инструмент управления контентом headless для предприятий, который выполняет проверки окружения и анализ аргументов для выявления проблем تراياج هو أداة إدارة المحتوى بدون رأس للشركات، التي تقوم بفحص البيئة وتحليل الحجج لتحديد المشكلات how to use triage what is triage triage alternative triage vs dotCMS triage install guide triage setup for GitHub automated issue management with GraphQL triage for enterprises GitHub issue triage automation AI Issue Triage 云内容管理系统 GraphQL Java 开源技术 dotCMS/core 问题解决自动化 Runs environment checks using GitHub commands (gh --version, gh auth status) Parses arguments and extracts issue numbers using --issue <number> syntax Utilizes GraphQL for querying repository data (gh repo view --json nameWithOwner) Supports automated issue triage with Java and dotCMS integration Performs checks to ensure the repository is dotCMS/core Triage is an AI-powered issue management system that automates environment checks, parses arguments, and extracts issue numbers using GitHub commands and GraphQL.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jiangzhe/doradb/issue', 'community', 'jiangzhe', 'doradb', 'jiangzhe/doradb', 'issue', 118, 3, 49, '2026-03-03T07:39:29Z', '2026-03-06T06:30:35.962Z', 'cd787a5b967ed38c7dd8c525983e4150bfb6a4ab9c5e09ca4bc8c0cca14930df', '{"id":"jiangzhe/doradb/issue","name":"issue","description":{"en":"The issue skill automates GitHub issue operations for developers using DoraDB, ensuring efficient issue creation and validation of planning documents.","zh":"DoraDB 的 Issue 功能提供了 GitHub Issue 自动化的解决方案，通过脚本实现高效的Issue操作。","ja":"DoraDB の Issue 機能は、GitHub Issue の自動化ソリューションを提供し、スクリプトを使用して効率的な Issue 操作を実現します。","ko":"DoraDB의 이슈 기능은 GitHub 이슈 자동화 솔루션을 제공하며, 스크립트를 사용하여 효율적인 이슈操作을 thực現합니다.","es":"El Issue es una herramienta para automatizar operaciones de issue en GitHub, validando la ruta de documentos y ejecutando scripts de línea de comandos","fr":"L''Issue est un outil pour automatiser les opérations d''issue sur GitHub, en validant le chemin de document et en exécutant des scripts de ligne de commande","de":"Das Issue ist ein Tool zur Automatisierung von Issue-Operationen in GitHub, indem es den Dokumentenpfad überprüft und Kommandozeilen-Scripts ausführt","pt":"O Issue é uma ferramenta de automação do GitHub para DoraDB, que valida a criação de documentos e issues.","ru":"Issue - это инструмент автоматизации GitHub для DoraDB, который проверяет создание документов и проблем.","ar":"إشعار Issue هو أداة أتمتة جيثب لـ DoraDB ، التي تحقق من صحة إنشاء المستندات و الإشعارات."},"seo":{"title":{"en":"Issue: GitHub Issue Automation Setup Guide | AI Agent Skill","zh":"Issue Setup Guide: DoraDB GitHub Issue Automation","ja":"Issue セットアップガイド: DoraDB GitHub Issue Automation","ko":"이슈 설정 가이드: DoraDB GitHub 이슈 자동화","es":"Guía de configuración de Issue para DoraDB","fr":"Guide de configuration de Issue pour DoraDB","de":"Einrichtungsleitfaden für Issue in DoraDB","pt":"Guia de Configuração de Issue para DoraDB","ru":"Настройка ИИ Агента Issue для DoraDB","ar":"دليل إعداد إشعارIssue لـ DoraDB"},"description":{"en":"Automate GitHub issue operations with DoraDB using executable scripts. Learn how to validate planning documents and create issues efficiently.","zh":"使用 DoraDB 实现 GitHub Issue 自动化，提高开发效率。了解如何设置和使用 Issue 功能。","ja":"DoraDB を使用して GitHub Issue を自動化し、開発効率を向上させます。Issue 機能の設定と使用方法を学びましょう。","ko":"DoraDB를 사용하여 GitHub 이슈를 자동화하고 개발 효율을 높이세요. 이슈 기능 설정과 사용 방법을 알아보세요.","es":"Automatice operaciones de issue con scripts de GitHub y valide la ruta de documentos con herramientas de línea de comandos","fr":"Automatisez les opérations d''issue avec des scripts GitHub et validez le chemin de document avec des outils de ligne de commande","de":"Automatisieren Sie Issue-Operationen mit GitHub-Scripts und überprüfen Sie den Dokumentenpfad mit Kommandozeilen-Tools","pt":"Aprenda a configurar o Issue para DoraDB com scripts de automação do GitHub e validação de documentos","ru":"Узнайте, как настроить Issue для DoraDB с помощью скриптов автоматизации GitHub и валидации документов","ar":"تعرف على كيفية إعداد إشعار Issue لـ DoraDB باستخدام سكريبتات автоматизации جيثب و التحقق من صحة المستندات"},"definition":{"en":"Issue is a GitHub issue automation skill that uses executable scripts to validate planning document paths and create issues.","zh":"Issue 是 DoraDB 中用于 GitHub Issue 自动化的功能，通过脚本实现 Issue 操作。","ja":"Issue は、DoraDB における GitHub Issue 自動化機能で、スクリプトを使用して Issue 操作を実現します。","ko":"이슈는 DoraDB에서 GitHub 이슈 자동화를 위한 기능으로, 스크립트를 사용하여 이슈操作을 thực現합니다.","es":"Issue es una herramienta de automatización de operaciones de issue que utiliza scripts de GitHub y validación de documentos","fr":"Issue est un outil d''automatisation des opérations d''issue qui utilise des scripts GitHub et une validation de documents","de":"Issue ist ein Tool zur Automatisierung von Issue-Operationen, das GitHub-Scripts und Dokumentenvalidierung verwendet","pt":"O que é Issue? É uma ferramenta de automação do GitHub que valida a criação de documentos e issues para DoraDB.","ru":"Что такое Issue? Это инструмент автоматизации GitHub, который проверяет создание документов и проблем для DoraDB.","ar":"ما هو إشعار Issue؟هو أداة أتمتة جيثب التي تحقق من صحة إنشاء المستندات و الإشعارات لـ DoraDB."},"features":{"en":["Validates planning document paths using tools/issue.rs","Supports executable scripts for issue operations","Enforces document-first creation using accepted paths","Uses bash commands for script invocation","Accepts specific file formats, including docs/tasks/<6 digits>-<slug>.md"],"zh":["使用脚本实现 GitHub Issue 操作","支持文档优先创建","可验证计划文档路径","支持特定路径格式（docs/tasks/<6 digits>-<slug>.md 和 docs/rfcs/<4 digits>-<slug>.md）"],"ja":["スクリプトを使用して GitHub Issue 操作を実現","ドキュメント優先作成をサポート","計画文書パスの検証をサポート","特定のパス形式（docs/tasks/<6 digits>-<slug>.md と docs/rfcs/<4 digits>-<slug>.md）をサポート"],"ko":["스크립트를 사용하여 GitHub 이슈操作을 실現","문서優先作成을 지원","계획문서경로를検証","특定한 경로 형식（docs/tasks/<6 digits>-<slug>.md 와 docs/rfcs/<4 digits>-<slug>.md）을 지원"],"es":["Validación de ruta de documentos con herramientas de línea de comandos","Ejecución de scripts de GitHub para operaciones de issue","Compatibilidad con rutas de documentos en formato ''docs/tasks/<6 dígitos>-<slug>.md''","Compatibilidad con rutas de documentos en formato ''docs/rfcs/<4 dígitos>-<slug>.md''","Uso de scripts ejecutables para operaciones de issue","Evitación de prompts interactivos de ''gh''"],"fr":["Validation du chemin de document avec des outils de ligne de commande","Exécution de scripts GitHub pour les opérations d''issue","Compatibilité avec les chemins de documents au format ''docs/tasks/<6 chiffres>-<slug>.md''","Compatibilité avec les chemins de documents au format ''docs/rfcs/<4 chiffres>-<slug>.md''","Utilisation de scripts exécutables pour les opérations d''issue","Évitement des invites interactives de ''gh''"],"de":["Überprüfung des Dokumentenpfads mit Kommandozeilen-Tools","Ausführung von GitHub-Scripts für Issue-Operationen","Kompatibilität mit Dokumentenpfaden im Format ''docs/tasks/<6 Ziffern>-<slug>.md''","Kompatibilität mit Dokumentenpfaden im Format ''docs/rfcs/<4 Ziffern>-<slug>.md''","Verwendung von ausführbaren Skripten für Issue-Operationen","Vermeidung von interaktiven ''gh''-Prompts"],"pt":["Validação de documento antes da criação de issue","Uso de scripts de automação do GitHub","Suporte a criação de issues e documentos no formato docs/tasks/<6 digits>-<slug>.md","Suporte a criação de issues e documentos no formato docs/rfcs/<4 digits>-<slug>.md","Execução direta de scripts sem prompts interativos"],"ru":["Проверка документа перед созданием проблемы","Использование скриптов автоматизации GitHub","Поддержка создания проблем и документов в формате docs/tasks/<6 digits>-<slug>.md","Поддержка создания проблем и документов в формате docs/rfcs/<4 digits>-<slug>.md","Прямое выполнение скриптов без интерактивных подсказок"],"ar":["التحقق من صحة المستند قبل إنشاء الإشعار","استخدام سكريبتات أتمتة جيثب","دعم إنشاء الإشعارات و المستندات بصيغة docs/tasks/<6 digits>-<slug>.md","دعم إنشاء الإشعارات و المستندات بصيغة docs/rfcs/<4 digits>-<slug>.md","التشغيل المباشر للسكريبتات بدون إرشادات تفاعلية"]},"keywords":{"en":["how to use issue","issue setup guide","github issue automation","DoraDB alternative","issue vs github","issue install","what is issue","issue automation tool","github issue management"],"zh":["DoraDB","GitHub Issue","自动化","脚本","文档优先创建","计划文档路径","AIエージェント","Issue Setup"],"ja":["DoraDB","GitHub Issue","自動化","スクリプト","ドキュメント優先作成","計画文書パス","AIエージェント","Issue セットアップ"],"ko":["DoraDB","GitHub 이슈","자동화","스크립트","문서優先作成","계획문서경로","AI 에이전트","이슈 설정"],"es":[" Issue de GitHub","Automatización de issue","Validación de documentos","Scripts de línea de comandos","Herramientas de línea de comandos","DoraDB","Issue de DoraDB","Guía de configuración de Issue","Automatización de operaciones de issue"],"fr":["Issue de GitHub","Automatisation d''issue","Validation de documents","Scripts de ligne de commande","Outils de ligne de commande","DoraDB","Issue de DoraDB","Guide de configuration de Issue","Automatisation des opérations d''issue"],"de":["Issue von GitHub","Automatisierung von Issue","Überprüfung von Dokumenten","Kommandozeilen-Scripts","Kommandozeilen-Tools","DoraDB","Issue von DoraDB","Einrichtungsleitfaden für Issue","Automatisierung von Issue-Operationen"],"pt":["Issue DoraDB","automação do GitHub","validação de documentos","criação de issues","scripts de automação","DoraDB Issue setup","Guia de configuração de Issue"],"ru":["Issue DoraDB","автоматизация GitHub","проверка документов","создание проблем","скрипты автоматизации","Настройка Issue DoraDB","Руководство по настройке Issue"],"ar":["إشعار Issue DoraDB","أتمتة جيثب","التحقق من صحة المستندات","إنشاء الإشعارات","سكريبتات أتمتة","إعداد إشعار Issue DoraDB","دليل إعداد إشعار Issue"]}},"owner":"jiangzhe","repo":"doradb","repoPath":"jiangzhe/doradb","stars":118,"forks":3,"updatedAt":"2026-03-03T07:39:29Z","topics":[],"category":"community","skillMd":{"name":"issue","description":"Automate GitHub Issues lifecycle workflows with deterministic scripts. Use when creating, triaging, assigning, updating, linking, or closing issues in this repository, especially when converting planning documents in docs/tasks or docs/rfcs into trackable GitHub issues with required type labels and default priority handling.","bodyPreview":"# GitHub Issue Automation\n\nUse these scripts for all issue operations. Avoid interactive `gh` prompts.\nScripts are executable; invoke them directly (no `cargo +nightly -Zscript` prefix).\n\n## Enforce Document-First Creation\n\nBefore creating an issue, validate the planning document path:\n\n```bash\ntools/issue.rs validate-doc-path --path docs/tasks/000001-example.md\n```\n\nAccepted paths:\n- `docs/tasks/<6 digits>-<slug>.md`\n- `docs/rfcs/<4 digits>-<slug>.md`\n\nCreate operations must fail if no valid pl","body":"# GitHub Issue Automation\n\nUse these scripts for all issue operations. Avoid interactive `gh` prompts.\nScripts are executable; invoke them directly (no `cargo +nightly -Zscript` prefix).\n\n## Enforce Document-First Creation\n\nBefore creating an issue, validate the planning document path:\n\n```bash\ntools/issue.rs validate-doc-path --path docs/tasks/000001-example.md\n```\n\nAccepted paths:\n- `docs/tasks/<6 digits>-<slug>.md`\n- `docs/rfcs/<4 digits>-<slug>.md`\n\nCreate operations must fail if no valid planning document is provided.\n\nIf user input is id-only shorthand (for example `$issue create task 000047`), resolve id to exactly one document first:\n\n```bash\ntools/doc-id.rs search-by-id --kind task --id 000047 --scope open\n```\n\n## Create Issue From Planning Doc\n\n```bash\ntools/issue.rs create-issue-from-doc \\\n  --doc docs/tasks/000001-example.md \\\n  --labels \"type:task,priority:high\" \\\n  --assignee \"@me\"\n```\n\n`create-issue-from-doc` must use assignee `@me`.\n\n`--labels` is optional. If omitted, labels can be derived from planning-doc metadata:\n\n```md\nIssue Labels:\n- type:task\n- priority:high\n- codex\n```\n\nWhen both metadata and `--labels` are present:\n- CLI `type:*` and `priority:*` override metadata values.\n- `codex` is unioned from both sources.\n\nDefaults when no source provides a value:\n- task doc -> `type:task`\n- RFC doc -> `type:epic`\n- priority -> `priority:medium`\n\nFor child issues linked to an epic:\n\n```bash\ntools/issue.rs create-issue-from-doc \\\n  --doc docs/tasks/000002-subtask.md \\\n  --labels \"type:task\" \\\n  --assignee \"@me\" \\\n  --parent 42\n```\n\nThis script always uses `--body-file` to avoid body-length command issues.\nAllowed labels are strictly validated:\n- type: `type:doc`, `type:perf`, `type:feature`, `type:question`, `type:bug`, `type:chore`, `type:epic`, `type:task`\n- priority: `priority:low`, `priority:medium`, `priority:high`, `priority:critical`\n- special: `codex`\n\n## List Issues\n\n```bash\ntools/issue.rs list-issues --state open --assignee \"@me\" --limit 50\n```\n\nUse `--label` repeatedly for multiple labels:\n\n```bash\ntools/issue.rs list-issues --label type:task --label priority:high\n```\n\n## Update Issue\n\n```bash\ntools/issue.rs update-issue \\\n  --issue 123 \\\n  --add-label \"priority:high\" \\\n  --comment \"Refined acceptance criteria.\"\n```\n\nSupported update operations:\n- Add/remove labels\n- Add/remove assignees\n- Replace body (`--body` or `--body-file`)\n- Add comment\n\n## Close Issue\n\n```bash\ntools/issue.rs close-issue \\\n  --issue 123 \\\n  --comment \"Completed in PR #456.\"\n```\n\n## Resolve RFC Issue (Precheck + Explicit Close)\n\nUse RFC-specific resolve flow instead of direct close when closing RFC issues:\n\n```bash\ntools/issue.rs resolve-rfc \\\n  --doc docs/rfcs/0006-example.md\n```\n\nThis runs RFC resolve precheck only (no closure).\n\nTo close explicitly after precheck passes:\n\n```bash\ntools/issue.rs resolve-rfc \\\n  --doc docs/rfcs/0006-example.md \\\n  --issue 456 \\\n  --close \\\n  --comment \"RFC implemented and synchronized.\"\n```\n\nRules:\n- `resolve-rfc` must validate all sub-task/docs/backlog prechecks before closure.\n- No automatic issue closure from `rfc resolve`; closure requires explicit `--close`.\n- For legacy RFC docs without parseable phase tracking, use `--allow-legacy`.\n\n## Optional PR Bridge\n\nGenerate a canonical close-link snippet:\n\n```bash\ntools/issue.rs link-pr-guidance --issue 123\n```\n\nUse the snippet in PR body (for example: `Fixes #123`).\n\nOr create PR directly from current branch with default close-link body:\n\n```bash\ntools/issue.rs create-pr-from-branch --issue 123 --push --assignee \"@me\"\n```\n\nDefault body includes `Closes #123`.\nAssignee must be `@me`.\nIf `--title` is omitted, title is auto-derived from changed planning docs in `base...head`:\n- if both task and RFC docs are present, RFC is preferred.\n- if only RFC docs are present, use RFC title with a suitable type prefix (default `feat:`).\n- if only task docs are present, use task title with a suitable type prefix (default `chore:`).\n- explicit `--title` always overrides auto title.\nBefore creating PR, workflow must check for uncommitted changes.\nIf dirty changes exist, developer must explicitly decide to:\n1. manually commit selected changes, or\n2. ignore and proceed with explicit override:\n```bash\ntools/issue.rs create-pr-from-branch --issue 123 --push --assignee \"@me\" --allow-dirty\n```\n\n## Reference\n\nIf workflow details are needed, read:\n- `references/workflow.md`\n"},"lastSynced":"2026-03-06T06:30:35.962Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents requiring streamlined GitHub issue management and automation using DoraDB and bash scripts.","zh":"适合需要简化GitHub问题管理和使用DoraDB和bash脚本进行自动化的开发代理。","ja":"DoraDBとbashスクリプトを使用したGitHubの問題管理と自動化をストリームライン化する必要がある開発エージェントに最適です。","ko":"DoraDB와 bash 스크립트를 사용하여 GitHub 문제 관리 및 자동화를 스트림라인해야 하는 개발 에이전트에 적합합니다.","es":"Ideal para agentes de desarrollo que requieren una gestión de problemas de GitHub optimizada y automatización utilizando DoraDB y scripts de bash.","fr":"Idéal pour les agents de développement nécessitant une gestion de problèmes GitHub rationalisée et une automatisation utilisant DoraDB et des scripts bash.","de":"Ideal für Entwicklungsmittel, die eine optimierte GitHub-Problemmangement und Automatisierung unter Verwendung von DoraDB und bash-Skripten erfordern.","pt":"Ideal para Agentes de Desenvolvimento que exigem gestão de problemas do GitHub simplificada e automação usando DoraDB e scripts bash.","ru":"Идеально для агентов разработки, требующих упрощенного управления проблемами GitHub и автоматизации с помощью DoraDB и скриптов bash.","ar":"مثالي للوكلاء النمطية الذين يتطلبون إدارة مشاكل GitHub مبسطة وتأتمتية باستخدام DoraDB وبرامج bash."},"recommendation":{"en":"Empowers agents to automate GitHub issue creation and validation of planning documents using executable scripts, enforcing document-first creation with validated paths such as `docs/tasks/<6 digits>-<slug>.md` and `docs/rfcs/<4 digits>-<slug>.md`.","zh":"赋予代理人使用可执行脚本自动化GitHub问题创建和规划文档验证的能力，强制使用经过验证的路径（如`docs/tasks/<6 digits>-<slug>.md`和`docs/rfcs/<4 digits>-<slug>.md`）进行文档优先创建。","ja":"エージェントが実行可能なスクリプトを使用してGitHubの問題作成と計画書の検証を自動化できるようにし、`docs/tasks/<6 digits>-<slug>.md`および`docs/rfcs/<4 digits>-<slug>.md`などの検証されたパスを使用してドキュメント優先の作成を強制します。","ko":"에이전트가 실행 가능한 스크립트를 사용하여 GitHub 문제 생성 및 계획 문서의 유효성을 자동화할 수 있도록 하며, `docs/tasks/<6 digits>-<slug>.md` 및 `docs/rfcs/<4 digits>-<slug>.md`와 같은 검증된 경로를 사용하여 문서 우선 생성을 강제합니다.","es":"Habilita a los agentes a automatizar la creación y validación de problemas de GitHub y documentos de planificación utilizando scripts ejecutables, aplicando la creación de documentos en primer lugar con rutas validadas como `docs/tasks/<6 dígitos>-<slug>.md` y `docs/rfcs/<4 dígitos>-<slug>.md`.","fr":"Permet aux agents d''automatiser la création et la validation des problèmes GitHub et des documents de planification en utilisant des scripts exécutables, en appliquant la création de documents en premier lieu avec des chemins validés tels que `docs/tasks/<6 chiffres>-<slug>.md` et `docs/rfcs/<4 chiffres>-<slug>.md`.","de":"Ermächtigt die Mittel, die Erstellung und Validierung von GitHub-Problemen und Planungsdokumenten mithilfe von ausführbaren Skripten zu automatisieren, indem sie die Dokumentenerstellung in erster Linie mit validierten Pfaden wie `docs/tasks/<6 Ziffern>-<slug>.md` und `docs/rfcs/<4 Ziffern>-<slug>.md` durchsetzt.","pt":"Habilita os agentes a automatizar a criação e validação de problemas do GitHub usando scripts executáveis, aplicando a criação de documentos em primeiro lugar com caminhos validados como `docs/tasks/<6 digits>-<slug>.md` e `docs/rfcs/<4 digits>-<slug>.md`.","ru":"Позволяет агентам автоматизировать создание и проверку проблем GitHub с помощью исполняемых скриптов, обеспечивая создание документов в первую очередь с проверенными путями, такими как `docs/tasks/<6 digits>-<slug>.md` и `docs/rfcs/<4 digits>-<slug>.md`.","ar":"تمكين الوكلاء من تأتمتة إنشاء مشاكل GitHub والتحقق منها باستخدام البرامج النصية القابلة للتنفيذ، وتنفيذ إنشاء المستندات أولاً بمسارات تم التحقق منها مثل `docs/tasks/<6 digits>-<slug>.md` و `docs/rfcs/<4 digits>-<slug>.md`."},"useCases":{"en":["Automating issue creation with validated planning document paths","Validating planning document paths before issue creation","Enforcing document-first creation for GitHub issues"],"zh":["使用验证的规划文档路径自动化问题创建","在问题创建之前验证规划文档路径","强制使用验证的路径进行GitHub问题的文档优先创建"],"ja":["検証された計画書パスを使用して問題作成を自動化する","問題作成前に計画書パスを検証する","検証されたパスを使用してGitHubの問題のドキュメント優先作成を強制する"],"ko":["검증된 계획 문서 경로를 사용하여 문제 생성을 자동화하는 것","문제 생성 전에 계획 문서 경로를 검증하는 것","검증된 경로를 사용하여 GitHub 문제의 문서 우선 생성을 강제하는 것"],"es":["Automatización de la creación de problemas con rutas de documentos de planificación validadas","Validación de rutas de documentos de planificación antes de la creación de problemas","Aplicación de la creación de documentos en primer lugar para problemas de GitHub"],"fr":["Automatisation de la création de problèmes avec des chemins de documents de planification validés","Validation des chemins de documents de planification avant la création de problèmes","Application de la création de documents en premier lieu pour les problèmes GitHub"],"de":["Automatisierung der Problemerstellung mit validierten Planungsdokument-Pfaden","Validierung von Planungsdokument-Pfaden vor der Problemerstellung","Durchsetzung der Dokumentenerstellung in erster Linie für GitHub-Probleme"],"pt":["Automatizar a criação de problemas com caminhos de documentos de planejamento validados","Validar caminhos de documentos de planejamento antes da criação de problemas","Aplicar a criação de documentos em primeiro lugar para problemas do GitHub"],"ru":["Автоматизация создания проблем с проверенными путями документов планирования","Проверка путей документов планирования перед созданием проблем","Обеспечение создания документов в первую очередь для проблем GitHub"],"ar":["تأتمتة إنشاء المشاكل بمسارات وثائق التخطيط المُحَققة"," التحقق من مسارات وثائق التخطيط قبل إنشاء المشاكل","تطبيق إنشاء المستندات أولاً لمشاكل GitHub"]},"limitations":{"en":["Requires DoraDB setup","Limited to GitHub issue operations","Path validation required for issue creation"],"zh":["需要DoraDB设置","仅限GitHub问题操作","问题创建需要路径验证"],"ja":["DoraDBの設定が必要","GitHubの問題操作のみ","問題作成にはパス検証が必要"],"ko":["DoraDB 설정이 필요합니다.","GitHub 문제操作만 해당합니다.","문제 생성에는 경로 유효성이 필요합니다."],"es":["Requiere configuración de DoraDB","Limitado a operaciones de problemas de GitHub","Validación de rutas requerida para la creación de problemas"],"fr":["Nécessite une configuration de DoraDB","Limité aux opérations de problèmes GitHub","Validation de chemins requise pour la création de problèmes"],"de":["Benötigt DoraDB-Konfiguration","Begrenzt auf GitHub-Problemmoperationen","Pfadvalidierung erforderlich für die Problemerstellung"],"pt":["Exige configuração do DoraDB","Limitado a operações de problemas do GitHub","Validação de caminho necessária para criação de problemas"],"ru":["Требует настройки DoraDB","Ограничен операциями с проблемами GitHub","Требуется проверка пути для создания проблем"],"ar":["يتطلب إعداد DoraDB","محدود لعمليات مشاكل GitHub","التحقق من المسار مطلوب لإنشاء المشاكل"]},"version":4},"contentHash":"cd787a5b967ed38c7dd8c525983e4150bfb6a4ab9c5e09ca4bc8c0cca14930df","qualityScore":49}');
