INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jiangzhe/doradb/issue', 'issue', 'jiangzhe', 'doradb', 'community', 'issue jiangzhe doradb community The issue skill automates GitHub issue operations for developers using DoraDB, ensuring efficient issue creation and validation of planning documents. DoraDB 的 Issue 功能提供了 GitHub Issue 自动化的解决方案，通过脚本实现高效的Issue操作。 DoraDB の Issue 機能は、GitHub Issue の自動化ソリューションを提供し、スクリプトを使用して効率的な Issue 操作を実現します。 DoraDB의 이슈 기능은 GitHub 이슈 자동화 솔루션을 제공하며, 스크립트를 사용하여 효율적인 이슈操作을 thực現합니다. El Issue es una herramienta para automatizar operaciones de issue en GitHub, validando la ruta de documentos y ejecutando scripts de línea de comandos L''Issue est un outil pour automatiser les opérations d''issue sur GitHub, en validant le chemin de document et en exécutant des scripts de ligne de commande Das Issue ist ein Tool zur Automatisierung von Issue-Operationen in GitHub, indem es den Dokumentenpfad überprüft und Kommandozeilen-Scripts ausführt O Issue é uma ferramenta de automação do GitHub para DoraDB, que valida a criação de documentos e issues. Issue - это инструмент автоматизации GitHub для DoraDB, который проверяет создание документов и проблем. إشعار Issue هو أداة أتمتة جيثب لـ DoraDB ، التي تحقق من صحة إنشاء المستندات و الإشعارات. how to use issue issue setup guide github issue automation DoraDB alternative issue vs github issue install what is issue issue automation tool github issue management DoraDB GitHub Issue 自动化 脚本 文档优先创建 计划文档路径 AIエージェント Issue Setup Validates planning document paths using tools/issue.rs Supports executable scripts for issue operations Enforces document-first creation using accepted paths Uses bash commands for script invocation Accepts specific file formats, including docs/tasks/<6 digits>-<slug>.md Issue is a GitHub issue automation skill that uses executable scripts to validate planning document paths and create issues.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('stacklok/toolhive-studio/testing-with-api-mocks', 'community', 'stacklok', 'toolhive-studio', 'stacklok/toolhive-studio', 'testing-with-api-mocks', 116, 13, 49, '2026-03-03T12:59:48Z', '2026-03-06T06:30:43.963Z', '4d26b466a92a5b4c85451d67f7e3286bdbfd3a73cbd4b54ec72e9b2dba3fe3a8', '{"id":"stacklok/toolhive-studio/testing-with-api-mocks","name":"testing-with-api-mocks","description":{"en":"The testing-with-api-mocks skill enables developers to create automatic API mocks using MSW for efficient testing of AI agents, streamlining the development process for MCP servers and ToolHive applications.","zh":"本文介绍如何使用API Mocks进行测试，包括MSW的自动化schema-based mocks生成","ja":"APIモックを使用したテスト方法を紹介します。MSWの自動化schema-based mocks生成についても説明します","ko":"API Mocks를 사용한 테스트 방법을 소개합니다. MSW의 자동화 schema-based mocks 생성에 대해서도 설명합니다","es":"ToolHive permite probar y depurar Agentes de Inteligencia Artificial con API Mocks generados automáticamente. Aprenda a usar MSW para mejorar la seguridad y eficiencia.","fr":"ToolHive permet de tester et de déboguer les Outils d''Intelligence Artificielle avec des API Mocks générés automatiquement. Découvrez comment utiliser MSW pour améliorer la sécurité et l''efficacité.","de":"ToolHive ermöglicht das Testen und Debuggen von KI-Agents mit automatisch generierten API-Mocks. Erfahren Sie, wie Sie MSW verwenden, um die Sicherheit und Effizienz zu verbessern.","pt":"O skill ''testing-with-api-mocks'' permite testar aplicações com mocks de API automáticos, melhorando a eficiência do desenvolvimento","ru":"Навык ''testing-with-api-mocks'' позволяет тестировать приложения с помощью автоматически сгенерированных моков API, повышая эффективность разработки","ar":"المهارة ''testing-with-api-mocks'' تمكن من اختبار التطبيقات مع محاكاة واجهة برمجة التطبيقات الآلية، مما يحسن كفاءة التطوير"},"seo":{"title":{"en":"testing-with-api-mocks: API Mocking Setup Guide for AI Ag...","zh":"使用API Mocks进行测试Setup Guide","ja":"APIモックを使用したテストベストプラクティス","ko":"API Mocks를 사용한 테스트 설정 가이드","es":"Guía de configuración de pruebas con API Mocks para Agent...","fr":"Guide de mise en place des tests avec API Mocks pour les ...","de":"Einrichtungsleitfaden für Tests mit API-Mocks für KI-Agents","pt":"Guia de Configuração para Testes com Mocks de API","ru":"Настройка тестирования с помощью ИИ Агентов и Mock API","ar":"دليل إعداد الاختبارات مع محاكاة واجهة برمجة التطبيقات"},"description":{"en":"Learn how to set up API mocking with MSW and auto-generated schema-based mocks for seamless testing, try it now and optimize your AI agent development","zh":"学习如何使用MSW（Mock Service Worker）自动生成schema-based mocks进行API测试，提高测试效率","ja":"MSW（Mock Service Worker）を使用してschema-based mocksを自動生成し、APIテストを効率化する方法を学ぶ","ko":"MSW（Mock Service Worker）를 사용하여 schema-based mocks를 자동 생성하고 API 테스트를 효율화하는 방법을 알아보세요","es":"Aprenda a configurar pruebas con API Mocks para mejorar la seguridad y eficiencia de sus Agentes de Inteligencia Artificial con ToolHive y MSW","fr":"Découvrez comment configurer des tests avec API Mocks pour améliorer la sécurité et l''efficacité de vos Outils d''Intelligence Artificielle avec ToolHive et MSW","de":"Erfahren Sie, wie Sie Tests mit API-Mocks einrichten, um die Sicherheit und Effizienz Ihrer KI-Agents mit ToolHive und MSW zu verbessern","pt":"Aprenda a configurar testes com mocks de API usando MSW e schema-based mocks para melhorar a eficiência do desenvolvimento","ru":"Узнайте, как настроить тестирование с помощью ИИ Агентов и Mock API, используя MSW и schema-based mocks для повышения эффективности разработки","ar":"تعرف على كيفية إعداد الاختبارات مع محاكاة واجهة برمجة التطبيقات باستخدام MSW وschema-based mocks لتحسين كفاءة التطوير"},"definition":{"en":"testing-with-api-mocks is a technique using Mock Service Worker (MSW) for auto-generating schema-based API mocks in tests, simplifying AI agent development","zh":"API Mocks是使用MSW自动生成schema-based mocks的测试技术，用于提高API测试效率","ja":"APIモックは、MSWを使用してschema-based mocksを自動生成するテスト技術であり、APIテストの効率化に使用されます","ko":"API Mocks는 MSW를 사용하여 schema-based mocks를 자동 생성하는 테스트 기술로서 API 테스트 효율화를 위해 사용됩니다","es":"Pruebas con API Mocks son un método para simular llamadas a API y mejorar la seguridad y eficiencia de los Agentes de Inteligencia Artificial","fr":"Les tests avec API Mocks sont une méthode pour simuler des appels d''API et améliorer la sécurité et l''efficacité des Outils d''Intelligence Artificielle","de":"Tests mit API-Mocks sind eine Methode, um API-Aufrufe zu simulieren und die Sicherheit und Effizienz von KI-Agents zu verbessern","pt":"Testes com mocks de API são uma técnica de teste que simula chamadas de API para melhorar a eficiência do desenvolvimento","ru":"Тестирование с помощью моков API - это техника тестирования, которая имитирует вызовы API для повышения эффективности разработки","ar":"الاختبارات مع محاكاة واجهة برمجة التطبيقات هي تقنية اختبار تحاكي呼叫ات واجهة برمجة التطبيقات لتحسين كفاءة التطوير"},"features":{"en":["Uses MSW (Mock Service Worker) for automatic API mocking","Auto-generates schema-based mocks for API endpoints","Supports seamless testing of AI agents with MCP servers","Integrates with ToolHive for efficient application management","Enables automatic mock generation for unknown API endpoints","Works with TypeScript for robust and maintainable code"],"zh":["使用MSW自动生成schema-based mocks","支持自动化API测试","提高测试效率","支持多种API endpoint","集成ToolHive应用"],"ja":["MSWを使用してschema-based mocksを自動生成","自動化APIテストをサポート","テスト効率を向上","複数のAPIエンドポイントをサポート","ToolHiveアプリケーションと統合"],"ko":["MSW를 사용하여 schema-based mocks를 자동 생성","자동화 API 테스트를 지원","테스트 효율성을 향상","複数의 API 엔드포인트를 지원","ToolHive 애플리케이션과 통합"],"es":["API Mocks generados automáticamente con MSW","Soporte para pruebas de componentes que llaman a API","Mejora de la seguridad y eficiencia de los Agentes de Inteligencia Artificial","Integración con ToolHive para una gestión fácil de los servidores MCP","Compatibilidad con Linux, macOS y Windows"],"fr":["API Mocks générés automatiquement avec MSW","Prise en charge des tests de composants qui appellent des API","Amélioration de la sécurité et de l''efficacité des Outils d''Intelligence Artificielle","Intégration avec ToolHive pour une gestion facile des serveurs MCP","Compatibilité avec Linux, macOS et Windows"],"de":["API-Mocks automatisch mit MSW generiert","Unterstützung für Tests von Komponenten, die API-Aufrufe durchführen","Verbesserung der Sicherheit und Effizienz von KI-Agents","Integration mit ToolHive für eine einfache Verwaltung von MCP-Servern","Kompatibilität mit Linux, macOS und Windows"],"pt":["Uso de MSW (Mock Service Worker) para mockar chamadas de API","Geração automática de mocks de API com base em schema","Melhoria da eficiência do desenvolvimento com testes mais rápidos e confiáveis","Integração com aplicações que utilizam MCP (Model Context Protocol)","Suporte a múltiplas plataformas, incluindo Linux, macOS e Windows"],"ru":["Использование MSW (Mock Service Worker) для имитации вызовов API","Автоматическая генерация моков API на основе schema","Повышение эффективности разработки за счет более быстрых и надежных тестов","Интеграция с приложениями, использующими MCP (Model Context Protocol)","Поддержка нескольких платформ, включая Linux, macOS и Windows"],"ar":["استخدام MSW (Mock Service Worker) لمحاكاة呼叫ات واجهة برمجة التطبيقات","التوليد الآلي لمحاكاة واجهة برمجة التطبيقات مع आधار.schema","تحسين كفاءة التطوير من خلال الاختبارات الأسرع والأكثر موثوقية","التكامل مع التطبيقات التي تستخدم MCP (بروتوكول سياق النموذج)","دعم منصات متعددة، بما في ذلك Linux وmacOS وWindows"]},"keywords":{"en":["how to use testing-with-api-mocks","testing-with-api-mocks setup guide","MSW API mocking tutorial","AI agent testing best practices","testing-with-api-mocks vs traditional mocking","install testing-with-api-mocks","testing-with-api-mocks for MCP servers","ToolHive API mocking","testing-with-api-mocks alternative solutions","testing-with-api-mocks documentation"],"zh":["API Mocks","MSW","schema-based mocks","API测试","ToolHive","AIエージェント","自动化测试","测试效率"],"ja":["APIモック","MSW","schema-based mocks","APIテスト","ToolHive","AIエージェント","自動化テスト","テスト効率"],"ko":["API Mocks","MSW","schema-based mocks","API 테스트","ToolHive","AI 에이전트","자동화 테스트","테스트 효율성"],"es":["pruebas con API Mocks","Agentes de Inteligencia Artificial","seguridad de API","eficiencia de API","ToolHive","MSW","pruebas de componentes","servidores MCP"],"fr":["tests avec API Mocks","Outils d''Intelligence Artificielle","sécurité d''API","efficacité d''API","ToolHive","MSW","tests de composants","serveurs MCP"],"de":["Tests mit API-Mocks","KI-Agents","API-Sicherheit","API-Effizienz","ToolHive","MSW","Komponententests","MCP-Server"],"pt":["testes com mocks de API","MSW","schema-based mocks","desenvolvimento de software","MCP","Linux","macOS","Windows","testes automatizados"],"ru":["тестирование с помощью моков API","ИИ Агенты","MSW","schema-based mocks","разработка программного обеспечения","MCP","Linux","macOS","Windows","автоматизированное тестирование"],"ar":["الاختبارات مع محاكاة واجهة برمجة التطبيقات","وكلاء الذكاء الاصطناعي","MSW","محاكاة واجهة برمجة التطبيقات مع आधار.schema","تطوير البرمجيات","MCP","Linux","macOS","Windows","الاختبارات الآلية"]}},"owner":"stacklok","repo":"toolhive-studio","repoPath":"stacklok/toolhive-studio","stars":116,"forks":13,"updatedAt":"2026-03-03T12:59:48Z","topics":["agents","ai","ai-security","claude","continue","copilot","cursor","developer-tools","linux","macos","mcp","mcp-client","mcp-server","mcp-tools","model-context-protocol","security","typescript","windows"],"category":"community","skillMd":{"name":"testing-with-api-mocks","description":"Start here for all API mocking in tests. Covers auto-generation, fixtures, and when to use other skills. Required reading before creating, refactoring, or modifying any test involving API calls.","bodyPreview":"# Testing with API Mocks\n\n**This is the starting point for all API mocking in tests.** Read this skill first before working on any test that involves API calls.\n\nThis project uses MSW (Mock Service Worker) with auto-generated schema-based mocks. When writing tests for code that calls API endpoints, mocks are created automatically.\n\n## How It Works\n\n1. **Run a test** that triggers an API call (e.g., a component that fetches data)\n2. **Mock auto-generates** if no fixture exists for that endpoint\n3","body":"# Testing with API Mocks\n\n**This is the starting point for all API mocking in tests.** Read this skill first before working on any test that involves API calls.\n\nThis project uses MSW (Mock Service Worker) with auto-generated schema-based mocks. When writing tests for code that calls API endpoints, mocks are created automatically.\n\n## How It Works\n\n1. **Run a test** that triggers an API call (e.g., a component that fetches data)\n2. **Mock auto-generates** if no fixture exists for that endpoint\n3. **Fixture saved** to `renderer/src/common/mocks/fixtures/<endpoint>/<method>.ts`\n4. **Subsequent runs** use the saved fixture\n\nNo manual mock setup is required for basic tests.\n\n## Fixture Location\n\nFixtures are organized by endpoint path and HTTP method:\n\n```\nrenderer/src/common/mocks/fixtures/\n├── groups/\n│   ├── get.ts          # GET /api/v1beta/groups\n│   └── post.ts         # POST /api/v1beta/groups\n├── workloads/\n│   └── get.ts          # GET /api/v1beta/workloads\n├── workloads_name/\n│   └── get.ts          # GET /api/v1beta/workloads/:name\n└── ...\n```\n\nPath parameters like `:name` become `_name` in the directory name.\n\n## Fixture Structure\n\nGenerated fixtures use the `AutoAPIMock` wrapper with types from the OpenAPI schema:\n\n```typescript\n// renderer/src/common/mocks/fixtures/groups/get.ts\nimport type {\n  GetApiV1BetaGroupsResponse,\n  GetApiV1BetaGroupsData,\n} from ''@common/api/generated/types.gen''\nimport { AutoAPIMock } from ''@mocks''\n\nexport const mockedGetApiV1BetaGroups = AutoAPIMock<\n  GetApiV1BetaGroupsResponse,\n  GetApiV1BetaGroupsData\n>({\n  groups: [\n    { name: ''default'', registered_clients: [''client-a''] },\n    { name: ''research'', registered_clients: [''client-b''] },\n  ],\n})\n```\n\nThe second type parameter (`*Data`) provides typed access to request parameters (query, path, body) for conditional overrides.\n\n### Naming Convention\n\nExport names follow the pattern: `mocked` + HTTP method + endpoint path in PascalCase.\n\n- `GET /api/v1beta/groups` → `mockedGetApiV1BetaGroups`\n- `POST /api/v1beta/workloads` → `mockedPostApiV1BetaWorkloads`\n- `GET /api/v1beta/workloads/:name` → `mockedGetApiV1BetaWorkloadsByName`\n\n## Writing a Basic Test\n\nFor most tests, just render the component and the mock handles the rest:\n\n```typescript\nimport { render, screen, waitFor } from ''@testing-library/react''\n\nit(''displays groups from the API'', async () => {\n  render(<GroupsList />)\n\n  await waitFor(() => {\n    expect(screen.getByText(''default'')).toBeVisible()\n  })\n})\n```\n\nThe auto-generated mock provides realistic fake data based on the OpenAPI schema.\n\n## Customizing Fixture Data\n\nIf the auto-generated data doesn''t suit your test, edit the fixture file directly:\n\n```typescript\n// renderer/src/common/mocks/fixtures/groups/get.ts\nexport const mockedGetApiV1BetaGroups = AutoAPIMock<\n  GetApiV1BetaGroupsResponse,\n  GetApiV1BetaGroupsData\n>({\n  groups: [\n    { name: ''production'', registered_clients: [''claude-code''] }, // Custom data\n    { name: ''staging'', registered_clients: [] },\n  ],\n})\n```\n\nThis becomes the new default for all tests using this endpoint.\n\n## Regenerating a Fixture\n\nTo regenerate a fixture with fresh schema-based data:\n\n1. Delete the fixture file\n2. Run a test that calls that endpoint\n3. New fixture auto-generates\n\n```bash\nrm renderer/src/common/mocks/fixtures/groups/get.ts\npnpm test -- --run <test-file>\n```\n\n## Key Imports\n\n```typescript\n// Types for API responses and request parameters\nimport type {\n  GetApiV1BetaGroupsResponse,\n  GetApiV1BetaGroupsData,\n} from ''@common/api/generated/types.gen''\n\n// AutoAPIMock wrapper\nimport { AutoAPIMock } from ''@mocks''\n\n// Fixture mocks (for test-scoped overrides, see: testing-api-overrides skill)\nimport { mockedGetApiV1BetaGroups } from ''@mocks/fixtures/groups/get''\n```\n\n## 204 No Content Endpoints\n\nFor endpoints that return 204, create a minimal `AutoAPIMock` fixture and override the handler in each test:\n\n```typescript\n// renderer/src/common/mocks/fixtures/health/get.ts\nimport type {\n  GetHealthResponse,\n  GetHealthData,\n} from ''@common/api/generated/types.gen''\nimport { AutoAPIMock } from ''@mocks''\n\nexport const mockedGetHealth = AutoAPIMock<GetHealthResponse, GetHealthData>(\n  '''' as unknown as GetHealthResponse\n)\n```\n\nThen in tests, use `.overrideHandler()` to return the appropriate response:\n\n```typescript\nimport { mockedGetHealth } from ''@mocks/fixtures/health/get''\nimport { HttpResponse } from ''msw''\n\nit(''navigates on health check success'', async () => {\n  mockedGetHealth.overrideHandler(() => new HttpResponse(null, { status: 204 }))\n  // ...\n})\n\nit(''handles health check failure'', async () => {\n  mockedGetHealth.overrideHandler(() => HttpResponse.error())\n  // ...\n})\n```\n\n## Custom Mocks (Text/Plain Endpoints)\n\n**Custom mocks are only needed for text/plain endpoints.** The only current example is the logs endpoint:\n\n```typescript\n// renderer/src/common/mocks/customHandlers/index.ts\nexport const customHandlers = [\n  http.get(mswEndpoint(''/api/v1beta/workloads/:name/logs''), ({ params }) => {\n    const { name } = params\n    const logs = getMockLogs(name as string)\n    return new HttpResponse(logs, { status: 200 })\n  }),\n]\n```\n\nTo override the logs response in tests, use the exported `getMockLogs` mock:\n\n```typescript\nimport { getMockLogs } from ''@/common/mocks/customHandlers''\n\ngetMockLogs.mockReturnValueOnce(''Custom log content for this test'')\n```\n\n## Related Skills\n\n- **testing-api-overrides** - Test-scoped overrides and conditional responses for testing filters/params\n- **testing-api-assertions** - Verifying API calls for mutations (create/update/delete)\n"},"lastSynced":"2026-03-06T06:30:43.963Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing efficient testing with automatic API mocks using MSW","zh":"非常适合需要使用MSW进行自动API模拟的高效测试的AI代理","ja":"MSWを使用した自動APIモックによる効率的なテストが必要なAIエージェントに最適","ko":"MSW를 사용한 자동 API 모킹을 통한 효율적인 테스트가 필요한 AI 에이전트에게 적합","es":"Perfecto para Agentes de IA que necesitan pruebas eficientes con mocks de API automáticos utilizando MSW","fr":"Parfait pour les Agents IA qui ont besoin de tests efficaces avec des mocks d''API automatiques utilisant MSW","de":"Perfekt für KI-Agents, die effizientes Testen mit automatischen API-Mocks unter Verwendung von MSW benötigen","pt":"Perfeito para Agentes de IA que precisam de testes eficientes com mocks de API automáticos usando MSW","ru":"Идеально для агентов ИИ, которым необходимы эффективные тесты с автоматическими моками API, используя MSW","ar":"مثالي لعمليات إيه آي التي تحتاج إلى اختبارات فعالة مع ميكروبروجيكتات أوتوماتيكية باستخدام إم إس دبليو"},"recommendation":{"en":"Empowers agents to streamline development processes for MCP servers and ToolHive applications by creating auto-generated schema-based mocks using MSW, enabling efficient testing of API endpoints and reducing development time","zh":"赋予代理简化MCP服务器和ToolHive应用程序的开发过程的能力，通过使用MSW创建自动生成的基于模式的模拟，从而实现API端点的高效测试并减少开发时间","ja":"MSWを使用して自動生成されたスキーマベースのモックを作成することで、MCPサーバーとToolHiveアプリケーションの開発プロセスを合理化し、APIエンドポイントの効率的なテストを可能にし、開発時間を短縮するエージェントの能力を付与","ko":"MSW를 사용하여 자동 생성된 스키마 기반의 모킹을 생성함으로써 MCP 서버와 ToolHive 애플리케이션의 개발 프로세스를 간소화하고 API 엔드포인트의 효율적인 테스트를 가능하게 하며 개발 시간을 단축하는 에이전트의 능력을 부여","es":"Habilita a los agentes a optimizar los procesos de desarrollo para servidores MCP y aplicaciones ToolHive creando mocks basados en esquemas autogenerados utilizando MSW, lo que permite pruebas eficientes de puntos finales de API y reduce el tiempo de desarrollo","fr":"Permet aux agents de rationaliser les processus de développement pour les serveurs MCP et les applications ToolHive en créant des mocks basés sur des schémas autogénérés utilisant MSW, permettant ainsi des tests efficaces des points de terminaison d''API et réduisant le temps de développement","de":"Ermöglicht es den Agents, die Entwicklungsprozesse für MCP-Server und ToolHive-Anwendungen zu optimieren, indem sie automatisch generierte schema-basierte Mocks unter Verwendung von MSW erstellen, wodurch eine effiziente Überprüfung von API-Endpunkten ermöglicht und die Entwicklungszeit reduziert wird","pt":"Habilita os agentes a racionalizar os processos de desenvolvimento para servidores MCP e aplicações ToolHive, criando mocks baseados em esquemas auto-gerados usando MSW, permitindo testes eficientes de pontos de extremidade de API e reduzindo o tempo de desenvolvimento","ru":"Позволяет агентам оптимизировать процессы разработки для серверов MCP и приложений ToolHive, создавая автоматически сгенерированные на основе схемы моки, используя MSW, что обеспечивает эффективное тестирование конечных точек API и сокращает время разработки","ar":"يمكن للعمليات إمكانية تعزيز عمليات التطوير لأجهزة خادم إم سي بي وتطبيقات ToolHive من خلال إنشاء ميكروبروجيكتات أوتوماتيكية ذات مخططات مُولدة ذاتيًا باستخدام إم إس دبليو، مما يتيح اختبارًا فعالًا لنقاط النهاية.api ويتقلص وقت التطوير"},"useCases":{"en":["Automating API mock generation for tests","Streamlining development processes for MCP servers","Efficiently testing ToolHive applications with auto-generated mocks"],"zh":["自动化API模拟生成用于测试","简化MCP服务器的开发过程","使用自动生成的模拟高效地测试ToolHive应用程序"],"ja":["テスト用のAPIモックの自動化","MCPサーバーの開発プロセスの合理化","自動生成されたモックを使用してToolHiveアプリケーションの効率的なテスト"],"ko":["테스트를 위한 API 모킹의 자동화","MCP 서버의 개발 프로세스 간소화","자동 생성된 모킹을 사용한 ToolHive 애플리케이션의 효율적인 테스트"],"es":["Automatización de la generación de mocks de API para pruebas","Optimización de los procesos de desarrollo para servidores MCP","Pruebas eficientes de aplicaciones ToolHive con mocks autogenerados"],"fr":["Automatisation de la génération de mocks d''API pour les tests","Rationalisation des processus de développement pour les serveurs MCP","Tests efficaces des applications ToolHive avec des mocks autogénérés"],"de":["Automatisierung der Generierung von API-Mocks für Tests","Optimierung der Entwicklungsprozesse für MCP-Server","Effizientes Testen von ToolHive-Anwendungen mit automatisch generierten Mocks"],"pt":["Automatizar a geração de mocks de API para testes","Racionalizar os processos de desenvolvimento para servidores MCP","Testar aplicações ToolHive de forma eficiente com mocks auto-gerados"],"ru":["Автоматизировать генерацию моков API для тестов","Оптимизировать процессы разработки для серверов MCP","Эффективно тестировать приложения ToolHive с автоматически сгенерированными моками"],"ar":["أتمتة توليد محاكيات واجهة برمجة التطبيقات للاختبارات","تيسير عمليات التطوير لأجهزة خادم إم سي بي","اختبار تطبيقات ToolHive بشكل فعال مع محاكيات أوتوماتيكية المولد"]},"limitations":{"en":["Requires MSW (Mock Service Worker) setup","Limited to API endpoints with existing schema"],"zh":["需要MSW（模拟服务工作者）设置","仅限于具有现有模式的API端点"],"ja":["MSW（モックサービスワーカー）の設定が必要","既存のスキーマを持つAPIエンドポイントのみに限定"],"ko":["MSW(모의 서비스 워커) 설정이 필요","既存의 스키마를 갖는 API 엔드포인트에만 제한"],"es":["Requiere configuración de MSW (Mock Service Worker)","Limitado a puntos finales de API con esquema existente"],"fr":["Nécessite une configuration de MSW (Mock Service Worker)","Limité aux points de terminaison d''API avec un schéma existant"],"de":["Erfordert MSW (Mock Service Worker)-Einrichtung","Begrenzt auf API-Endpunkte mit vorhandenem Schema"],"pt":["Requer configuração do MSW (Mock Service Worker)","Limitado a pontos de extremidade de API com esquema existente"],"ru":["Требуется настройка MSW (Mock Service Worker)","Ограничен до конечных точек API с существующей схемой"],"ar":["يتطلب إعداد إم إس دبليو (عامل خدمة المحاكاة)","محدود بنقاط النهاية لبروتوكول اتصال التطبيقات مع مخطط موجود"]},"version":4},"contentHash":"4d26b466a92a5b4c85451d67f7e3286bdbfd3a73cbd4b54ec72e9b2dba3fe3a8","qualityScore":49}');
DELETE FROM skills_fts WHERE id = 'stacklok/toolhive-studio/testing-with-api-mocks';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('stacklok/toolhive-studio/testing-with-api-mocks', 'testing-with-api-mocks', 'stacklok', 'toolhive-studio', 'community', 'testing-with-api-mocks stacklok toolhive-studio community agents ai ai-security claude continue copilot cursor developer-tools linux macos mcp mcp-client mcp-server mcp-tools model-context-protocol security typescript windows The testing-with-api-mocks skill enables developers to create automatic API mocks using MSW for efficient testing of AI agents, streamlining the development process for MCP servers and ToolHive applications. 本文介绍如何使用API Mocks进行测试，包括MSW的自动化schema-based mocks生成 APIモックを使用したテスト方法を紹介します。MSWの自動化schema-based mocks生成についても説明します API Mocks를 사용한 테스트 방법을 소개합니다. MSW의 자동화 schema-based mocks 생성에 대해서도 설명합니다 ToolHive permite probar y depurar Agentes de Inteligencia Artificial con API Mocks generados automáticamente. Aprenda a usar MSW para mejorar la seguridad y eficiencia. ToolHive permet de tester et de déboguer les Outils d''Intelligence Artificielle avec des API Mocks générés automatiquement. Découvrez comment utiliser MSW pour améliorer la sécurité et l''efficacité. ToolHive ermöglicht das Testen und Debuggen von KI-Agents mit automatisch generierten API-Mocks. Erfahren Sie, wie Sie MSW verwenden, um die Sicherheit und Effizienz zu verbessern. O skill ''testing-with-api-mocks'' permite testar aplicações com mocks de API automáticos, melhorando a eficiência do desenvolvimento Навык ''testing-with-api-mocks'' позволяет тестировать приложения с помощью автоматически сгенерированных моков API, повышая эффективность разработки المهارة ''testing-with-api-mocks'' تمكن من اختبار التطبيقات مع محاكاة واجهة برمجة التطبيقات الآلية، مما يحسن كفاءة التطوير how to use testing-with-api-mocks testing-with-api-mocks setup guide MSW API mocking tutorial AI agent testing best practices testing-with-api-mocks vs traditional mocking install testing-with-api-mocks testing-with-api-mocks for MCP servers ToolHive API mocking testing-with-api-mocks alternative solutions testing-with-api-mocks documentation API Mocks MSW schema-based mocks API测试 ToolHive AIエージェント 自动化测试 测试效率 Uses MSW (Mock Service Worker) for automatic API mocking Auto-generates schema-based mocks for API endpoints Supports seamless testing of AI agents with MCP servers Integrates with ToolHive for efficient application management Enables automatic mock generation for unknown API endpoints Works with TypeScript for robust and maintainable code testing-with-api-mocks is a technique using Mock Service Worker (MSW) for auto-generating schema-based API mocks in tests, simplifying AI agent development');
