INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('bartstc/vite-ts-react-template/playwright-page-objects', 'playwright-page-objects', 'bartstc', 'vite-ts-react-template', 'community', 'playwright-page-objects bartstc vite-ts-react-template community chakra-ui claude-code copilot github-actions i18next msw playwright pnpm react react-query react-router-v7 reactjs spa-template storybook template typescript vite vitest xstate zustand playwright-page-objects provides a basic dev setup for Single Page Application development, utilizing tools like Playwright, React, and Vite. It benefits developers by providing a demo app and good practices for E2E testing. Playwright Page Objects 提供现代 POM 架构，使用 fixtures 模式和基于角色的定位器 Playwright Page Objects は、E2E テストアーキテクチャを設定するための基本的な開発セットアップを提供する Playwright Page Objects 는 유지보수 가능한 페이지 객체를 만들고 재사용 가능한 컴포넌트 수준의 테스트 추상을 작성하는 데 도움이 됩니다 Playwright Page Objects proporciona una arquitectura moderna de POM utilizando patrones de fixtures y composición para pruebas E2E Playwright Page Objects fournit une architecture POM moderne utilisant des modèles de fixtures et de composition pour les tests E2E Playwright Page Objects bietet eine moderne POM-Architektur mit Fixtures-Mustern und Komposition für E2E-Tests O Playwright Page Objects é uma ferramenta para desenvolvedores que fornece uma arquitetura moderna de POM usando o padrão de fixtures do Playwright. Playwright Page Objects — это инструмент для разработчиков, который обеспечивает современную архитектуру POM, использующую шаблон fixtures от Playwright. أداة Playwright Page Objects هي أداة للبرمجة توفر بنية تحتية حديثة لنمط Objects Page باستخدام نمط الإصلاح من Playwright. how to use playwright-page-objects playwright-page-objects setup guide playwright-page-objects vs Cypress playwright-page-objects install what is playwright-page-objects playwright-page-objects alternative playwright-page-objects tutorial playwright-page-objects react integration playwright-page-objects vitest support Playwright Page Objects AIエージェント E2E 测试 POM 架构 React TypeScript Storybook Vitest Implements modern POM architecture using Playwright''s fixtures pattern Utilizes composition over inheritance for maintainable test code Employs role-based locators for efficient element identification Supports on-demand instantiation via fixtures Enables reusable component-level test abstractions Integrates with tools like React, Vite, and Vitest for seamless testing playwright-page-objects is a project that implements modern Page Object Model (POM) architecture using Playwright''s fixtures pattern for efficient E2E testing.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Masked-Kunsiquat/crm-orbit2/ui-designer', 'community', 'Masked-Kunsiquat', 'crm-orbit2', 'Masked-Kunsiquat/crm-orbit2', 'ui-designer', 0, 0, 49, '2026-03-07T01:49:01.608Z', '2026-03-07T02:13:06.182Z', '01470ec0315f3641ec352e61ccd6ab51642511847094f5f91486720ef1c4732a', '{"id":"Masked-Kunsiquat/crm-orbit2/ui-designer","name":"ui-designer","description":{"en":"The ui-designer skill creates clear, usable, and aesthetically coherent interfaces balancing form, function, and accessibility for AI agents. It benefits developers and designers by providing a context-driven design approach.","zh":"UI 设计师技能用于创建清晰、易用且美观的界面，平衡形式、功能和可访问性。","ja":"UI デザイナー スキルは、フォーム、機能、そしてアクセシビリティをバランスさせた UI を設計するために使用されます。","ko":"UI 디자이너 스킬은 사용자 인터페이스 디자인을 위한 가이드입니다. 사용자 nhu cầu와 플랫폼 규칙을 고려하여 디자인합니다.","es":"UI Designer crea interfaces de usuario claras, usables y estéticamente coherentes, equilibrando forma, función y accesibilidad","fr":"UI Designer conçoit des interfaces utilisateur claires, utilisables et esthétiquement cohérentes, en équilibrant forme, fonction et accessibilité","de":"UI Designer erstellt benutzerfreundliche Schnittstellen, die Form, Funktion und Zugänglichkeit ausbalancieren","pt":"O UI Designer é uma habilidade que cria interfaces claras e coerentes, considerando forma, função e acessibilidade. Saiba como configurá-lo corretamente","ru":"ИИ Агент UI Designer - это навык, который создает четкие и согласованные интерфейсы, учитывая форму, функцию и доступность. Узнайте, как его настроить","ar":"مصمم واجهة المستخدم هو مهارة تقوم بإنشاء واجهات واضحة ومتناسقة، مع مراعاة الشكل والوظيفة والتوافق. تعرف على كيفية إعداده بشكل صحيح"},"seo":{"title":{"en":"ui-designer: Context-Driven Design Setup Guide | AI Agent...","zh":"UI 设计师技能：创建用户界面设计的最佳实践","ja":"UI デザイナー スキル：AI エージェントを使用した UI 設計のセットアップ ガイド","ko":"UI 디자이너 스킬: 사용자 인터페이스 디자인을 위한 가이드","es":"Guía de configuración de UI Designer: Diseño de interface...","fr":"Guide de mise en place de UI Designer : Conception d''inte...","de":"Einrichtungsleitfaden für UI Designer: Erstellung benutze...","pt":"Guia de Configuração do UI Designer: Melhores Práticas pa...","ru":"Руководство по настройке ИИ Агента UI Designer: Лучшие пр...","ar":"دليل إعداد مصمم واجهة المستخدم: أفضل الممارسات للعاملين ف..."},"description":{"en":"Unlock efficient UI design with context discovery. Learn how to anchor your work in brand constraints, existing design systems, and real user needs. Get star...","zh":"了解 UI 设计师技能的技术细节，包括上下文发现和设计系统。使用 AI 工具创建用户界面设计","ja":"UI デザイナー スキルを使用して、フォーム、機能、そしてアクセシビリティをバランスさせた UI を設計する。AI エージェントの技術情報を参照してください","ko":"UI 디자이너 스킬은 사용자 인터페이스 디자인을 위한 가이드입니다. 브랜드 제약, 기존 디자인 시스템, 실제 사용자 nhu cầu 및 플랫폼 규칙을 고려하여設計합니다.","es":"Aprende a diseñar interfaces de usuario claras y coherentes con UI Designer, considerando restricciones de marca y necesidades de usuarios reales","fr":"Découvrez comment concevoir des interfaces utilisateur claires et cohérentes avec UI Designer, en tenant compte des contraintes de marque et des besoins réel...","de":"Erfahren Sie, wie Sie mit UI Designer benutzerfreundliche Schnittstellen entwerfen, die Markeneinschränkungen und reale Benutzerbedürfnisse berücksichtigen","pt":"Aprenda a configurar o UI Designer com eficácia, considerando restrições de marca, sistemas de design existentes e necessidades reais dos usuários","ru":"Узнайте, как настроить ИИ Агента UI Designer, учитывая ограничения бренда, существующие системы дизайна и реальные потребности пользователей","ar":"تعرف على كيفية إعداد مصمم واجهة المستخدم بشكل فعال، مع مراعاة قيود العلامة التجارية والأنظمة الحالية للتصميم واحتياجات المستخدمين الفعلية"},"definition":{"en":"ui-designer is a skill that enables the creation of user interfaces anchored in brand constraints, existing design systems, real user needs, and platform conventions.","zh":"UI 设计师技能是一种用于创建用户界面设计的技能，注重形式、功能和可访问性。","ja":"UI デザイナー スキルは、UI を設計するために使用される AI エージェントのスキルです。","ko":"UI 디자이너 스킬은 사용자 인터페이스 디자인을 위한 가이드입니다.","es":"UI Designer es una habilidad que permite crear interfaces de usuario intuitivas y coherentes, considerando restricciones de marca y necesidades de usuarios reales","fr":"UI Designer est une compétence qui permet de concevoir des interfaces utilisateur intuitives et cohérentes, en tenant compte des contraintes de marque et des besoins réels des utilisateurs","de":"UI Designer ist eine Fähigkeit, die die Erstellung benutzerfreundlicher und kohärenter Schnittstellen ermöglicht, unter Berücksichtigung von Markeneinschränkungen und realen Benutzerbedürfnissen","pt":"O UI Designer é uma habilidade de design de interface do usuário que equilibra forma, função e acessibilidade","ru":"ИИ Агент UI Designer - это навык дизайна интерфейса пользователя, который балансирует форму, функцию и доступность","ar":"مصمم واجهة المستخدم هو مهارة لتصميم واجهة المستخدم التي توازن بين الشكل والوظيفة والتوافق"},"features":{"en":["Queries context-manager for context discovery","Anchors design in brand constraints and existing design systems","Considers real user needs and platform conventions","Balances form, function, and accessibility in interface design","Requires mandatory context discovery as the first step"],"zh":["上下文发现：查询 context-manager 以了解设计背景","设计系统：遵循现有的设计系统和品牌约束","用户需求：满足实际用户的需求和平台规则","可访问性：设计易用的和美观的界面","形式和功能的平衡：平衡形式、功能和可访问性"],"ja":["コンテキストの発見：context-manager を問い合わせて設計の背景を理解する","デザイン システム：既存のデザイン システムとブランドの制約に従う","ユーザーのニーズ：実際のユーザーのニーズとプラットフォームの規則に応える","アクセシビリティ：使いやすいと美観のある UI を設計する","フォームと機能のバランス：フォーム、機能、そしてアクセシビリティをバランスさせる"],"ko":["콘텍스트 발견：context-manager를 查询하여 디자인 背景을 이해한다","디자인 시스템：既存의 디자인 시스템과 브랜드 제약을 고려한다","사용자 nhu cầu：실제 사용자의 nhu cầu와 플랫폼 규칙을 고려하여 디자인한다","사용자 인터페이스 디자인：사용자 인터페이스를 디자인한다","형식과 함수의 균형：형식、함수、 그리고 접근성을 균형させる"],"es":["Diseño de interfaces de usuario claras y coherentes","Equilibrio de forma, función y accesibilidad","Consideración de restricciones de marca y necesidades de usuarios reales","Uso de sistemas de diseño existentes y convenciones de plataforma","Descubrimiento de contexto mediante la consulta del administrador de contexto"],"fr":["Conception d''interfaces utilisateur claires et cohérentes","Équilibre de forme, fonction et accessibilité","Prise en compte des contraintes de marque et des besoins réels des utilisateurs","Utilisation de systèmes de conception existants et de conventions de plateforme","Découverte de contexte via la consultation du gestionnaire de contexte"],"de":["Erstellung benutzerfreundlicher und kohärenter Schnittstellen","Ausbalancierung von Form, Funktion und Zugänglichkeit","Berücksichtigung von Markeneinschränkungen und realen Benutzerbedürfnissen","Verwendung von vorhandenen Design-Systemen und Plattform-Konventionen","Kontext-Erkennung durch Abfrage des Kontext-Managers"],"pt":["Análise de contexto com o context-manager","Consideração de restrições de marca e sistemas de design existentes","Desenvolvimento de interfaces claras e coerentes","Equilíbrio entre forma, função e acessibilidade","Integração com plataformas e convenções de design"],"ru":["Анализ контекста с помощью context-manager","Учет ограничений бренда и существующих систем дизайна","Разработка четких и согласованных интерфейсов","Баланс между формой, функцией и доступностью","Интеграция с платформами и конвенциями дизайна"],"ar":["تحليل السياق باستخدام الإدارة السياقية","مراعاة قيود العلامة التجارية والأنظمة الحالية للتصميم","تصميم واجهات واضحة ومتناسقة","توازن بين الشكل والوظيفة والتوافق","التكامل مع المنصات والاتفاقيات التصميمية"]},"keywords":{"en":["how to use ui-designer","ui-designer context discovery","ui-designer vs other design tools","ui-designer setup guide","what is ui-designer","ui-designer alternative","ui-designer install","ui-designer for AI agents","ui-designer design principles","ui-designer best practices"],"zh":["UI 设计师技能","用户界面设计","AI 工具","上下文发现","设计系统","用户需求","可访问性","形式和功能的平衡"],"ja":["UI デザイナー スキル","UI 設計","AI エージェント","コンテキストの発見","デザイン システム","ユーザーのニーズ","アクセシビリティ","フォームと機能のバランス"],"ko":["UI 디자이너 스킬","사용자 인터페이스 디자인","AI 도구","콘텍스트 발견","디자인 시스템","사용자 nhu cầu","사용자 인터페이스 디자인","형식과 함수의 균형"],"es":["UI Designer","diseño de interfaces de usuario","accesibilidad web","sistemas de diseño","convenciones de plataforma","diseño de experiencia de usuario","Herramientas de AI para diseño","Agentes de IA para diseño"],"fr":["UI Designer","conception d''interfaces utilisateur","accessibilité web","systèmes de conception","conventions de plateforme","conception d''expérience utilisateur","Outils d''IA pour la conception","Agents d''IA pour la conception"],"de":["UI Designer","Benutzeroberflächendesign","Web-Zugänglichkeit","Design-Systeme","Plattform-Konventionen","Benutzererfahrungsentwicklung","AI-Tools für Design","KI-Agenten für Design"],"pt":["ui designer","design de interface do usuário","desenvolvimento de interfaces","análise de contexto","restrições de marca","sistemas de design existentes","acessibilidade","form e função"],"ru":["ИИ Агент UI Designer","дизайн интерфейса пользователя","разработка интерфейсов","анализ контекста","ограничения бренда","существующие системы дизайна","доступность","форма и функция"],"ar":["مصمم واجهة المستخدم","تصميم واجهة المستخدم","تطوير واجهات","تحليل السياق","قيود العلامة التجارية","الأنظمة الحالية للتصميم","التوافق","الشكل والوظيفة"]}},"owner":"Masked-Kunsiquat","repo":"crm-orbit2","repoPath":"Masked-Kunsiquat/crm-orbit2","stars":0,"forks":0,"updatedAt":"2026-03-07T01:49:01.608Z","topics":[],"category":"community","skillMd":{"name":"ui-designer","description":"Design intuitive, accessible, and visually coherent interfaces aligned with brand and product goals.","version":"1.0.0","tags":"","bodyPreview":"# UI Designer (Codex Skill)\n\nYou are the **UI Designer**. Your job is to create clear, usable, and aesthetically coherent interfaces that balance **form, function, and accessibility**.\n\nYou do not design in a vacuum. You always anchor your work in:\n- brand constraints\n- existing design systems\n- real user needs\n- platform conventions\n\n---\n\n## Mandatory first step: Context discovery\n\nBefore designing anything, you must query the **context-manager**.\n\nYou are not allowed to proceed without this un","body":"# UI Designer (Codex Skill)\n\nYou are the **UI Designer**. Your job is to create clear, usable, and aesthetically coherent interfaces that balance **form, function, and accessibility**.\n\nYou do not design in a vacuum. You always anchor your work in:\n- brand constraints\n- existing design systems\n- real user needs\n- platform conventions\n\n---\n\n## Mandatory first step: Context discovery\n\nBefore designing anything, you must query the **context-manager**.\n\nYou are not allowed to proceed without this unless explicitly told to ignore context.\n\nYou must request:\n\n- brand guidelines (colors, typography, tone)\n- existing design system or component library\n- accessibility requirements\n- platform targets (web, mobile, desktop)\n- performance constraints\n- known UX problems\n\n---\n\n## Core responsibilities\n\n### 1) Visual hierarchy\n- Make the most important thing obvious\n- Guide the eye naturally\n- Use spacing, contrast, and scale intentionally\n- Avoid visual noise\n\n### 2) Consistency\n- Reuse patterns\n- Align with existing components\n- Follow platform conventions\n- Avoid inventing new UI patterns unless necessary\n\n### 3) Accessibility (non-negotiable)\n- Color contrast\n- Keyboard navigation\n- Focus states\n- Screen-reader-friendly structure\n- Motion-reduced alternatives\n- Tap target sizing\n\nIf a design is not accessible, it is not “done.”\n\n### 4) Interaction clarity\n- Clear affordances\n- Predictable behavior\n- Obvious feedback\n- Reversible actions\n- Graceful error states\n\n---\n\n## Design artifacts you may produce\n\nDepending on the task, you may output:\n\n- Component specs\n- Layout wireframes\n- Visual mockups (described textually if needed)\n- Design tokens\n- Interaction notes\n- State diagrams\n- Accessibility annotations\n- Handoff documentation\n\n---\n\n## Operating principles\n\n- Prefer clarity over decoration\n- Prefer systemization over one-offs\n- Prefer boring patterns that work\n- Prefer native behavior when available\n- Use existing theme tokens; avoid hardcoded hex/rgb/rgba colors unless extending the theme.\n\n---\n\n## Execution flow\n\n### Step 1: Understand the problem\n- What is the user trying to do?\n- Where are they confused today?\n- What must not change?\n- What platforms are in scope?\n\n### Step 2: Inventory existing patterns\n- Components\n- Layouts\n- Colors\n- Typography\n- Motion rules\n\nNever invent if reuse is possible.\n\n### Step 3: Design the solution\n- Define layout\n- Define component usage\n- Define states (loading, empty, error, success)\n- Define responsive behavior\n\n### Step 4: Validate\n- Accessibility check\n- Consistency check\n- Clarity check\n- Edge-case check\n\n### Step 5: Handoff\n- Provide clear specs\n- Define spacing, sizing, and states\n- Document decisions\n- Note any tradeoffs\n\n---\n\n## Output format (required)\n\nWhen delivering UI design guidance:\n\n### Summary\nWhat you designed and why.\n\n### User goal\nWhat problem this UI solves.\n\n### Structure\nHigh-level layout and component usage.\n\n### Components\nNew or modified components.\n\n### States\nLoading, error, empty, hover, focus, disabled, etc.\n\n### Accessibility notes\nContrast, focus, keyboard, screen reader considerations.\n\n### Handoff notes\nAnything developers must know to implement correctly.\n\n---\n\n## Red flags you must call out\n\n- Low contrast text\n- Ambiguous affordances\n- Inconsistent spacing\n- Overloaded screens\n- Hidden primary actions\n- Motion without user control\n- Color-only meaning\n- Hardcoded colors bypassing theme tokens\n\n---\n\n## Collaboration with other skills\n\nYou commonly work with:\n\n- **frontend-developer / react-specialist** → implementation\n- **accessibility-tester** → compliance\n- **technical-writer** → UI docs\n- **context-manager** → brand + rules\n- **product-manager** → requirements\n- **performance-engineer** → animation + asset budgets\n\n---\n\n## Example guidance\n\nIf redesigning a form:\n\n- Group related fields\n- Reduce cognitive load\n- Use inline validation\n- Provide clear error messaging\n- Avoid modal hell\n- Preserve entered data\n\n---\n\n## Philosophy\n\nUI should feel obvious.\n\nIf users have to think about the interface, the interface failed.\n\nYour job is to make complexity invisible.\n"},"lastSynced":"2026-03-07T02:13:06.182Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing human-centered interface design capabilities balancing form, function, and accessibility.","zh":"非常适合需要人性化界面设计能力的AI代理，能够平衡形式、功能和可访问性。","ja":"人間中心のインターフェイス設計能力が必要なAIエージェントに最適で、形式、機能、可達性のバランスをとることができます。","ko":"인간 중심의 인터페이스 디자인 기능이 필요한 AI 에이전트에게 적합하며, 형식, 기능, 접근성의 균형을 유지할 수 있습니다.","es":"Perfecto para agentes de IA que necesitan capacidades de diseño de interfaz centrado en el ser humano que equilibren la forma, la función y la accesibilidad.","fr":"Parfait pour les agents IA ayant besoin de capacités de conception d''interface centrée sur l''humain équilibrant la forme, la fonction et l''accessibilité.","de":"Perfekt für KI-Agents, die kapazitäten für menschenzentriertes Interface-Design benötigen, das Form, Funktion und Zugänglichkeit ausgleicht.","pt":"Perfeito para Agentes de IA que necessitam de capacidades de design de interface centrado no ser humano, equilibrando forma, função e acessibilidade.","ru":"Идеально для агентов ИИ, которым требуются возможности проектирования интерфейса, ориентированного на человека, балансирующие форму, функцию и доступность.","ar":"مثالي للوكلاء الذكاء الاصطناعي الذين يحتاجون إلى قدرات تصميم واجهة مستخدم تركز على الإنسان وتوازن الشكل والوظيفة والوصول."},"recommendation":{"en":"Empowers agents to create clear, usable, and aesthetically coherent interfaces anchored in brand constraints, existing design systems, real user needs, and platform conventions, utilizing context-driven design approaches.","zh":"赋予代理创建清晰、可用且美观的一致性界面，依托品牌约束、现有的设计系统、真实的用户需求和平台惯例，利用上下文驱动的设计方法。","ja":"エージェントに明確で使いやすく、また美観のある一貫性のあるインターフェイスを作成する力を与え、ブランドの制約、既存のデザインシステム、実際のユーザーのニーズ、プラットフォームの規約に基づいて、コンテキスト駆動のデザインアプローチを利用する。","ko":"에이전트가 브랜드 제약, 기존 디자인 시스템, 실제 사용자 요구 및 플랫폼 규칙에 기반하여 명확하고 사용하기 쉬우며 심미적으로 일관된 인터페이스를 생성할 수 있는力を 부여하며, 컨텍스트 주도设计 접근 방식을 사용합니다.","es":"Habilita a los agentes a crear interfaces claras, utilizables y estéticamente coherentes ancladas en restricciones de marca, sistemas de diseño existentes, necesidades reales de los usuarios y convenciones de plataforma, utilizando enfoques de diseño dirigidos por el contexto.","fr":"Permet aux agents de créer des interfaces claires, utilisables et esthétiquement cohérentes ancrées dans les contraintes de marque, les systèmes de conception existants, les besoins réels des utilisateurs et les conventions de plateforme, en utilisant des approches de conception pilotées par le contexte.","de":"Ermöglicht es den Agents, klare, benutzbare und ästhetisch kohärente Schnittstellen zu erstellen, die in Markteinschränkungen, bestehenden Designsystemen, realen Benutzerbedürfnissen und Plattformkonventionen verankert sind und kontextgetriebene Designansätze nutzen.","pt":"Habilita os agentes a criar interfaces claras, utilizáveis e esteticamente coerentes, ancoradas em restrições de marca, sistemas de design existentes, necessidades reais dos usuários e convenções de plataforma, utilizando abordagens de design orientadas por contexto.","ru":"Наделяет агентов возможностью создавать ясные, удобные и эстетически последовательные интерфейсы, основанные на ограничениях бренда, существующих системах дизайна, реальных потребностях пользователей и платформенных конвенциях, используя контекстно-ориентированные подходы к дизайну.","ar":"تمكّن الوكلاء من إنشاء واجهات واضحة وسهلة الاستخدام ومتناسقة من الناحية الجمالية، مرتكزة على قيود العلامة التجارية وأنظمة التصميم الحالية واحتياجات المستخدمين الحقيقية وأعراف المنصة، باستخدام نهج تصميم مدفوع بالسياق."},"useCases":{"en":["Designing intuitive onboarding flows for web applications","Developing accessible and responsive UI components for mobile devices","Creating consistent branding across multiple platforms and devices"],"zh":["为Web应用程序设计直观的入门流程","为移动设备开发无障碍且响应式的UI组件","跨多个平台和设备创建一致的品牌形象"],"ja":["Webアプリケーションの直感的なオンボーディングフローを設計する","モバイルデバイスのアクセシブル且つレスポンシブなUIコンポーネントを開発する","複数のプラットフォームおよびデバイス間で一貫したブランドイメージを作成する"],"ko":["웹 애플리케이션을 위한 직관적인 온보딩 흐름 설계","모바일 기기의 접근성 및 반응형 UI 구성 요소 개발","여러 플랫폼 및 기기 간에 일관된 브랜드 이미지를 생성"],"es":["Diseñar flujos de incorporación intuitivos para aplicaciones web","Desarrollar componentes de UI accesibles y responsivos para dispositivos móviles","Crear una marca coherente en varias plataformas y dispositivos"],"fr":["Concevoir des flux d''intégration intuitifs pour les applications web","Développer des composants d''interface utilisateur accessibles et responsifs pour les appareils mobiles","Créer une marque cohérente sur plusieurs plateformes et appareils"],"de":["Intuitive Onboardings-Flüsse für Webanwendungen entwerfen","Zugängliche und responsive UI-Komponenten für mobile Geräte entwickeln","Eine konsistente Markenidentität über mehrere Plattformen und Geräte hinweg erstellen"],"pt":["Projetar fluxos de integração intuitivos para aplicações web","Desenvolver componentes de UI acessíveis e responsivos para dispositivos móveis","Criar marcação consistente em várias plataformas e dispositivos"],"ru":["Проектирование интуитивно понятных потоков интеграции для веб-приложений","Разработка доступных и адаптивных компонентов UI для мобильных устройств","Создание последовательного брендинга на нескольких платформах и устройствах"],"ar":["تصميم تدفقات دمج直觉ية لتطبيقات الويب","تنمية مكونات واجهة المستخدم المتوافقة والاستجابة لأجهزة المحمول","إنشاء علامة تجارية متسقة عبر منصات وأجهزة متعددة"]},"limitations":{"en":["Requires context discovery through the context-manager","Must adhere to brand constraints and existing design systems"],"zh":["需要通过上下文管理器进行上下文发现","必须遵守品牌约束和现有的设计系统"],"ja":["コンテキストマネージャーを通じたコンテキストの発見が必要","ブランドの制約および既存のデザインシステムに従う必要がある"],"ko":["컨텍스트 관리자를 통해 컨텍스트 발견이 필요","브랜드 제약 및 기존 디자인 시스템을 따라야 함"],"es":["Requiere descubrimiento de contexto a través del administrador de contexto","Debe adherirse a las restricciones de marca y los sistemas de diseño existentes"],"fr":["Nécessite une découverte de contexte via le gestionnaire de contexte","Doit se conformer aux contraintes de marque et aux systèmes de conception existants"],"de":["Benötigt Kontextentdeckung durch den Kontext-Manager","Muss sich an die Markteinschränkungen und bestehenden Designsysteme halten"],"pt":["Exige descoberta de contexto por meio do gerenciador de contexto","Deve aderir às restrições de marca e sistemas de design existentes"],"ru":["Требует открытия контекста через менеджер контекста","Должно соответствовать ограничениям бренда и существующим системам дизайна"],"ar":["يتطلب اكتشاف السياق من خلال مدير السياق","يجب الالتزام بقيود العلامة التجارية وأنظمة التصميم الحالية"]},"version":4},"contentHash":"01470ec0315f3641ec352e61ccd6ab51642511847094f5f91486720ef1c4732a","qualityScore":49}');
