INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Masked-Kunsiquat/crm-orbit2/ui-designer', 'ui-designer', 'Masked-Kunsiquat', 'crm-orbit2', 'community', 'ui-designer Masked-Kunsiquat crm-orbit2 community The ui-designer skill creates clear, usable, and aesthetically coherent interfaces balancing form, function, and accessibility for AI agents. It benefits developers and designers by providing a context-driven design approach. UI 设计师技能用于创建清晰、易用且美观的界面，平衡形式、功能和可访问性。 UI デザイナー スキルは、フォーム、機能、そしてアクセシビリティをバランスさせた UI を設計するために使用されます。 UI 디자이너 스킬은 사용자 인터페이스 디자인을 위한 가이드입니다. 사용자 nhu cầu와 플랫폼 규칙을 고려하여 디자인합니다. UI Designer crea interfaces de usuario claras, usables y estéticamente coherentes, equilibrando forma, función y accesibilidad UI Designer conçoit des interfaces utilisateur claires, utilisables et esthétiquement cohérentes, en équilibrant forme, fonction et accessibilité UI Designer erstellt benutzerfreundliche Schnittstellen, die Form, Funktion und Zugänglichkeit ausbalancieren O UI Designer é uma habilidade que cria interfaces claras e coerentes, considerando forma, função e acessibilidade. Saiba como configurá-lo corretamente ИИ Агент UI Designer - это навык, который создает четкие и согласованные интерфейсы, учитывая форму, функцию и доступность. Узнайте, как его настроить مصمم واجهة المستخدم هو مهارة تقوم بإنشاء واجهات واضحة ومتناسقة، مع مراعاة الشكل والوظيفة والتوافق. تعرف على كيفية إعداده بشكل صحيح how to use ui-designer ui-designer context discovery ui-designer vs other design tools ui-designer setup guide what is ui-designer ui-designer alternative ui-designer install ui-designer for AI agents ui-designer design principles ui-designer best practices UI 设计师技能 用户界面设计 AI 工具 上下文发现 设计系统 用户需求 可访问性 形式和功能的平衡 Queries context-manager for context discovery Anchors design in brand constraints and existing design systems Considers real user needs and platform conventions Balances form, function, and accessibility in interface design Requires mandatory context discovery as the first step ui-designer is a skill that enables the creation of user interfaces anchored in brand constraints, existing design systems, real user needs, and platform conventions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('HosungYou/Diverga/diverga-g2', 'community', 'HosungYou', 'Diverga', 'HosungYou/Diverga', 'diverga-g2', 0, 0, 49, '2026-03-06T12:59:22.226Z', '2026-03-06T14:12:11.351Z', '7baf07caa6c2b314960d581980eeeeb7a1e5cd8096eb59b0662f1794fb5b6517', '{"id":"HosungYou/Diverga/diverga-g2","name":"diverga-g2","description":{"en":"diverga-g2 creates materials to communicate research findings to diverse audiences, supporting customized communication from academic abstracts to social media content. It benefits researchers and academics looking to effectively share their findings.","zh":"Diverga-G2是一种基于GPT-5.2-Codex的学术交流工具，支持定制化的学术摘要和社会媒体内容的生成","ja":"Diverga-G2はGPT-5.2-Codexを用いた学術交流ツールであり、カスタマイズされた学術摘要とソーシャルメディアコンテンツの生成をサポート","ko":"Diverga-G2는 GPT-5.2-Codex 기반의 학술 소통 도구로, 맞춤형 학술 요약과 소셜 미디어 콘텐츠 생성을 지원합니다","es":"Diverga-g2 es un agente de comunicación académica que utiliza gpt-5.2-codex para crear materiales de comunicación efectivos. Soporta la personalización de la comunicación desde resúmenes académicos hasta contenido de redes sociales.","fr":"Diverga-g2 est un agent de communication académique qui utilise gpt-5.2-codex pour créer des matériaux de communication efficaces. Il prend en charge la personnalisation de la communication depuis les résumés académiques jusqu''au contenu des réseaux sociaux.","de":"Diverga-g2 ist ein Agent für akademische Kommunikation, der gpt-5.2-codex verwendet, um effektive Kommunikationsmaterialien zu erstellen. Es unterstützt die Anpassung der Kommunikation von akademischen Zusammenfassungen bis hin zu Social-Media-Inhalten.","pt":"O Diverga-G2 é um agente de comunicação acadêmica que utiliza a tecnologia gpt-5.2-codex para criar materiais personalizados.","ru":"Diverga-G2 - это агент академической коммуникации, который использует технологию gpt-5.2-codex для создания индивидуальных материалов.","ar":"Diverga-G2 هو وسيط اتصال أكاديمي يستخدم تقنية gpt-5.2-codex لإنشاء مواد مخصصة."},"seo":{"title":{"en":"diverga-g2: Customized Academic Communication Setup Guide...","zh":"Diverga-G2 Setup Guide: 基于GPT-5.2-Codex的学术交流工具","ja":"Diverga-G2 の設定方法: GPT-5.2-Codex を用いた AIエージェント","ko":"Diverga-G2 설정 가이드: GPT-5.2-Codex 기반 학술 소통 도구","es":"Guía de configuración de diverga-g2: Comunicación académi...","fr":"Guide de mise en place de diverga-g2: Communication acadé...","de":"Einrichtungsleitfaden für diverga-g2: Effektive akademisc...","pt":"Guia de Configuração do Diverga-G2: Comunicação Acadêmica...","ru":"Настройка Diverga-G2: Расширенный Академический Коммуника...","ar":"دليل إعداد Diverga-G2: تواصل أكاديمي متقدم بأدوات الذكاء ..."},"description":{"en":"Unlock effective research communication with diverga-g2. Discover how to create audience-specific messages using VS methodology and gpt-5.2-codex model. Get ...","zh":"了解Diverga-G2的功能和特点，掌握基于GPT-5.2-Codex的学术交流工具的使用方法","ja":"Diverga-G2の機能と特徴を学び、GPT-5.2-Codexを用いたAIエージェントの活用方法をマスター","ko":"Diverga-G2의 기능과 특징을 알아보고, GPT-5.2-Codex 기반 학술 소통 도구의 사용 방법을 익히세요","es":"Aprende a utilizar diverga-g2 para crear materiales de comunicación académica efectivos con gpt-5.2-codex y VS methodology","fr":"Découvrez comment utiliser diverga-g2 pour créer des matériaux de communication académique efficaces avec gpt-5.2-codex et VS methodology","de":"Erfahren Sie, wie Sie diverga-g2 verwenden, um effektive akademische Kommunikationsmaterialien mit gpt-5.2-codex und VS methodology zu erstellen","pt":"Aprenda a configurar o Diverga-G2 para criar materiais de comunicação acadêmica personalizados com a tecnologia gpt-5.2-codex","ru":"Узнайте, как настроить Diverga-G2 для создания индивидуальных материалов академической коммуникации с помощью технологии gpt-5.2-codex и ИИ Агентов","ar":"تعلم كيفية إعداد Diverga-G2 لإنشاء مواد اتصال أكاديمي مخصصة باستخدام تقنية gpt-5.2-codex وأدوات الذكاء الاصطناعي"},"definition":{"en":"diverga-g2 is a communication agent that applies VS methodology to design audience-specific messages, utilizing the gpt-5.2-codex model for efficient communication.","zh":"Diverga-G2是一种AI工具，用于生成学术摘要和社会媒体内容","ja":"Diverga-G2はAIエージェントであり、学術摘要とソーシャルメディアコンテンツの生成を支援","ko":"Diverga-G2는 학술 요약과 소셜 미디어 콘텐츠 생성을 지원하는 AI 도구입니다","es":"Diverga-g2 es un agente de comunicación académica que utiliza inteligencia artificial para crear materiales de comunicación efectivos","fr":"Diverga-g2 est un agent de communication académique qui utilise l''intelligence artificielle pour créer des matériaux de communication efficaces","de":"Diverga-g2 ist ein Agent für akademische Kommunikation, der künstliche Intelligenz verwendet, um effektive Kommunikationsmaterialien zu erstellen","pt":"O Diverga-G2 é um agente de comunicação acadêmica que cria materiais personalizados com a tecnologia gpt-5.2-codex","ru":"Diverga-G2 - это агент академической коммуникации, который создает индивидуальные материалы с помощью технологии gpt-5.2-codex","ar":"Diverga-G2 هو وسيط اتصال أكاديمي لإنشاء مواد مخصصة بتكنولوجيا gpt-5.2-codex"},"features":{"en":["Creates customized communication materials using gpt-5.2-codex model","Supports audience-specific message design with VS methodology","Generates content for academic abstracts, public summaries, and social media","Runs in Codex CLI''s single-model mode for efficient processing","Applies Light VS methodology for beyond template-based writing"],"zh":["基于GPT-5.2-Codex的学术交流工具","支持定制化的学术摘要生成","支持社会媒体内容的生成","应用VS方法论（Light）进行消息设计","支持Codex CLI单模型模式"],"ja":["GPT-5.2-Codexを用いた学術交流ツール","カスタマイズされた学術摘要の生成をサポート","ソーシャルメディアコンテンツの生成をサポート","VS方法論（Light）を用いたメッセージ設計","Codex CLIシングルモデルモードをサポート"],"ko":["GPT-5.2-Codex 기반의 학술 소통 도구","맞춤형 학술 요약 생성 지원","소셜 미디어 콘텐츠 생성 지원","VS 방법론（Light）을 사용한 메시지 디자인","Codex CLI 단일 모델 모드 지원"],"es":["Utiliza gpt-5.2-codex para crear materiales de comunicación efectivos","Soporta la personalización de la comunicación desde resúmenes académicos hasta contenido de redes sociales","Aplica la metodología VS (Light) para diseñar mensajes específicos para la audiencia","Se ejecuta en modo degradado de Codex CLI","Utiliza un solo modelo para la creación de contenido","Permite la creación de resúmenes académicos y contenido de redes sociales personalizados"],"fr":["Utilise gpt-5.2-codex pour créer des matériaux de communication efficaces","Prend en charge la personnalisation de la communication depuis les résumés académiques jusqu''au contenu des réseaux sociaux","Applique la méthodologie VS (Light) pour concevoir des messages spécifiques à l''audience","S''exécute en mode dégradé de Codex CLI","Utilise un seul modèle pour la création de contenu","Permet la création de résumés académiques et de contenu de réseaux sociaux personnalisés"],"de":["Verwendet gpt-5.2-codex, um effektive Kommunikationsmaterialien zu erstellen","Unterstützt die Anpassung der Kommunikation von akademischen Zusammenfassungen bis hin zu Social-Media-Inhalten","Wendet die VS-Methodik (Light) an, um audienciaspezifische Nachrichten zu entwerfen","Führt aus in eingeschränktem Modus von Codex CLI","Verwendet ein einzelnes Modell für die Erstellung von Inhalten","Ermöglicht die Erstellung von akademischen Zusammenfassungen und Social-Media-Inhalten"],"pt":["Utiliza a tecnologia gpt-5.2-codex para criar materiais de comunicação acadêmica","Suporta comunicação personalizada de resumos acadêmicos a sumários públicos e conteúdo de mídia social","Aplica a metodologia VS (Light) para criar mensagens personalizadas para o público","Funciona no modo degradado do Codex CLI","Utiliza o modelo de linguagem gpt-5.2-codex para criar conteúdo personalizado","Permite a criação de materiais de comunicação acadêmica em diferentes formatos"],"ru":["Использует технологию gpt-5.2-codex для создания материалов академической коммуникации","Поддерживает индивидуальную коммуникацию от академических аннотаций до публичных суммари и контента социальных сетей","Применяет методологию VS (Light) для создания персонализированных сообщений для аудитории","Работает в режиме деградации Codex CLI","Использует языковую модель gpt-5.2-codex для создания персонализированного контента","Позволяет создавать материалы академической коммуникации в разных форматах"],"ar":["يستخدم تقنية gpt-5.2-codex لإنشاء مواد اتصال أكاديمي","يدعم التواصل المخصص من الملخصات الأكاديمية إلى الملخصات العامة ومحتوى وسائل الإعلام الاجتماعية","يتطبيق منهجية VS (Light) لإنشاء رسائل مخصصة للجمهور","يعمل في وضع التدهور من Codex CLI","يستخدم نموذج اللغة gpt-5.2-codex لإنشاء محتوى مخصص","يسمح بإنشاء مواد اتصال أكاديمي في صيغ مختلفة"]},"keywords":{"en":["how to use diverga-g2","diverga-g2 alternative","diverga-g2 setup guide","what is diverga-g2","diverga-g2 vs gpt-3","diverga-g2 install","gpt-5.2-codex model","VS methodology","academic communication tools","research findings sharing"],"zh":["Diverga-G2","GPT-5.2-Codex","学术交流工具","AI工具","学术摘要生成","社会媒体内容生成","VS方法论","Codex CLI"],"ja":["Diverga-G2","GPT-5.2-Codex","AIエージェント","学術交流ツール","学術摘要生成","ソーシャルメディアコンテンツ生成","VS方法論","Codex CLI"],"ko":["Diverga-G2","GPT-5.2-Codex","AI 도구","학술 소통 도구","학술 요약 생성","소셜 미디어 콘텐츠 생성","VS 방법론","Codex CLI"],"es":["diverga-g2","comunicación académica","gpt-5.2-codex","VS methodology","Codex CLI","creación de contenido","resúmenes académicos","contenido de redes sociales","inteligencia artificial","herramientas de AI"],"fr":["diverga-g2","communication académique","gpt-5.2-codex","VS methodology","Codex CLI","création de contenu","résumés académiques","contenu des réseaux sociaux","intelligence artificielle","outils de l''IA"],"de":["diverga-g2","akademische Kommunikation","gpt-5.2-codex","VS-Methodik","Codex CLI","Erstellung von Inhalten","akademische Zusammenfassungen","Social-Media-Inhalte","künstliche Intelligenz","KI-Tools"],"pt":["Diverga-G2","comunicação acadêmica","gpt-5.2-codex","Codex CLI","metodologia VS","materiais de comunicação personalizados","resumos acadêmicos","sumários públicos","conteúdo de mídia social","tecnologia de linguagem natural"],"ru":["Diverga-G2","академическая коммуникация","gpt-5.2-codex","Codex CLI","методология VS","индивидуальные материалы коммуникации","академические аннотации","публичные суммари","контент социальных сетей","технология естественного языка"],"ar":["Diverga-G2","اتصال أكاديمي","gpt-5.2-codex","Codex CLI","منهجية VS","مواد اتصال مخصصة","ملخصات أكاديمية","ملخصات عامة","محتوى وسائل الإعلام الاجتماعية","تكنولوجيا اللغة الطبيعية"]}},"owner":"HosungYou","repo":"Diverga","repoPath":"HosungYou/Diverga","stars":0,"forks":0,"updatedAt":"2026-03-06T12:59:22.226Z","topics":[],"category":"community","skillMd":{"name":"diverga-g2","description":"|","version":"10.3.0","bodyPreview":"# G2-AcademicCommunicator\n\n**Agent ID**: G2\n**Category**: G - Communication\n**Model**: gpt-5.2-codex\n\n## Overview\n\nCreates materials to effectively communicate research findings to diverse audiences. Supports customized communication from academic abstracts to public summaries and social media content. Applies VS methodology (Light) to move beyond template-based writing toward audience-specific message design.\n\n## Codex CLI Degraded Mode\nThis agent runs in Codex CLI''s single-model mode. Key diff","body":"# G2-AcademicCommunicator\n\n**Agent ID**: G2\n**Category**: G - Communication\n**Model**: gpt-5.2-codex\n\n## Overview\n\nCreates materials to effectively communicate research findings to diverse audiences. Supports customized communication from academic abstracts to public summaries and social media content. Applies VS methodology (Light) to move beyond template-based writing toward audience-specific message design.\n\n## Codex CLI Degraded Mode\nThis agent runs in Codex CLI''s single-model mode. Key differences from Claude Code:\n- No parallel agent execution - tasks run sequentially\n- No MCP runtime checkpoints - uses text-based checkpoint protocol\n- No AskUserQuestion UI - uses text prompts for decisions\n\n## Checkpoint Protocol\nNo checkpoints during execution. Integrates with humanization pipeline optionally.\n\n## Prerequisites\nNone required. Standalone agent.\n\n## Core Capabilities\n\n### Communication Types\n1. **Academic Abstract** - Structured (IMRAD) and unstructured abstracts, graphical abstract concepts\n2. **Plain Language Summary** - Non-specialist explanation emphasizing real-life relevance\n3. **Media Materials** - Press releases, interview Q&A, infographic concepts\n4. **Social Media** - Twitter/X threads, LinkedIn posts, Instagram captions\n5. **Presentations** - Elevator pitch, poster summary, 3-Minute Thesis\n\n### Audience Strategies\n| Audience | Strategy |\n|----------|----------|\n| Researchers | Technical terms, detailed methodology |\n| Policymakers | Emphasize implications, recommendations |\n| Practitioners | Practical applications |\n| General public | Simple terms, metaphors, everyday context |\n| Media | Novelty, impact, quotes |\n| Students | Educational value, examples |\n\n### Humanization Integration\nAfter generating content, optionally invoke humanization pipeline:\n- Conservative mode for journal submissions\n- Balanced mode for most academic writing\n- Aggressive mode for social media and informal content\n\n### VS Modal Awareness (Light)\n| Audience | Modal (T>0.8) | Differentiated (T<0.5) |\n|----------|---------------|------------------------|\n| Abstract | \"Fill IMRAD template\" | Core contribution + journal style match |\n| Summary | \"Remove jargon\" | Storytelling + everyday relevance |\n| Social media | \"Tweet result summary\" | Audience engagement + visual hook |\n| Press | \"Press release template\" | Maximize news value + design quotes |\n\n## Output Format\n\nProduces Research Communication Materials with:\n- 3 core messages (academic and general expressions)\n- Academic abstract (250 words, IMRAD structured)\n- Plain language summary (150 words)\n- Press release (300 words) with researcher quote\n- Twitter/X thread (5 tweets)\n- LinkedIn post\n- Graphical abstract concept layout\n- Elevator pitch (30 seconds)\n\n## Tool Mapping (Codex)\n| Claude Code | Codex CLI |\n|-------------|-----------|\n| Read | read_file |\n| Edit | apply_diff |\n| Write | write_file |\n| Grep | grep |\n| Bash | shell |\n| Task (subagent) | Read skill file, follow instructions |\n\n## Related Agents\n- **G1-JournalMatcher**: Select submission journal\n- **G3-PeerReviewStrategist**: Respond to reviewers\n- **G5-AcademicStyleAuditor**: Analyze AI patterns in output\n- **G6-AcademicStyleHumanizer**: Transform output to natural prose\n"},"lastSynced":"2026-03-06T14:12:11.351Z","agentAnalysis":{"suitability":{"en":"Perfect for Research Agents needing customized communication materials for diverse audiences.","zh":"非常适合需要为不同受众定制通信材料的研究代理。","ja":"研究エージェントが様々なオーディエンス向けのカスタマイズされたコミュニケーション資料を必要とする場合に最適です。","ko":"다양한 대상에게 맞춤형 커뮤니케이션 자료가 필요한 연구 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Investigación que necesitan materiales de comunicación personalizados para audiencias diversas.","fr":"Parfait pour les agents de recherche ayant besoin de matériel de communication personnalisé pour des publics divers.","de":"Perfekt für Forschungsagenten, die benutzerdefinierte Kommunikationsmaterialien für verschiedene Zielgruppen benötigen.","pt":"Perfeito para Agentes de Pesquisa que precisam de materiais de comunicação personalizados para públicos diversos.","ru":"Идеально подходит для исследовательских агентов, которым необходимы индивидуализированные материалы для общения с разнообразной аудиторией.","ar":"مثالي لويبوتات البحث التي تحتاج إلى مواد اتصال مخصصة للجماهير المتنوعة."},"recommendation":{"en":"Empowers agents to create tailored content from academic abstracts to social media posts using the VS methodology, moving beyond template-based writing toward audience-specific message design with gpt-5.2-codex.","zh":"赋予代理创建从学术摘要到社交媒体帖子等定制内容的能力，使用VS方法，超越基于模板的写作，采用gpt-5.2-codex实现面向特定受众的信息设计。","ja":"VSメソッドを使用して、学術的要約からソーシャルメディア投稿まで、gpt-5.2-codexを用いてテンプレートベースの文章作成を超えた、特定のオーディエンス向けのメッセージ設計によるカスタマイズされたコンテンツの作成をエージェントに可能にします。","ko":"에이전트가 학술 초록부터 소셜 미디어 게시물까지 VS 방법을 사용하여 gpt-5.2-codex로 템플릿 기반 작성 방식을超越하여 특정 대상에게 맞춘 메시지 설계를 통해 사용자 지정 콘텐츠를 생성할 수 있도록 합니다.","es":"Habilita a los agentes a crear contenido personalizado desde resúmenes académicos hasta publicaciones en redes sociales utilizando la metodología VS, superando la escritura basada en plantillas hacia un diseño de mensaje específico de la audiencia con gpt-5.2-codex.","fr":"Permet aux agents de créer du contenu personnalisé allant des résumés académiques aux publications sur les réseaux sociaux en utilisant la méthodologie VS, allant au-delà de l''écriture basée sur des modèles pour concevoir des messages spécifiques à l''audience avec gpt-5.2-codex.","de":"Ermächtigt die Agenten, maßgeschneiderte Inhalte von akademischen Zusammenfassungen bis hin zu Social-Media-Beiträgen mithilfe der VS-Methode zu erstellen, indem es über die auf Vorlagen basierende Erstellung hinausgeht und auf eine audienciaspezifische Nachrichtenkonzeption mit gpt-5.2-codex setzt.","pt":"Habilita os agentes a criarem conteúdo personalizado a partir de resumos acadêmicos até postagens em mídias sociais usando a metodologia VS, avançando além da escrita baseada em modelos em direção ao design de mensagem específico para o público com gpt-5.2-codex.","ru":"Наделяет агентов возможностью создавать адаптированный контент от академических аннотаций до публикаций в социальных сетях, используя методологию VS, продвигаясь дальше шаблонного написания в сторону проектирования сообщений, ориентированных на аудиторию, с помощью gpt-5.2-codex.","ar":"تمكّن الوكلاء من إنشاء محتوى مخصص من الملخصات الأكاديمية إلى منشورات وسائل الإعلام الاجتماعية باستخدام منهجية VS، متجاوزين كتابة القوالب نحو تصميم رسائل محددة للجمهور مع gpt-5.2-codex."},"useCases":{"en":["Generating public summaries from research findings","Creating social media content for academic research","Automating the production of customized communication materials"],"zh":["从研究发现生成公共摘要","为学术研究创建社交媒体内容","自动生产定制通信材料"],"ja":["研究結果からパブリックサマリーを生成する","学術研究のためのソーシャルメディアコンテンツを作成する","カスタマイズされたコミュニケーション資料の自動生成"],"ko":["연구 결과로부터 공개 요약 생성","학술 연구를 위한 소셜 미디어 콘텐츠 생성","사용자 지정 커뮤니케이션 자료 자동 생성"],"es":["Generación de resúmenes públicos a partir de resultados de investigación","Creación de contenido de redes sociales para investigación académica","Automatización de la producción de materiales de comunicación personalizados"],"fr":["Génération de résumés publics à partir de résultats de recherche","Création de contenu de réseaux sociaux pour la recherche académique","Automatisation de la production de matériel de communication personnalisé"],"de":["Erstellung öffentlicher Zusammenfassungen aus Forschungsergebnissen","Erstellung von Social-Media-Inhalten für akademische Forschung","Automatisierung der Produktion von benutzerdefinierten Kommunikationsmaterialien"],"pt":["Geração de resumos públicos a partir de resultados de pesquisa","Criação de conteúdo de mídia social para pesquisa acadêmica","Automatização da produção de materiais de comunicação personalizados"],"ru":["Генерация публичных резюме на основе результатов исследований","Создание контента социальных сетей для академических исследований","Автоматизация производства индивидуализированных материалов для общения"],"ar":["إيجاد ملخصات عامة من نتائج البحث","إنشاء محتوى لوسائل الإعلام الاجتماعية للبحث الأكاديمي","تأتميم إنتاج مواد اتصال مخصصة"]},"limitations":{"en":["Runs in Codex CLI''s single-model mode","Limited to gpt-5.2-codex model"],"zh":["仅在Codex CLI的单模型模式下运行","仅限gpt-5.2-codex模型"],"ja":["Codex CLIのシングルモデルモードでのみ実行","gpt-5.2-codexモデルに限定"],"ko":["Codex CLI의 싱글 모델 모드에서만 실행","gpt-5.2-codex 모델로 제한"],"es":["Se ejecuta en el modo de un solo modelo de Codex CLI","Limitado al modelo gpt-5.2-codex"],"fr":["S''exécute en mode mono-modèle de Codex CLI","Limité au modèle gpt-5.2-codex"],"de":["Läuft im Einmodus-Modus von Codex CLI","Begrenzt auf das gpt-5.2-codex-Modell"],"pt":["Executa no modo de modelo único do Codex CLI","Limitado ao modelo gpt-5.2-codex"],"ru":["Работает в режиме одиночного моделирования Codex CLI","Ограничен моделью gpt-5.2-codex"],"ar":["يعمل في وضع نموذج واحد من Codex CLI","محدود بنموذج gpt-5.2-codex"]},"version":4},"contentHash":"7baf07caa6c2b314960d581980eeeeb7a1e5cd8096eb59b0662f1794fb5b6517","qualityScore":49}');
