INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('HosungYou/Diverga/diverga-g2', 'diverga-g2', 'HosungYou', 'Diverga', 'community', 'diverga-g2 HosungYou Diverga community diverga-g2 creates materials to communicate research findings to diverse audiences, supporting customized communication from academic abstracts to social media content. It benefits researchers and academics looking to effectively share their findings. Diverga-G2是一种基于GPT-5.2-Codex的学术交流工具，支持定制化的学术摘要和社会媒体内容的生成 Diverga-G2はGPT-5.2-Codexを用いた学術交流ツールであり、カスタマイズされた学術摘要とソーシャルメディアコンテンツの生成をサポート Diverga-G2는 GPT-5.2-Codex 기반의 학술 소통 도구로, 맞춤형 학술 요약과 소셜 미디어 콘텐츠 생성을 지원합니다 Diverga-g2 es un agente de comunicación académica que utiliza gpt-5.2-codex para crear materiales de comunicación efectivos. Soporta la personalización de la comunicación desde resúmenes académicos hasta contenido de redes sociales. Diverga-g2 est un agent de communication académique qui utilise gpt-5.2-codex pour créer des matériaux de communication efficaces. Il prend en charge la personnalisation de la communication depuis les résumés académiques jusqu''au contenu des réseaux sociaux. Diverga-g2 ist ein Agent für akademische Kommunikation, der gpt-5.2-codex verwendet, um effektive Kommunikationsmaterialien zu erstellen. Es unterstützt die Anpassung der Kommunikation von akademischen Zusammenfassungen bis hin zu Social-Media-Inhalten. O Diverga-G2 é um agente de comunicação acadêmica que utiliza a tecnologia gpt-5.2-codex para criar materiais personalizados. Diverga-G2 - это агент академической коммуникации, который использует технологию gpt-5.2-codex для создания индивидуальных материалов. Diverga-G2 هو وسيط اتصال أكاديمي يستخدم تقنية gpt-5.2-codex لإنشاء مواد مخصصة. how to use diverga-g2 diverga-g2 alternative diverga-g2 setup guide what is diverga-g2 diverga-g2 vs gpt-3 diverga-g2 install gpt-5.2-codex model VS methodology academic communication tools research findings sharing Diverga-G2 GPT-5.2-Codex 学术交流工具 AI工具 学术摘要生成 社会媒体内容生成 VS方法论 Codex CLI Creates customized communication materials using gpt-5.2-codex model Supports audience-specific message design with VS methodology Generates content for academic abstracts, public summaries, and social media Runs in Codex CLI''s single-model mode for efficient processing Applies Light VS methodology for beyond template-based writing diverga-g2 is a communication agent that applies VS methodology to design audience-specific messages, utilizing the gpt-5.2-codex model for efficient communication.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('JetBrains/intellij-community/debugging', 'community', 'JetBrains', 'intellij-community', 'JetBrains/intellij-community', 'debugging', 19773, 5699, 49, '2026-03-08T01:25:45Z', '2026-03-08T01:58:14.712Z', '18f733870ca77424ccb7f7e862e49dc108de6b02858df8a3c64af5dede88a7e6', '{"id":"JetBrains/intellij-community/debugging","name":"debugging","description":{"en":"The debugging skill provides technical resources for IntelliJ IDEA & IntelliJ Platform, benefiting developers who need to diagnose IDE freezes and analyze exceptions. It offers guides on logging, performance, and exception analysis.","zh":"IntelliJ IDEA调试功能提供了强大的日志搜索和异常分析能力","ja":"IntelliJ IDEAのデバッグ機能は強力なログ検索と例外分析機能を提供します","ko":"IntelliJ IDEA의 디버깅 기능은 강력한 로그 검색과 예외 분석 기능을 제공합니다","es":"Depuración de código en IntelliJ IDEA con recursos técnicos para Agents de IA. Aprende a diagnosticar problemas y optimizar tu código","fr":"Débogage de code dans IntelliJ IDEA avec des ressources techniques pour les outils d''IA. Découvrez comment diagnostiquer les problèmes et optimiser votre code","de":"Code-Debugging in IntelliJ IDEA mit technischen Ressourcen für KI-Tools. Erfahren Sie, wie Sie Probleme diagnostizieren und Ihren Code optimieren können","pt":"Depuração no IntelliJ IDEA inclui investigação de congelamentos, análise de exceções e busca no arquivo idea.log","ru":"Отладка в IntelliJ Platform включает в себя диагностику зависаний, анализ исключений и поиск в файле idea.log","ar":"تصحيح أخطاء أداة IntelliJ IDEA يتضمن تحليل التجميدات وتحليل الاستثناءات والبحث في ملف idea.log"},"seo":{"title":{"en":"Debugging: IntelliJ IDEA Setup Guide | AI Agent Skill","zh":"IntelliJ IDEA 调试设置指南","ja":"IntelliJ IDEA デバッグ設定ガイド - AIエージェント","ko":"IntelliJ IDEA 디버깅 설정 가이드 - AI 도구","es":"Guía de Depuración de IntelliJ IDEA","fr":"Débogage IntelliJ IDEA : Guide de Configuration","de":"IntelliJ IDEA-Debugging-Setup-Anleitung","pt":"Guia de Depuração do IntelliJ IDEA","ru":"ИИ Агенты: Руководство по отладке IntelliJ Platform","ar":"دليل تصحيح أخطاء أداة IntelliJ IDEA"},"description":{"en":"Unlock efficient debugging with IntelliJ IDEA & Platform. Learn how to investigate freezes, analyze exceptions, and master idea.log searches. Get started now!","zh":"学习如何使用IntelliJ IDEA进行调试，包括日志搜索和异常分析","ja":"IntelliJ IDEAでのデバッグ方法を学びましょう - ログ検索、例外分析など","ko":"IntelliJ IDEA에서 디버깅하는 방법을 알아보세요 - 로그 검색, 예외 분석 등","es":"Aprende a depurar código en IntelliJ IDEA con nuestras mejores prácticas y recursos técnicos para Agents de IA","fr":"Découvrez comment déboguer votre code dans IntelliJ IDEA avec nos meilleures pratiques et ressources techniques pour les outils d''IA","de":"Erfahren Sie, wie Sie Code in IntelliJ IDEA debuggen können, mit unseren besten Praktiken und technischen Ressourcen für KI-Tools","pt":"Aprenda a depurar código no IntelliJ IDEA com nossa guia passo a passo, incluindo dicas para investigar congelamentos e analisar exceções","ru":"Откройте для себя возможности отладки кода в IntelliJ Platform с помощью нашего пошагового руководства, включая советы по диагностике зависаний и анализу иск...","ar":"تعرف على كيفية تصحيح أخطاء التعليمات البرمجية في أداة IntelliJ IDEA باستخدام دليل خطوة بخطوة، بما في ذلك نصائح لتحليل التجميدات وتحليل الاستثناءات"},"definition":{"en":"Debugging is the process of identifying and fixing errors in code, involving techniques such as logging, exception analysis, and performance optimization.","zh":"调试是指使用IntelliJ IDEA等工具来查找和修复代码错误的过程","ja":"デバッグは、IntelliJ IDEAなどのツールを使用してコードのエラーを探し修正するプロセスです","ko":"디버깅은 IntelliJ IDEA 등의 도구를 사용하여 코드 오류를 찾고 수정하는 과정입니다","es":"La depuración es el proceso de identificar y corregir errores en el código, utilizando herramientas como IntelliJ IDEA","fr":"Le débogage est le processus d''identification et de correction des erreurs dans le code, en utilisant des outils tels que IntelliJ IDEA","de":"Das Debugging ist der Prozess der Identifizierung und Korrektur von Fehlern im Code, unter Verwendung von Tools wie IntelliJ IDEA","pt":"Depuração é o processo de identificação e correção de erros no código","ru":"Отладка - это процесс выявления и исправления ошибок в коде","ar":"تصحيح أخطاء هو عملية تحديد وتصحيح الأخطاء في التعليمات البرمجية"},"features":{"en":["Searches idea.log using specific log levels and patterns","Provides Logger FAQ for frequently asked logging questions","Offers guides on how to investigate freezes in IntelliJ IDEA","Includes Exception Analyzing FAQ for categorizing exceptions","Supports performance optimization through diagnostic techniques","Utilizes IntelliJ Platform for comprehensive debugging capabilities"],"zh":["日志搜索功能","异常分析能力","Logger FAQ文档","How to Investigate Freezes文档","Exception Analyzing FAQ文档","idea.log文件搜索"],"ja":["ログ検索機能","例外分析機能","Logger FAQドキュメント","How to Investigate Freezesドキュメント","Exception Analyzing FAQドキュメント","idea.logファイル検索"],"ko":["로그 검색 기능","예외 분석 기능","Logger FAQ 문서","How to Investigate Freezes 문서","Exception Analyzing FAQ 문서","idea.log 파일 검색"],"es":["Búsqueda en idea.log con patrones de niveles de registro","Análisis de excepciones con la FAQ de excepciones","Diagnóstico de congelamientos de la IDE con la guía de investigación","Uso de la plataforma IntelliJ para depuración","Configuración de la depuración en IntelliJ IDEA"],"fr":["Recherche dans idea.log avec des modèles de niveaux de journalisation","Analyse d''exceptions avec la FAQ d''exceptions","Diagnostic des gelés de l''IDE avec le guide d''investigation","Utilisation de la plate-forme IntelliJ pour le débogage","Configuration du débogage dans IntelliJ IDEA"],"de":["Suche in idea.log mit Muster für Log-Ebenen","Analyse von Ausnahmen mit der FAQ für Ausnahmen","Diagnose von IDE-Einfrieren mit dem Handbuch zur Untersuchung","Verwendung der IntelliJ-Plattform für das Debugging","Konfiguration des Debuggings in IntelliJ IDEA"],"pt":["Investigação de congelamentos no IntelliJ IDEA","Análise de exceções com o Exception Analyzing FAQ","Busca no arquivo idea.log com padrões de log","Uso do Logger FAQ para solucionar problemas de logging","Depuração de código no IntelliJ Platform"],"ru":["Диагностика зависаний в IntelliJ Platform","Анализ исключений с помощью Exception Analyzing FAQ","Поиск в файле idea.log с помощью шаблонов логирования","Использование Logger FAQ для решения проблем с логированием","Отладка кода в IntelliJ IDEA"],"ar":["تحليل التجميدات في أداة IntelliJ IDEA","تحليل الاستثناءات باستخدام Exception Analyzing FAQ","البحث في ملف idea.log باستخدام أنماط سجل","استخدام Logger FAQ لحل مشاكل التسجيل","تصحيح أخطاء التعليمات البرمجية في أداة IntelliJ Platform"]},"keywords":{"en":["how to use debugging in IntelliJ","what is debugging in software development","debugging alternative to print statements","debugging vs logging","intellij debugging setup guide","debugging install for IntelliJ IDEA","intellij platform debugging tutorial","debugging best practices for developers","intellij idea debugging tools"],"zh":["IntelliJ IDEA调试","日志搜索","异常分析","Logger FAQ","How to Investigate Freezes","Exception Analyzing FAQ","idea.log文件搜索","AIエージェント调试","代码错误修复"],"ja":["IntelliJ IDEAデバッグ","ログ検索","例外分析","Logger FAQ","How to Investigate Freezes","Exception Analyzing FAQ","idea.logファイル検索","AIエージェントデバッグ","コードエラーカテゴリ"],"ko":["IntelliJ IDEA디버깅","로그 검색","예외 분석","Logger FAQ","How to Investigate Freezes","Exception Analyzing FAQ","idea.log 파일 검색","AI 도구 디버깅","코드 오류 수정"],"es":["depuración de código","IntelliJ IDEA","Agents de IA","herramientas de depuración","diagnóstico de errores","optimización de código","niveles de registro","excepciones en Java"],"fr":["débogage de code","IntelliJ IDEA","outils d''IA","outils de débogage","diagnostic d''erreurs","optimisation de code","niveaux de journalisation","exceptions en Java"],"de":["Code-Debugging","IntelliJ IDEA","KI-Tools","Debugging-Tools","Fehlerdiagnose","Code-Optimierung","Log-Ebenen","Ausnahmen in Java"],"pt":["depuração intellij idea","intellij platform debugging","logger faq","exception analyzing faq","idea.log","congelamento intellij","análise de exceções","depuração de código"],"ru":["отладка intellij platform","intellij idea отладка","logger faq","exception analyzing faq","idea.log","зависание intellij","анализ исключений","отладка кода"],"ar":["تصحيح أخطاء أداة intellij idea","منصة intellij debugging","logger faq","exception analyzing faq","idea.log","تجميد أداة intellij","تحليل الاستثناءات","تصحيح أخطاء التعليمات البرمجية"]}},"owner":"JetBrains","repo":"intellij-community","repoPath":"JetBrains/intellij-community","stars":19773,"forks":5699,"updatedAt":"2026-03-08T01:25:45Z","topics":["code-editor","ide","intellij","intellij-community","intellij-platform"],"category":"community","skillMd":{"name":"debugging","description":"Debugging techniques and tools for IntelliJ development. Use when debugging IDE issues or investigating failures.","bodyPreview":"# Debugging\n\n## Documentation\n\n- [Logger FAQ](../docs/IntelliJ-Platform/4_man/Logger.md) - Frequently asked questions about logging\n- [How to Investigate Freezes](../docs/IntelliJ-Platform/4_man/Performance/How-To-Investigate-Freezes.md) - Diagnosing IDE freezes\n- [Exception Analyzing FAQ](../docs/IntelliJ-Platform/4_man/Exception-Analyzing-FAQ.md) - Analyzing and categorizing exceptions\n\n## Searching idea.log\n\nWhen debugging IntelliJ code, search `idea.log` using these patterns:\n\n**Log Levels:*","body":"# Debugging\n\n## Documentation\n\n- [Logger FAQ](../docs/IntelliJ-Platform/4_man/Logger.md) - Frequently asked questions about logging\n- [How to Investigate Freezes](../docs/IntelliJ-Platform/4_man/Performance/How-To-Investigate-Freezes.md) - Diagnosing IDE freezes\n- [Exception Analyzing FAQ](../docs/IntelliJ-Platform/4_man/Exception-Analyzing-FAQ.md) - Analyzing and categorizing exceptions\n\n## Searching idea.log\n\nWhen debugging IntelliJ code, search `idea.log` using these patterns:\n\n**Log Levels:**\n- `FINE` = debug level (from `LOG.debug { }`)\n- `INFO` = info level (from `LOG.info()`)\n\n**Category Format:**\n`#<abbreviated.package.path>.<ClassName>`\n\nExample: `com.intellij.openapi.wm.impl.status.IdeStatusBarImpl` → `#c.i.o.w.i.s.IdeStatusBarImpl`\n\n**Search Examples:**\n```bash\n# Debug logs from IdeStatusBarImpl\ngrep \"FINE - #c.i.o.w.i.s.IdeStatusBarImpl\" idea.log\n\n# Info logs from IdeStatusBarImpl\ngrep \"INFO - #c.i.o.w.i.s.IdeStatusBarImpl\" idea.log\n\n# All logs from a class\ngrep \"#c.i.o.w.i.s.IdeStatusBarImpl\" idea.log\n```\n\n## End-to-End Behavior\n\nWhen fixing issues where a user-facing entry point (script, command, API) doesn''t behave as expected:\n\n1. **Trace the full execution chain** from entry point to actual executor before making changes\n2. **Identify all layers** that handle the relevant behavior - each layer may swallow, transform, or ignore it\n3. **Verify the fix at the entry point** the user actually invokes, not just at the layer you modified\n4. **Add debugging output** if still unsure - add to all layers to trace the issue\n"},"lastSynced":"2026-03-08T01:58:14.712Z","agentAnalysis":{"suitability":{"en":"Ideal for Developer Agents requiring advanced IntelliJ IDEA debugging capabilities for diagnosing IDE freezes and analyzing exceptions.","zh":"适合需要高级 IntelliJ IDEA 调试功能的开发者代理，以诊断 IDE 冻结和分析异常。","ja":"IntelliJ IDEA の高度なデバッグ機能を必要とする開発者エージェントに適しています。IDE のフリーズを診断し、例外を分析するために使用します。","ko":"IntelliJ IDEA의 고급 디버깅 기능을 필요로 하는 개발자 에이전트에게 적합합니다. IDE의 동결을 진단하고 예외를 분석하는 데 사용됩니다.","es":"Ideal para Agentes de Desarrollador que requieren capacidades de depuración avanzadas de IntelliJ IDEA para diagnosticar bloqueos de IDE y analizar excepciones.","fr":"Idéal pour les agents de développement nécessitant des fonctionnalités de débogage avancées d''IntelliJ IDEA pour diagnostiquer les blocages de l''IDE et analyser les exceptions.","de":"Ideal für Developer-Agents, die erweiterte IntelliJ IDEA-Debugging-Funktionen zur Diagnose von IDE-Freeze und Analyse von Ausnahmen erfordern.","pt":"Ideal para Agentes de Desenvolvedor que exigem capacidades avançadas de depuração do IntelliJ IDEA para diagnosticar congelamentos do IDE e analisar exceções.","ru":"Идеально для агентов разработчиков, требующих расширенных возможностей отладки IntelliJ IDEA для диагностики зависаний IDE и анализа исключений.","ar":"مثالي لعميل المطور الذي يتطلب إمكانيات متقدمة لتصحيح أخطاء IntelliJ IDEA لتشخيص تجميد IDE وتحليل الاستثناءات."},"recommendation":{"en":"Empowers agents to investigate freezes, analyze exceptions, and optimize performance using logging, exception analysis, and idea.log searching with specific patterns and log levels like CRITICAL.","zh":"赋予代理调查冻结、分析异常和使用日志、异常分析和 idea.log 搜索来优化性能的能力，使用特定的模式和日志级别，如 CRITICAL。","ja":"エージェントがフリーズを調査し、例外を分析し、ロギング、例外分析、および idea.log 検索を使用して、CRITICAL などの特定のパターンとログ レベルでパフォーマンスを最適化する能力を付与します。","ko":"에이전트가 동결을 조사하고 예외를 분석하고 로깅, 예외 분석 및 idea.log 검색을 사용하여 성능을 최적화 할 수 있는 기능을 부여합니다. 특정 패턴 및 로그 수준(CRITICAL 등)을 사용합니다.","es":"Permite a los agentes investigar bloqueos, analizar excepciones y optimizar el rendimiento utilizando registros, análisis de excepciones y búsqueda de idea.log con patrones y niveles de registro específicos como CRITICAL.","fr":"Permet aux agents d''enquêter sur les blocages, d''analyser les exceptions et d''optimiser les performances en utilisant les journaux, l''analyse des exceptions et la recherche de idea.log avec des modèles et des niveaux de journalisation spécifiques comme CRITICAL.","de":"Ermöglicht es Agents, Freeze zu untersuchen, Ausnahmen zu analysieren und die Leistung zu optimieren, indem Protokolle, Ausnahmenanalyse und idea.log-Suche mit bestimmten Mustern und Protokollstufen wie CRITICAL verwendet werden.","pt":"Habilita os agentes a investigar congelamentos, analisar exceções e otimizar o desempenho usando registro, análise de exceções e pesquisa de idea.log com padrões e níveis de log específicos, como CRITICAL.","ru":"Наделяет агентов возможностью расследовать зависания, анализировать исключения и оптимизировать производительность с помощью журналирования, анализа исключений и поиска idea.log с конкретными шаблонами и уровнями журнала, такими как CRITICAL.","ar":"يمنح الوكلاء القدرة على التحقيق في تجميدات، وتحليل الاستثناءات، وضبط الأداء باستخدام التسجيل، و تحليل الاستثناءات، و بحث idea.log بنمط و مستوى سجل محدد، مثل CRITICAL."},"useCases":{"en":["Debugging IntelliJ code with idea.log","Analyzing and categorizing exceptions using Exception Analyzing FAQ","Diagnosing IDE freezes with How to Investigate Freezes guide"],"zh":["使用 idea.log 调试 IntelliJ 代码","使用 Exception Analyzing FAQ 分析和分类异常","使用 How to Investigate Freezes 指南诊断 IDE 冻结"],"ja":["idea.log を使用して IntelliJ コードをデバッグする","Exception Analyzing FAQ を使用して例外を分析および分類する","How to Investigate Freezes ガイドを使用して IDE のフリーズを診断する"],"ko":["idea.log를 사용하여 IntelliJ 코드 디버깅","Exception Analyzing FAQ를 사용하여 예외 분석 및 분류","How to Investigate Freezes 가이드를 사용하여 IDE 동결 진단"],"es":["Depuración de código IntelliJ con idea.log","Análisis y categorización de excepciones usando la FAQ de análisis de excepciones","Diagnóstico de bloqueos de IDE con la guía Cómo investigar bloqueos"],"fr":["Débogage de code IntelliJ avec idea.log","Analyse et catégorisation des exceptions en utilisant la FAQ d''analyse des exceptions","Diagnostic des blocages de l''IDE avec le guide Comment enquêter sur les blocages"],"de":["Debugging von IntelliJ-Code mit idea.log","Analyse und Kategorisierung von Ausnahmen unter Verwendung der FAQ zur Ausnahmenanalyse","Diagnose von IDE-Freeze mit dem Leitfaden zur Untersuchung von Freeze"],"pt":["Depuração de código IntelliJ com idea.log","Análise e categorização de exceções usando Exception Analyzing FAQ","Diagnóstico de congelamentos do IDE com o guia How to Investigate Freezes"],"ru":["Отладка кода IntelliJ с помощью idea.log","Анализ и категоризация исключений с помощью Exception Analyzing FAQ","Диагностика зависаний IDE с помощью руководства How to Investigate Freezes"],"ar":["تصحيح أخطاء رمز IntelliJ مع idea.log","تحليل وتصنيف الاستثناءات باستخدام Exception Analyzing FAQ","تشخيص تجميدات IDE مع دليل كيفية التحقيق في تجميدات"]},"limitations":{"en":["Requires IntelliJ IDEA or IntelliJ Platform installation","Specific to IntelliJ IDEA and its logging mechanisms"],"zh":["需要安装 IntelliJ IDEA 或 IntelliJ Platform","仅限于 IntelliJ IDEA 及其日志机制"],"ja":["IntelliJ IDEA または IntelliJ Platform のインストールが必要","IntelliJ IDEA 及びそのログメカニズムに限定される"],"ko":["IntelliJ IDEA 또는 IntelliJ 플랫폼 설치가 필요함","IntelliJ IDEA 및 로깅 메커니즘에만 특정됨"],"es":["Requiere la instalación de IntelliJ IDEA o IntelliJ Platform","Específico para IntelliJ IDEA y sus mecanismos de registro"],"fr":["Nécessite l''installation d''IntelliJ IDEA ou de la plate-forme IntelliJ","Spécifique à IntelliJ IDEA et à ses mécanismes de journalisation"],"de":["Benötigt die Installation von IntelliJ IDEA oder IntelliJ Platform","Spezifisch für IntelliJ IDEA und seine Protokollmechanismen"],"pt":["Exige instalação do IntelliJ IDEA ou plataforma IntelliJ","Específico para o IntelliJ IDEA e seus mecanismos de registro"],"ru":["Требует установки IntelliJ IDEA или платформы IntelliJ","Специфичен для IntelliJ IDEA и его механизмов журналирования"],"ar":["يتطلب تثبيت IntelliJ IDEA أو منصة IntelliJ","محدد ل IntelliJ IDEA وآليته التسجيلية"]},"version":4},"contentHash":"18f733870ca77424ccb7f7e862e49dc108de6b02858df8a3c64af5dede88a7e6","qualityScore":49}');
