INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('lawvable/awesome-legal-skills/statute-analysis-rafal-fryc', 'statute-analysis-rafal-fryc', 'lawvable', 'awesome-legal-skills', 'community', 'statute-analysis-rafal-fryc lawvable awesome-legal-skills community The statute-analysis-rafal-fryc skill provides a curated list of awesome Agent Skills for automating legal work, helping developers and legal professionals understand legislative intent and apply statutes to specific legal situations. statute-analysis-rafal-fryc技能提供了法律文本分析的技术指南，包括法令解释方法和立法意图 statute-analysis-rafal-frycスキルは、法令解釈と立法意図のための技術ガイドを提供します statute-analysis-rafal-fryc 기술은 법률 규정 분석을 위한 기술 가이드를 제공하며, 법령 해석 방법과 입법 의도를 포함합니다 El análisis de estatutos es una habilidad de agente de IA que ayuda a interpretar y aplicar leyes y regulaciones L''analyse de statuts est une compétence d''agent IA qui aide à interpréter et à appliquer les lois et les réglementations Die Gesetzesanalyse ist eine Fähigkeit des KI-Agents, die dabei hilft, Gesetze und Vorschriften zu interpretieren und anzuwenden O statute-analysis-rafal-fryc é uma habilidade de agente que fornece métodos de interpretação estatutária e canons de construção para automatizar o trabalho legal. Статут-анализ-рафал-фрайц - это навык агента, который предоставляет методы статутной интерпретации и каноны конструкции для автоматизации юридической работы на основе ИИ Агентов. مهارة الوكيل statue-analysis-rafal-fryc توفر أساليب تفسير المراسيم وقواعد البناء لتوفير الوقت في العمل القانوني باستخدام أدوات الذكاء الاصطناعي. how to use statute-analysis-rafal-fryc statute-analysis-rafal-fryc alternative statute-analysis-rafal-fryc install what is statute-analysis-rafal-fryc statute-analysis-rafal-fryc vs competitor statute-analysis-rafal-fryc setup guide 法令解释 法律文本分析 AI技术 法规分析 立法意图 跨司法管辖区合规 法令文本提取 法规解释 Provides guidance on how to read and interpret statutes, regulations, or rules Supports statutory interpretation methods and canons of construction Enables understanding of legislative intent and application of statutes to specific legal situations Extracts requirements from legal text and distinguishes between different types of legal requirements Performs cross-jurisdictional compliance analysis statute-analysis-rafal-fryc is a skill that enables statutory interpretation and analysis for automating legal work, covering methods and canons of construction, legislative intent, and cross-jurisdictional compliance analysis.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('danilonovaisv/PORTFOLIO-DANILO-FINAL/frontend-mobile-security-xss-scan', 'community', 'danilonovaisv', 'PORTFOLIO-DANILO-FINAL', 'danilonovaisv/PORTFOLIO-DANILO-FINAL', 'frontend-mobile-security-xss-scan', 1, 0, 49, '2026-03-08T00:31:07Z', '2026-03-08T02:00:48.941Z', 'df27098caa2b3fc77a194566002ffcaad8b7064210c5b3ca024ece43a7bf4a43', '{"id":"danilonovaisv/PORTFOLIO-DANILO-FINAL/frontend-mobile-security-xss-scan","name":"frontend-mobile-security-xss-scan","description":{"en":"The frontend-mobile-security-xss-scan skill analyzes frontend code to identify XSS vulnerabilities, benefiting developers working with React, Vue, Angular, and vanilla JavaScript.","zh":"本工具提供前端移动安全XSS漏洞扫描功能，支持React、Vue、Angular和JavaScript代码","ja":"このツールはフロントエンドモバイルセキュリティのXSS脆弱性をスキャンし、React、Vue、Angular、JavaScriptコードをサポートします","ko":"이 도구는 프론트엔드 모바일 보안 XSS 취약점을 스캔하고 React, Vue, Angular, JavaScript 코드를 지원합니다","es":"El escáner de vulnerabilidades XSS para frontend es una herramienta que analiza código React, Vue, Angular y JavaScript para detectar puntos de inyección y manipulación de DOM no seguros.","fr":"L''outil de détection de vulnérabilités XSS pour frontend est un outil qui analyse le code React, Vue, Angular et JavaScript pour détecter les points d''injection et la manipulation de DOM non sécurisés.","de":"Der XSS-Schwachstellen-Scanner für Frontend ist ein Tool, das React-, Vue-, Angular- und JavaScript-Code analysiert, um unsichere Injection-Punkte und DOM-Manipulationen zu erkennen.","pt":"Escaneie seu código frontend para detectar vulnerabilidades de XSS em React, Vue, Angular e JavaScript puro","ru":"Сканируйте свой фронтенд-код для обнаружения уязвимостей XSS в React, Vue, Angular и чистом JavaScript","ar":"افحص رمز الجبهة الخاص بك لاكتشاف الثغرات XSS في React و Vue و Angular و JavaScript النقي"},"seo":{"title":{"en":"frontend-mobile-security-xss-scan: XSS Vulnerability Scan...","zh":"前端移动安全XSS扫描工具设置指南","ja":"フロントエンドモバイルセキュリティXSSスキャンツールベストプラクティス","ko":"프론트엔드 모바일 보안 XSS 스캔 도구 설정 가이드","es":"Guía de configuración de escáner de vulnerabilidades XSS ...","fr":"Guide de configuration de l''outil de détection de vulnéra...","de":"Konfigurationsleitfaden für XSS-Schwachstellen-Scanner fü...","pt":"Guia de Configuração para Escaneamento de XSS em Frontend","ru":"Руководство по настройке сканера уязвимостей XSS для фрон...","ar":"دليل الإعداد لمسح ثغرات XSS في الجبهة"},"description":{"en":"Discover how to detect and prevent Cross-Site Scripting vulnerabilities in React, Vue, Angular, and vanilla JavaScript code with our expert guide - get start...","zh":"使用AIエージェント进行前端移动安全XSS漏洞扫描，保护您的React、Vue、Angular和JavaScript代码","ja":"AIエージェントを使用してフロントエンドモバイルセキュリティのXSS脆弱性をスキャンし、React、Vue、Angular、JavaScriptコードを保護します","ko":"AI 에이전트를 사용하여 프론트엔드 모바일 보안 XSS 취약점을 스캔하고 React, Vue, Angular, JavaScript 코드를 보호합니다","es":"Descubre cómo proteger tus aplicaciones frontend de ataques XSS con nuestro escáner de vulnerabilidades. Aprende a identificar puntos de inyección y manipula...","fr":"Découvrez comment protéger vos applications frontend contre les attaques XSS avec notre outil de détection de vulnérabilités. Apprenez à identifier les point...","de":"Erfahren Sie, wie Sie Ihre Frontend-Anwendungen vor XSS-Angriffen schützen können. Lernen Sie, wie Sie unsichere Injection-Punkte und DOM-Manipulationen iden...","pt":"Descubra como proteger seu aplicativo frontend contra ataques de XSS com nossa ferramenta de escaneamento","ru":"Узнайте, как защитить свое фронтенд-приложение от атак XSS с помощью нашей инструменты сканирования","ar":"اكتشف كيفية حماية تطبيق الجبهة من الهجمات XSS باستخدام أداة الفحص الخاصة بنا"},"definition":{"en":"frontend-mobile-security-xss-scan is a skill that detects and prevents Cross-Site Scripting vulnerabilities in frontend code, focusing on injection points and improper sanitization.","zh":"前端移动安全XSS扫描工具是一种用于检测和防止XSS漏洞的AIエージェント","ja":"フロントエンドモバイルセキュリティXSSスキャンツールはXSS脆弱性を検出して防ぐためのAIエージェントです","ko":"프론트엔드 모바일 보안 XSS 스캔 도구는 XSS 취약점을检测하고 방지하는 AI 에이전트입니다","es":"Un escáner de vulnerabilidades XSS para frontend es una herramienta que identifica puntos de inyección y manipulación de DOM no seguros en código frontend.","fr":"Un outil de détection de vulnérabilités XSS pour frontend est un outil qui identifie les points d''injection et la manipulation de DOM non sécurisés dans le code frontend.","de":"Ein XSS-Schwachstellen-Scanner für Frontend ist ein Tool, das unsichere Injection-Punkte und DOM-Manipulationen im Frontend-Code identifiziert.","pt":"Um escaneador de XSS é uma ferramenta que analisa código frontend para detectar vulnerabilidades de injeção de código","ru":"Сканер XSS - это инструмент, анализирующий фронтенд-код для обнаружения уязвимостей инъекции кода","ar":"ماسح XSS هو أداة تتحليل رمز الجبهة لاكتشاف ثغرات حقن الشفرة"},"features":{"en":["Analyzes React, Vue, Angular, and vanilla JavaScript code for XSS vulnerabilities","Identifies injection points and unsafe DOM manipulation","Detects improper sanitization in frontend code","Provides guidance on best practices for XSS vulnerability prevention","Supports workflow tasks related to XSS vulnerability scanning"],"zh":["支持React、Vue、Angular和JavaScript代码扫描","检测XSS注入点和不安全的DOM操作","提供XSS漏洞防止的最佳实践和检查清单","集成AIエージェント技术进行智能扫描","支持前端移动安全XSS漏洞扫描和防止"],"ja":["React、Vue、Angular、JavaScriptコードのスキャンをサポート","XSSの注入点と不安全なDOM操作を検出","XSS脆弱性防止のベストプラクティスとチェックリストを提供","AIエージェント技術を使用してスマートスキャンを実行","フロントエンドモバイルセキュリティのXSS脆弱性スキャンと防止をサポート"],"ko":["React, Vue, Angular, JavaScript 코드 스캔을 지원","XSS 주입점과 불안전한 DOM操作을 检出","XSS 취약점 방지를 위한 최적의 실践과 체크리스트를 제공","AI 에이전트 기술을 사용하여 스마트 스캔을 수행","프론트엔드 모바일 보안 XSS 취약점 스캔과 방지를 지원"],"es":["Análisis de código React, Vue, Angular y JavaScript","Detección de puntos de inyección y manipulación de DOM no seguros","Identificación de vulnerabilidades XSS en aplicaciones frontend","Compatibilidad con frameworks frontend populares","Escaneo de código para detectar patrones de ataque comunes"],"fr":["Analyse de code React, Vue, Angular et JavaScript","Détection de points d''injection et de manipulation de DOM non sécurisés","Identification de vulnérabilités XSS dans les applications frontend","Compatibilité avec les frameworks frontend populaires","Analyse de code pour détecter les modèles d''attaque courants"],"de":["Analyse von React-, Vue-, Angular- und JavaScript-Code","Erkennung von unsicheren Injection-Punkten und DOM-Manipulationen","Identifizierung von XSS-Schwachstellen in Frontend-Anwendungen","Kompatibilität mit beliebten Frontend-Frameworks","Code-Scan zur Erkennung von gängigen Angriffsmustern"],"pt":["Análise de código React para detectar injeção de código","Verificação de manipulação de DOM em Vue","Detecção de sanitização inadequada em Angular","Escaneamento de código JavaScript puro para vulnerabilidades de XSS","Identificação de pontos de injeção de código em aplicativos frontend","Fornecimento de orientação e práticas recomendadas para prevenir ataques de XSS"],"ru":["Анализ кода React для обнаружения инъекции кода","Проверка манипуляции DOM в Vue","Обнаружение недостаточной санитизации в Angular","Сканирование чистого JavaScript для уязвимостей XSS","Определение точек инъекции кода в фронтенд-приложениях","Предоставление рекомендаций и лучших практик для предотвращения атак XSS"],"ar":["تحليل رمز React لاكتشاف حقن الشفرة","التحقق من مаниبولات DOM في Vue","اكتشاف التطهير غير الكافي في Angular","فحص JavaScript النقي لثغرات XSS","تحديد نقاط حقن الشفرة في تطبيقات الجبهة","توفير الإرشادات وأفضل الممارسات لمنع الهجمات XSS"]},"keywords":{"en":["how to use frontend-mobile-security-xss-scan","frontend-mobile-security-xss-scan alternative","xss vulnerability scanner for frontend code","frontend-mobile-security-xss-scan setup guide","what is frontend-mobile-security-xss-scan","frontend-mobile-security-xss-scan vs other scanners","install frontend-mobile-security-xss-scan","frontend-mobile-security-xss-scan for React developers","frontend-mobile-security-xss-scan for Angular developers","frontend-mobile-security-xss-scan for Vue developers"],"zh":["前端移动安全","XSS扫描","AIエージェント","React安全","Vue安全","Angular安全","JavaScript安全","XSS防止","前端安全最佳实践"],"ja":["フロントエンドモバイルセキュリティ","XSSスキャン","AIエージェント","Reactセキュリティ","Vueセキュリティ","Angularセキュリティ","JavaScriptセキュリティ","XSS防止","フロントエンドセキュリティベストプラクティス"],"ko":["프론트엔드 모바일 보안","XSS 스캔","AI 에이전트","React 보안","Vue 보안","Angular 보안","JavaScript 보안","XSS 방지","프론트엔드 보안 최적의 실践"],"es":["escáner de vulnerabilidades XSS","seguridad frontend","protección contra ataques XSS","análisis de código frontend","detección de vulnerabilidades","React seguridad","Vue seguridad","Angular seguridad"],"fr":["outil de détection de vulnérabilités XSS","sécurité frontend","protection contre les attaques XSS","analyse de code frontend","détection de vulnérabilités","sécurité React","sécurité Vue","sécurité Angular"],"de":["XSS-Schwachstellen-Scanner","Frontend-Sicherheit","Schutz vor XSS-Angriffen","Frontend-Code-Analyse","Schwachstellen-Erkennung","React-Sicherheit","Vue-Sicherheit","Angular-Sicherheit"],"pt":["escaneamento de xss","segurança frontend","vulnerabilidades de xss","react xss","vue xss","angular xss","javascript xss","prevenção de ataques de xss","ferramentas de segurança frontend"],"ru":["сканирование xss","безопасность фронтенда","уязвимости xss","react xss","vue xss","angular xss","javascript xss","предотвращение атак xss","инструменты безопасности фронтенда"],"ar":["فحص xss","أمن الجبهة","ثغرات xss","react xss","vue xss","angular xss","javascript xss","منع الهجمات xss","أدوات أمن الجبهة"]}},"owner":"danilonovaisv","repo":"PORTFOLIO-DANILO-FINAL","repoPath":"danilonovaisv/PORTFOLIO-DANILO-FINAL","stars":1,"forks":0,"updatedAt":"2026-03-08T00:31:07Z","topics":[],"category":"community","skillMd":{"name":"frontend-mobile-security-xss-scan","description":"You are a frontend security specialist focusing on Cross-Site Scripting (XSS) vulnerability detection and prevention. Analyze React, Vue, Angular, and vanilla JavaScript code to identify injection poi","version":"4.1.0-fractal","bodyPreview":"# XSS Vulnerability Scanner for Frontend Code\n\nYou are a frontend security specialist focusing on Cross-Site Scripting (XSS) vulnerability detection and prevention. Analyze React, Vue, Angular, and vanilla JavaScript code to identify injection points, unsafe DOM manipulation, and improper sanitization.\n\n## Use this skill when\n\n- Working on xss vulnerability scanner for frontend code tasks or workflows\n- Needing guidance, best practices, or checklists for xss vulnerability scanner for frontend co","body":"# XSS Vulnerability Scanner for Frontend Code\n\nYou are a frontend security specialist focusing on Cross-Site Scripting (XSS) vulnerability detection and prevention. Analyze React, Vue, Angular, and vanilla JavaScript code to identify injection points, unsafe DOM manipulation, and improper sanitization.\n\n## Use this skill when\n\n- Working on xss vulnerability scanner for frontend code tasks or workflows\n- Needing guidance, best practices, or checklists for xss vulnerability scanner for frontend code\n\n## Do not use this skill when\n\n- The task is unrelated to xss vulnerability scanner for frontend code\n- You need a different domain or tool outside this scope\n\n## Context\n\nThe user needs comprehensive XSS vulnerability scanning for client-side code, identifying dangerous patterns like unsafe HTML manipulation, URL handling issues, and improper user input rendering. Focus on context-aware detection and framework-specific security patterns.\n\n## Requirements\n\n$ARGUMENTS\n\n## Instructions\n\n## 🧠 Knowledge Modules (Fractal Skills)\n\n### 1. [1. XSS Vulnerability Detection](./sub-skills/1-xss-vulnerability-detection.md)\n\n### 2. [2. Framework-Specific Detection](./sub-skills/2-framework-specific-detection.md)\n\n### 3. [3. Secure Coding Examples](./sub-skills/3-secure-coding-examples.md)\n\n### 4. [4. Automated Scanning Integration](./sub-skills/4-automated-scanning-integration.md)\n\n### 5. [5. Report Generation](./sub-skills/5-report-generation.md)\n\n### 6. [6. Prevention Checklist](./sub-skills/6-prevention-checklist.md)\n"},"lastSynced":"2026-03-08T02:00:48.941Z","agentAnalysis":{"suitability":{"en":"Perfect for Web Security Agents needing advanced Cross-Site Scripting (XSS) vulnerability detection and prevention capabilities in React, Vue, Angular, and vanilla JavaScript codebases.","zh":"非常适合需要在React、Vue、Angular和vanilla JavaScript代码库中高级跨站脚本（XSS）漏洞检测和防御能力的Web安全代理。","ja":"React、Vue、Angular、vanilla JavaScriptコードベースで高度なクロスサイトスクリプティング（XSS）脆弱性の検出および防止能力が必要なWebセキュリティエージェントに最適です。","ko":"React, Vue, Angular 및 vanilla JavaScript 코드베이스에서 고급 크로스 사이트 스크립팅(XSS) 취약성 탐지 및 방지 능력이 필요한 웹 보안 에이전트에 적합합니다.","es":"Perfecto para agentes de seguridad web que necesitan capacidades avanzadas de detección y prevención de vulnerabilidades de scripting entre sitios (XSS) en codebases de React, Vue, Angular y JavaScript vanilla.","fr":"Parfait pour les agents de sécurité Web nécessitant des capacités avancées de détection et de prévention des vulnérabilités de scripting entre sites (XSS) dans les codebases React, Vue, Angular et JavaScript vanilla.","de":"Perfekt für Web-Sicherheitsagenten, die erweiterte Fähigkeiten zur Erkennung und Verhinderung von Cross-Site-Scripting-(XSS)-Schwachstellen in React-, Vue-, Angular- und JavaScript-Vanilla-Codebasen benötigen.","pt":"Perfeito para Agentes de Segurança da Web que necessitam de capacidades avançadas de detecção e prevenção de vulnerabilidades de Cross-Site Scripting (XSS) em codebases React, Vue, Angular e JavaScript vanilla.","ru":"Идеально подходит для Веб-Агентов безопасности, которым необходимы расширенные возможности обнаружения и предотвращения уязвимостей Cross-Site Scripting (XSS) в кодовых базах React, Vue, Angular и ванильном JavaScript.","ar":"مثالي للوكلاء الأمنيين على الويب الذين يحتاجون إلى إمكانيات متقدمة لاكتشاف وتحديد نقاط الضعف في هجمات Cross-Site Scripting (XSS) في قواعد كود React و Vue و Angular و JavaScript العادي."},"recommendation":{"en":"Empowers agents to analyze frontend code for XSS vulnerabilities, identifying injection points, unsafe DOM manipulation, and improper sanitization, ensuring secure coding practices with libraries like React, Vue, and Angular, and supporting protocols such as HTTP and HTTPS.","zh":"赋予代理分析前端代码以检测XSS漏洞的能力，识别注入点、不安全的DOM操作和不当的清理，确保使用React、Vue和Angular等库的安全编码实践，并支持HTTP和HTTPS等协议。","ja":"エージェントにフロントエンドコードを分析してXSS脆弱性を検出する能力を付与し、インジェクションポイント、安全でないDOM操作、および不適切なサニタイズを識別し、React、Vue、Angularなどのライブラリを使用したセキュアなコーディング慣行を確保し、HTTPおよびHTTPSなどのプロトコルをサポートします。","ko":"에이전트가 XSS 취약성을检测하기 위해 프론트엔드 코드를 분석할 수 있는 능력을 부여하며, 주입 지점, 안전하지 않은 DOM 조작 및 부적절한 정제를 식별하고, React, Vue 및 Angular와 같은 라이브러리를 사용하여 보안 코딩 관행을 보장하며, HTTP 및 HTTPS와 같은 프로토콜을 지원합니다.","es":"Habilita a los agentes a analizar el código frontend para detectar vulnerabilidades de XSS, identificar puntos de inyección, manipulación de DOM no segura y desinfección inadecuada, garantizando prácticas de codificación seguras con bibliotecas como React, Vue y Angular, y admitiendo protocolos como HTTP y HTTPS.","fr":"Permet aux agents d''analyser le code frontend pour détecter les vulnérabilités de XSS, en identifiant les points d''injection, la manipulation non sécurisée du DOM et la désinfection inadéquate, en garantissant des pratiques de codage sécurisées avec des bibliothèques telles que React, Vue et Angular, et en prenant en charge des protocoles tels que HTTP et HTTPS.","de":"Ermöglicht es den Agenten, den Frontend-Code auf XSS-Schwachstellen zu analysieren, Einspeispunkte zu identifizieren, unsichere DOM-Manipulation und unzureichende Sanitierung zu erkennen, um sichere Codierungspraktiken mit Bibliotheken wie React, Vue und Angular sicherzustellen und Protokolle wie HTTP und HTTPS zu unterstützen.","pt":"Habilita os agentes a analisar o código frontend para vulnerabilidades de XSS, identificando pontos de injeção, manipulação de DOM insegura e sanitização imprópria, garantindo práticas de codificação seguras com bibliotecas como React, Vue e Angular, e suportando protocolos como HTTP e HTTPS.","ru":"Наделяет агентов возможностью анализировать код frontend на наличие уязвимостей XSS, выявляя точки инъекции, небезопасную манипуляцию DOM и неправильную санитизацию, обеспечивая безопасные практики кодирования с использованием библиотек như React, Vue и Angular, а также поддерживая протоколы такие как HTTP и HTTPS.","ar":"تمكّن الوكلاء من分析 كود البرنامج الأمامي لاكتشاف نقاط الضعف في هجمات XSS، وتحديد نقاط الحقن والتحكم غير الآمن في واجهة المستخدم والتنظيف غير الصحيح، وضمان ممارسات برمجة آمنة باستخدام مكتبات مثل React و Vue و Angular، ودعم بروتوكولات مثل HTTP و HTTPS."},"useCases":{"en":["Scanning React applications for XSS vulnerabilities","Identifying insecure DOM manipulation in Vue codebases","Detecting improper input sanitization in Angular projects"],"zh":["扫描React应用程序以检测XSS漏洞","在Vue代码库中识别不安全的DOM操作","在Angular项目中检测不当的输入清理"],"ja":["XSS脆弱性を検出するためにReactアプリケーションをスキャンする","Vueコードベースで安全でないDOM操作を識別する","Angularプロジェクトで不適切な入力サニタイズを検出する"],"ko":["XSS 취약성을检测하기 위해 React 애플리케이션을 스캔하는 것","Vue 코드베이스에서 안전하지 않은 DOM 조작을 식별하는 것","Angular 프로젝트에서 부적절한 입력 정제를检测하는 것"],"es":["Análisis de aplicaciones React en busca de vulnerabilidades de XSS","Identificación de manipulación de DOM insegura en codebases de Vue","Detección de desinfección inadecuada de entrada en proyectos de Angular"],"fr":["Analyse d''applications React pour détecter les vulnérabilités de XSS","Identification de la manipulation non sécurisée du DOM dans les codebases de Vue","Détection d''une désinfection inadéquate des entrées dans les projets Angular"],"de":["Überprüfung von React-Anwendungen auf XSS-Schwachstellen","Identifizierung unsicherer DOM-Manipulation in Vue-Codebasen","Erkennung unzureichender Eingabesanitierung in Angular-Projekten"],"pt":["Varredura de aplicações React para vulnerabilidades de XSS","Identificação de manipulação de DOM insegura em codebases Vue","Detecção de sanitização de entrada imprópria em projetos Angular"],"ru":["Сканирование приложений React на наличие уязвимостей XSS","Выявление небезопасной манипуляции DOM в кодовых базах Vue","Обнаружение неправильной санитизации входных данных в проектах Angular"],"ar":["فحص تطبيقات React لاكتشاف نقاط الضعف في هجمات XSS","تحديد التحكم غير الآمن في واجهة المستخدم في قواعد كود Vue","اكتشاف التنظيف غير الصحيح للإدخال في مشاريع Angular"]},"limitations":{"en":["Requires access to frontend codebases","Limited to React, Vue, Angular, and vanilla JavaScript frameworks"],"zh":["需要访问前端代码库","仅限React、Vue、Angular和vanilla JavaScript框架"],"ja":["フロントエンドコードベースへのアクセスが必要","React、Vue、Angular、vanilla JavaScriptフレームワークのみ"],"ko":["프론트엔드 코드베이스에 접근할 수 있어야 함","React, Vue, Angular 및 vanilla JavaScript 프레임워크만 지원"],"es":["Requiere acceso a los codebases frontend","Limitado a los frameworks React, Vue, Angular y JavaScript vanilla"],"fr":["Nécessite un accès aux codebases frontend","Limité aux frameworks React, Vue, Angular et JavaScript vanilla"],"de":["Benötigt Zugriff auf die Frontend-Codebasen","Begrenzt auf die Frameworks React, Vue, Angular und JavaScript-Vanilla"],"pt":["Requer acesso a codebases frontend","Limitado a frameworks React, Vue, Angular e JavaScript vanilla"],"ru":["Требует доступа к кодовым базам frontend","Ограничен фреймворками React, Vue, Angular и ванильным JavaScript"],"ar":["يتطلب الوصول إلى قواعد كود البرنامج الأمامي","محدود بالإطارات React و Vue و Angular و JavaScript العادي"]},"version":4},"contentHash":"df27098caa2b3fc77a194566002ffcaad8b7064210c5b3ca024ece43a7bf4a43","qualityScore":49}');
