INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('rand/cc-polymath/discover-testing', 'discover-testing', 'rand', 'cc-polymath', 'community', 'discover-testing rand cc-polymath community The discover-testing skill provides automatic access to comprehensive testing skills, benefiting developers working with testing, unit tests, and integration. It auto-activates for tasks like TDD and test coverage. 发现测试技能，提供自动化测试解决方案，包括e2e、集成、单元测试等 テストスキルを自動で発見、e2e、統合、ユニットテストなどの解決策を提供 테스팅 스킬 자동 발견, e2e, 통합, 유닛 테스트 등 솔루션 제공 Discover-testing ofrece habilidades de testing automatizado para mejorar la eficiencia y calidad de tus pruebas de software Discover-testing propose des compétences de test automatisé pour améliorer l''efficacité et la qualité de vos tests de logiciel Discover-testing bietet Fähigkeiten für automatisierte Tests, um die Effizienz und Qualität Ihrer Software-Tests zu verbessern O skill discover-testing fornece acesso automático a habilidades de teste abrangentes, incluindo testes unitários, de integração e de ponta a ponta. Навык discover-testing предоставляет автоматический доступ к комплексным навыкам тестирования, включая юнит-тесты, интеграционные тесты и тесты от конца до конца. المهارة discover-testing توفر وصولاً 자동ياً إلى مهارات اختبار شاملة، بما في ذلك الاختبارات الوحدوية والتكاملية والاختبارات من النهاية إلى النهاية. how to use discover-testing discover-testing alternative discover-testing setup guide what is discover-testing discover-testing vs testing frameworks discover-testing install automated testing with discover-testing discover-testing for unit testing discover-testing for integration testing discover-testing workflow optimization AIエージェント工具 自动化测试 e2e测试 集成测试 单元测试 性能测试 测试驱动开发 测试覆盖率策略 Auto-activates for testing tasks like unit tests, integration, and e2e Provides access to 6 testing skills, including performance-testing and test-driven-development Supports test coverage strategy and optimization Enables efficient workflow for TDD and test coverage Includes skills for e2e-testing and integration-testing Offers quick reference for testing skills discovery discover-testing is a skill that provides automatic access to comprehensive testing skills, including e2e-testing, integration-testing, and unit-testing, for efficient testing workflows.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('tutur3u/platform/flutter-expert', 'community', 'tutur3u', 'platform', 'tutur3u/platform', 'flutter-expert', 0, 0, 49, '2026-03-08T01:57:15.326Z', '2026-03-08T02:03:03.514Z', '90aaa4d66ca184b017360a807b1b2d9aba62d037f7a37eb0fcf287acceccc2dd', '{"id":"tutur3u/platform/flutter-expert","name":"flutter-expert","description":{"en":"The flutter-expert skill enables senior mobile engineers to build high-performance cross-platform applications with Flutter 3 and Dart, specializing in state management and app development for iOS, Android, Web, and Desktop.","zh":"Flutter Expert 是一名高级移动工程师，专门使用 Flutter 3 和 Dart 构建高性能跨平台应用。支持状态管理和路由","ja":"Flutter Expert は、高性能のクロスプラットフォームアプリを開発するために Flutter 3 と Dart を使用するシニアモバイルエンジニアです。状態管理とルーティングをサポート","ko":"Flutter Expert는 고성능 크로스 플랫폼 애플리케이션을 개발하는 데 전문적인 시니어 모바일 엔지니어입니다. 상태 관리와 라우팅을 지원","es":"Flutter Expert es un senior mobile engineer que construye aplicaciones cross-plataforma de alto rendimiento con Flutter 3 y Dart.","fr":"Flutter Expert est un ingénieur mobile senior qui construit des applications multi-plateformes haute performance avec Flutter 3 et Dart.","de":"Flutter Expert ist ein Senior-Mobile-Ingenieur, der cross-plattformige Anwendungen mit Flutter 3 und Dart entwickelt.","pt":"O Flutter Expert é um especialista em desenvolvimento móvel que cria aplicações cross-platform de alto desempenho com Flutter 3 e Dart.","ru":"ИИ Агент Flutter Expert - это специалист по мобильной разработке, создающий высокопроизводительные кросс-платформенные приложения с Flutter 3 и Dart.","ar":"خبير Flutter هو خبير في التنمية المتنقلة الذي يخلق تطبيقات متعددة المنصات عالية الأداء مع Flutter 3 و Dart."},"seo":{"title":{"en":"flutter-expert: Cross-Platform App Development Setup Guid...","zh":"Flutter Expert 指南：高性能跨平台应用开发","ja":"Flutter Expert のセットアップガイド：AI エージェントによるクロスプラットフォームアプリ開発","ko":"Flutt