INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('tutur3u/platform/flutter-expert', 'flutter-expert', 'tutur3u', 'platform', 'community', 'flutter-expert tutur3u platform community The flutter-expert skill enables senior mobile engineers to build high-performance cross-platform applications with Flutter 3 and Dart, specializing in state management and app development for iOS, Android, Web, and Desktop. Flutter Expert 是一名高级移动工程师，专门使用 Flutter 3 和 Dart 构建高性能跨平台应用。支持状态管理和路由 Flutter Expert は、高性能のクロスプラットフォームアプリを開発するために Flutter 3 と Dart を使用するシニアモバイルエンジニアです。状態管理とルーティングをサポート Flutter Expert는 고성능 크로스 플랫폼 애플리케이션을 개발하는 데 전문적인 시니어 모바일 엔지니어입니다. 상태 관리와 라우팅을 지원 Flutter Expert es un senior mobile engineer que construye aplicaciones cross-plataforma de alto rendimiento con Flutter 3 y Dart. Flutter Expert est un ingénieur mobile senior qui construit des applications multi-plateformes haute performance avec Flutter 3 et Dart. Flutter Expert ist ein Senior-Mobile-Ingenieur, der cross-plattformige Anwendungen mit Flutter 3 und Dart entwickelt. O Flutter Expert é um especialista em desenvolvimento móvel que cria aplicações cross-platform de alto desempenho com Flutter 3 e Dart. ИИ Агент Flutter Expert - это специалист по мобильной разработке, создающий высокопроизводительные кросс-платформенные приложения с Flutter 3 и Dart. خبير Flutter هو خبير في التنمية المتنقلة الذي يخلق تطبيقات متعددة المنصات عالية الأداء مع Flutter 3 و Dart. how to use flutter-expert flutter-expert alternative flutter-expert setup guide what is flutter-expert flutter-expert vs React Native flutter-expert install flutter-expert for iOS development flutter-expert for Android development flutter-expert with Riverpod 2.0 flutter-expert with GoRouter Flutter Expert 跨平台应用开发 Flutter 3 Dart 状态管理 Riverpod 2.0 路由 GoRouter iOS Android Web Desktop Builds cross-platform Flutter applications for iOS, Android, Web, and Desktop Implements state management using Riverpod 2.0 Utilizes GoRouter for efficient routing Writes performant and maintainable Dart code Supports Flutter 3.19+ for latest features and updates Enables proper state management for scalable app development flutter-expert is a senior mobile engineer skill for building high-performance cross-platform applications with Flutter 3 and Dart, utilizing Riverpod 2.0 and GoRouter.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('slym1v98/flownest-flutter/dart-expert', 'community', 'slym1v98', 'flownest-flutter', 'slym1v98/flownest-flutter', 'dart-expert', 0, 0, 49, '2026-03-08T01:57:15.338Z', '2026-03-08T02:03:23.672Z', '216b143d00028aa6bb10ea337513aa1fab5f340357e181ab9a48bbd4057c75d4', '{"id":"slym1v98/flownest-flutter/dart-expert","name":"dart-expert","description":{"en":"The dart-expert skill provides expert guidance for Dart programming and Flutter framework, benefiting developers who build mobile and cross-platform applications. It covers core concepts like strong typing and null safety.","zh":"Dart Expert 提供了强大的 Dart 编程和 Flutter 框架指导，帮助开发者提高移动开发和跨平台应用的效率","ja":"Dart Expert は、強力な Dart プログラミングと Flutter フレームワークのガイダンスを提供し、開発者がモバイル開発とクロスプラットフォームアプリケーションの効率を高めることができます","ko":"Dart Expert 는 강력한 Dart 프로그래밍과 Flutter 프레임워크 가이드를 제공하여 개발자가 모바일 개발과 크로스 플랫폼 애플리케이션의 효율성을 높일 수 있습니다","es":"Nuestro experto en Dart ofrece guías y mejores prácticas para desarrolladores en Dart y Flutter, cubriendo conceptos como la programación asíncrona y la seguridad de tipos","fr":"Notre expert Dart propose des guides et des meilleures pratiques pour les développeurs en Dart et Flutter, couvrant des concepts tels que la programmation asynchrone et la sécurité des types","de":"Unser Dart-Experte bietet Anleitungen und Best Practices für Entwickler in Dart und Flutter, einschließlich Konzepten wie asynchroner Programmierung und Typsicherheit","pt":"O Dart Expert fornece orientação sobre programação Dart, framework Flutter e desenvolvimento móvel","ru":"ИИ Агент Dart Expert предоставляет экспертное руководство по программированию на Dart и разработке кроссплатформенных приложений","ar":"خبير دارت يقدم إرشادات حول برمجة دارت وإطار عمل فلاتر وتطوير التطبيقات الموبايل"},"seo":{"title":{"en":"dart-expert: Mastering Dart and Flutter Development | AI ...","zh":"Dart Expert 指南：强大的移动开发和跨平台应用","ja":"Dart Expert セットアップガイド：モバイル開発とクロスプラットフォームアプリケーション","ko":"Dart Expert 가이드: 모바일 개발과 크로스 플랫폼 애플리케이션","es":"Guía de configuración de Dart Expert para desarrolladores","fr":"Guide de mise en route de Dart Expert pour les développeurs","de":"Einrichtungsleitfaden für Dart-Experten für Entwickler","pt":"Guia de Configuração do Dart Expert para Desenvolvedores","ru":"ИИ Агент Dart Expert: Руководство по Настройке","ar":"دليل إعداد خبير دارت للبرمجة"},"description":{"en":"Unlock expert-level Dart and Flutter development with dart-expert. Learn how to harness async/await, Streams, and State management for seamless cross-platfor...","zh":"了解 Dart 和 Flutter 的核心概念，包括强类型、异步/等待、流、混合和扩展等，AIエージェント帮助您提高开发效率","ja":"Dart と Flutter の核心概念を学び、強いタイピング、非同期/待機、ストリーム、ミックスインと拡張などをマスターして、モバイル開発とクロスプラットフォームアプリケーションを効率化する、AIエージェント","ko":"Dart 와 Flutter 의 핵심 개념을 학습하여 강한 타이핑, 비동기/대기, 스트림, 믹스인 및 확장 등을 마스터하고, 모바일 개발과 크로스 플랫폼 애플리케이션을 효율화하는 AI 도구","es":"Mejora tus habilidades en Dart y Flutter con nuestro experto en AI. Aprende sobre programación asíncrona, Streams y seguridad de tipos","fr":"Améliorez vos compétences en Dart et Flutter avec notre expert AI. Découvrez la programmation asynchrone, les Streams et la sécurité des types","de":"Verbessern Sie Ihre Fähigkeiten in Dart und Flutter mit unserem AI-Experten. Erfahren Sie mehr über asynchrone Programmierung, Streams und Typsicherheit","pt":"Aprenda a configurar e utilizar o Dart Expert para desenvolver aplicativos móveis e cross-platform com Flutter","ru":"Получите экспертное руководство по разработке на Dart и созданию кроссплатформенных приложений с помощью ИИ Агента","ar":"تعلم كيفية إعداد وتشغيل خبير دارت لإنشاء تطبيقات موبايل ومتعددة المنصات باستخدام فلاتر"},"definition":{"en":"dart-expert is a specialized AI agent skill that offers in-depth knowledge and expertise in Dart and Flutter development, including core language features and framework-specific capabilities.","zh":"Dart Expert 是一种提供 Dart 编程和 Flutter 框架指导的 AI エージェント","ja":"Dart Expert は、Dart プログラミングと Flutter フレームワークのガイダンスを提供する AI エージェントです","ko":"Dart Expert 는 Dart 프로그래밍과 Flutter 프레임워크 가이드를 제공하는 AI 도구입니다","es":"Un experto en Dart es un agente de IA que proporciona orientación y soporte para desarrolladores en Dart y Flutter","fr":"Un expert Dart est un agent IA qui fournit des conseils et un support pour les développeurs en Dart et Flutter","de":"Ein Dart-Experte ist ein KI-Agent, der Anleitung und Unterstützung für Entwickler in Dart und Flutter bietet","pt":"O que é Dart Expert? É um agente de IA que fornece orientação sobre programação Dart e desenvolvimento móvel","ru":"Что такое ИИ Агент Dart Expert? Это агент, предоставляющий экспертное руководство по разработке на Dart","ar":"ما هو خبير دارت؟ هو وكيل ذكاء اصطناعي يقدم إرشادات حول برمجة دارت وتطوير التطبيقات الموبايل"},"features":{"en":["Provides strong typing with type inference for robust Dart applications","Supports async/await and Futures for efficient asynchronous programming","Utilizes Streams for reactive programming and real-time data handling","Offers expertise in State management using Provider, Riverpod, and Bloc","Enables responsive layouts and platform integration for seamless user experiences","Covers Material and Cupertino design for consistent cross-platform UI"],"zh":["强类型和类型推断","异步/等待和 Futures","流和混合","Null 安全性和集合","Flutter 框架和小部件"],"ja":["強いタイピングとタイプ推論","非同期/待機と Futures","ストリームとミックスイン","Null 安全性とコレクション","Flutter フレームワークとウィジェット"],"ko":["강한 타이핑과 타입 추론","비동기/대기와 Futures","스트림과 믹스인","Null 안전성과 컬렉션","Flutter 프레임워크와 위젯"],"es":["Programación asíncrona con Async/await y Futures","Trabajando con Streams y Mixins","Seguridad de tipos con inferencia de tipos","Desarrollo de aplicaciones móviles con Flutter","Gestión de estado con Provider, Riverpod y Bloc"],"fr":["Programmation asynchrone avec Async/await et Futures","Travail avec des Streams et des Mixins","Sécurité des types avec inférence de types","Développement d''applications mobiles avec Flutter","Gestion d''état avec Provider, Riverpod et Bloc"],"de":["Asynchrone Programmierung mit Async/await und Futures","Arbeiten mit Streams und Mixins","Typsicherheit mit Typinferenz","Entwicklung von mobilen Anwendungen mit Flutter","Zustandsverwaltung mit Provider, Riverpod und Bloc"],"pt":["Suporte à linguagem Dart com tipagem forte e inferência de tipo","Utilização de Async/await e Futures para programação assíncrona","Trabalho com Streams e Mixins para desenvolvimento de aplicativos","Gerenciamento de estado com Provider, Riverpod e Bloc","Criação de layouts responsivos com Material e Cupertino design"],"ru":["Поддержка языка Dart с сильной типизацией и типовыми выводами","Использование Async/await и Futures для асинхронного программирования","Работа со Streams и Mixins для разработки приложений","Управление состоянием с помощью Provider, Riverpod и Bloc","Создание адаптивных макетов с помощью Material и Cupertino design"],"ar":["دعم لغة دارت مع نوع قوي وتحديد النوع","استخدام Async/await و Futures للبرمجة غير المتزامنة","العمل مع Streams و Mixins لتطوير التطبيقات","إدارة الحالة مع Provider و Riverpod و Bloc","إنشاء تصاميم مستجيبة مع Material و Cupertino design"]},"keywords":{"en":["how to use dart-expert","dart-expert vs flutter","dart-expert setup guide","what is dart-expert","dart-expert alternative","dart-expert install","dart programming tutorial","flutter framework guide","cross-platform app development","dart-expert documentation"],"zh":["Dart 编程","Flutter 框架","移动开发","跨平台应用","AI エージェント","Dart Expert","强类型","异步/等待","流"],"ja":["Dart プログラミング","Flutter フレームワーク","モバイル開発","クロスプラットフォームアプリケーション","AI エージェント","Dart Expert","強いタイピング","非同期/待機","ストリーム"],"ko":["Dart 프로그래밍","Flutter 프레임워크","모바일 개발","크로스 플랫폼 애플리케이션","AI 도구","Dart Expert","강한 타이핑","비동기/대기","스트림"],"es":["Dart Expert","Desarrollo de aplicaciones móviles","Programación asíncrona","Seguridad de tipos","Flutter","State management","Aplicaciones cross-plataforma","Dart y Flutter","Agentes de IA para desarrolladores"],"fr":["Expert Dart","Développement d''applications mobiles","Programmation asynchrone","Sécurité des types","Flutter","Gestion d''état","Applications cross-plateformes","Dart et Flutter","Agents IA pour développeurs"],"de":["Dart-Experte","Entwicklung von mobilen Anwendungen","Asynchrone Programmierung","Typsicherheit","Flutter","Zustandsverwaltung","Cross-Plattform-Anwendungen","Dart und Flutter","KI-Agenten für Entwickler"],"pt":["Dart Expert","Desenvolvimento móvel","Flutter","Programação Dart","Async/await","Futures","Streams","Mixins","Provider","Riverpod","Bloc"],"ru":["ИИ Агент Dart Expert","Мобильная разработка","Flutter","Программирование на Dart","Async/await","Futures","Streams","Mixins","Provider","Riverpod","Bloc"],"ar":["خبير دارت","تطوير التطبيقات الموبايل","فلاتر","برمجة دارت","Async/await","Futures","Streams","Mixins","Provider","Riverpod","Bloc"]}},"owner":"slym1v98","repo":"flownest-flutter","repoPath":"slym1v98/flownest-flutter","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.338Z","topics":[],"category":"community","skillMd":{"name":"dart-expert","description":"Expert-level Dart, Flutter, mobile development, and cross-platform apps","version":"1.0.0","tags":["dart","flutter","mobile","cross-platform","widgets"],"bodyPreview":"# Dart & Flutter Expert\n\nExpert guidance for Dart programming, Flutter framework, mobile development, and cross-platform applications.\n\n## Core Concepts\n\n### Dart Language\n- Strong typing with type inference\n- Async/await and Futures\n- Streams\n- Mixins and extensions\n- Null safety\n- Collections\n\n### Flutter Framework\n- Widgets (Stateless & Stateful)\n- State management (Provider, Riverpod, Bloc)\n- Navigation and routing\n- Material and Cupertino design\n- Responsive layouts\n- Platform integration","body":"# Dart & Flutter Expert\n\nExpert guidance for Dart programming, Flutter framework, mobile development, and cross-platform applications.\n\n## Core Concepts\n\n### Dart Language\n- Strong typing with type inference\n- Async/await and Futures\n- Streams\n- Mixins and extensions\n- Null safety\n- Collections\n\n### Flutter Framework\n- Widgets (Stateless & Stateful)\n- State management (Provider, Riverpod, Bloc)\n- Navigation and routing\n- Material and Cupertino design\n- Responsive layouts\n- Platform integration\n\n## Dart Fundamentals\n\n```dart\n// Variables and types\nvar name = ''John'';  // Type inference\nString explicitType = ''Explicit'';\nfinal constantValue = 42;  // Runtime constant\nconst compileConstant = ''Compile-time'';\n\n// Null safety\nString? nullableString;\nString nonNullable = ''Never null'';\n\n// Late initialization\nlate String lateInit;\n\n// Collections\nList<String> names = [''Alice'', ''Bob'', ''Charlie''];\nMap<String, int> ages = {''Alice'': 25, ''Bob'': 30};\nSet<int> uniqueNumbers = {1, 2, 3, 3};  // {1, 2, 3}\n\n// Functions\nint add(int a, int b) => a + b;\n\n// Named parameters\nvoid createUser({\n  required String name,\n  int age = 18,\n  String? email,\n}) {\n  print(''Creating user: $name, age: $age'');\n}\n\n// Classes\nclass User {\n  final String id;\n  final String name;\n  int age;\n\n  User({\n    required this.id,\n    required this.name,\n    this.age = 0,\n  });\n\n  // Named constructor\n  User.guest() : this(id: ''guest'', name: ''Guest'');\n\n  // Methods\n  void celebrateBirthday() {\n    age++;\n  }\n\n  @override\n  String toString() => ''User($name, $age)'';\n}\n\n// Mixins\nmixin Loggable {\n  void log(String message) {\n    print(''[${DateTime.now()}] $message'');\n  }\n}\n\nclass LoggableUser extends User with Loggable {\n  LoggableUser({required String id, required String name})\n      : super(id: id, name: name);\n}\n\n// Extensions\nextension StringExtensions on String {\n  bool get isValidEmail => contains(''@'') && contains(''.'');\n  String capitalize() => ''${this[0].toUpperCase()}${substring(1)}'';\n}\n```\n\n## Async Programming\n\n```dart\nimport ''dart:async'';\n\n// Future\nFuture<String> fetchUser(String id) async {\n  await Future.delayed(Duration(seconds: 1));\n  return ''User $id'';\n}\n\n// Error handling\nFuture<User?> fetchUserSafely(String id) async {\n  try {\n    final user = await fetchUser(id);\n    return User(id: id, name: user);\n  } catch (e) {\n    print(''Error: $e'');\n    return null;\n  }\n}\n\n// Multiple futures\nFuture<void> fetchMultiple() async {\n  final results = await Future.wait([\n    fetchUser(''1''),\n    fetchUser(''2''),\n    fetchUser(''3''),\n  ]);\n  print(results);\n}\n\n// Streams\nStream<int> countStream() async* {\n  for (int i = 1; i <= 5; i++) {\n    await Future.delayed(Duration(seconds: 1));\n    yield i;\n  }\n}\n\n// Listen to stream\nvoid listenToStream() {\n  countStream().listen(\n    (data) => print(''Received: $data''),\n    onError: (error) => print(''Error: $error''),\n    onDone: () => print(''Done''),\n  );\n}\n\n// Stream transformations\nStream<String> transformedStream() {\n  return countStream()\n      .where((n) => n % 2 == 0)\n      .map((n) => ''Number: $n'')\n      .take(3);\n}\n\n// StreamController\nclass Counter {\n  final _controller = StreamController<int>();\n\n  Stream<int> get stream => _controller.stream;\n\n  void increment(int value) {\n    _controller.add(value);\n  }\n\n  void dispose() {\n    _controller.close();\n  }\n}\n```\n\n## Flutter Widgets\n\n```dart\nimport ''package:flutter/material.dart'';\n\n// Stateless Widget\nclass UserCard extends StatelessWidget {\n  final User user;\n\n  const UserCard({Key? key, required this.user}) : super(key: key);\n\n  @override\n  Widget build(BuildContext context) {\n    return Card(\n      child: ListTile(\n        title: Text(user.name),\n        subtitle: Text(''Age: ${user.age}''),\n        trailing: Icon(Icons.arrow_forward),\n      ),\n    );\n  }\n}\n\n// Stateful Widget\nclass CounterWidget extends StatefulWidget {\n  const CounterWidget({Key? key}) : super(key: key);\n\n  @override\n  State<CounterWidget> createState() => _CounterWidgetState();\n}\n\nclass _CounterWidgetState extends State<CounterWidget> {\n  int _counter = 0;\n\n  void _incrementCounter() {\n    setState(() {\n      _counter++;\n    });\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return Column(\n      children: [\n        Text(''Counter: $_counter''),\n        ElevatedButton(\n          onPressed: _incrementCounter,\n          child: Text(''Increment''),\n        ),\n      ],\n    );\n  }\n}\n\n// Layout\nclass UserListScreen extends StatelessWidget {\n  final List<User> users;\n\n  const UserListScreen({Key? key, required this.users}) : super(key: key);\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      appBar: AppBar(\n        title: Text(''Users''),\n        actions: [\n          IconButton(\n            icon: Icon(Icons.add),\n            onPressed: () => Navigator.push(\n              context,\n              MaterialPageRoute(builder: (_) => AddUserScreen()),\n            ),\n          ),\n        ],\n      ),\n      body: ListView.builder(\n        itemCount: users.length,\n        itemBuilder: (context, index) {\n          return UserCard(user: users[index]);\n        },\n      ),\n    );\n  }\n}\n```\n\n## State Management (Provider)\n\n```dart\nimport ''package:provider/provider.dart'';\n\n// State class\nclass UserProvider extends ChangeNotifier {\n  List<User> _users = [];\n\n  List<User> get users => _users;\n\n  Future<void> fetchUsers() async {\n    _users = await api.getUsers();\n    notifyListeners();\n  }\n\n  void addUser(User user) {\n    _users.add(user);\n    notifyListeners();\n  }\n\n  void removeUser(String id) {\n    _users.removeWhere((user) => user.id == id);\n    notifyListeners();\n  }\n}\n\n// Setup provider\nvoid main() {\n  runApp(\n    MultiProvider(\n      providers: [\n        ChangeNotifierProvider(create: (_) => UserProvider()),\n        ChangeNotifierProvider(create: (_) => AuthProvider()),\n      ],\n      child: MyApp(),\n    ),\n  );\n}\n\n// Consume provider\nclass UserList extends StatelessWidget {\n  @override\n  Widget build(BuildContext context) {\n    final userProvider = Provider.of<UserProvider>(context);\n\n    return ListView.builder(\n      itemCount: userProvider.users.length,\n      itemBuilder: (context, index) {\n        final user = userProvider.users[index];\n        return ListTile(\n          title: Text(user.name),\n          trailing: IconButton(\n            icon: Icon(Icons.delete),\n            onPressed: () => userProvider.removeUser(user.id),\n          ),\n        );\n      },\n    );\n  }\n}\n\n// Consumer widget\nclass UserCounter extends StatelessWidget {\n  @override\n  Widget build(BuildContext context) {\n    return Consumer<UserProvider>(\n      builder: (context, userProvider, child) {\n        return Text(''Total users: ${userProvider.users.length}'');\n      },\n    );\n  }\n}\n```\n\n## Navigation\n\n```dart\n// Basic navigation\nNavigator.push(\n  context,\n  MaterialPageRoute(builder: (context) => DetailScreen()),\n);\n\n// Named routes\nMaterialApp(\n  routes: {\n    ''/'': (context) => HomeScreen(),\n    ''/details'': (context) => DetailScreen(),\n    ''/settings'': (context) => SettingsScreen(),\n  },\n);\n\nNavigator.pushNamed(context, ''/details'');\n\n// Pass arguments\nNavigator.pushNamed(\n  context,\n  ''/details'',\n  arguments: {''userId'': ''123''},\n);\n\n// Get arguments\nfinal args = ModalRoute.of(context)!.settings.arguments as Map;\n\n// Return data\nfinal result = await Navigator.push(\n  context,\n  MaterialPageRoute(builder: (_) => SelectionScreen()),\n);\n\n// Pop with result\nNavigator.pop(context, selectedValue);\n```\n\n## HTTP and API\n\n```dart\nimport ''package:http/http.dart'' as http;\nimport ''dart:convert'';\n\nclass ApiService {\n  final String baseUrl = ''https://api.example.com'';\n\n  Future<List<User>> fetchUsers() async {\n    final response = await http.get(Uri.parse(''$baseUrl/users''));\n\n    if (response.statusCode == 200) {\n      final List<dynamic> data = json.decode(response.body);\n      return data.map((json) => User.fromJson(json)).toList();\n    } else {\n      throw Exception(''Failed to load users'');\n    }\n  }\n\n  Future<User> createUser(User user) async {\n    final response = await http.post(\n      Uri.parse(''$baseUrl/users''),\n      headers: {''Content-Type'': ''application/json''},\n      body: json.encode(user.toJson()),\n    );\n\n    if (response.statusCode == 201) {\n      return User.fromJson(json.decode(response.body));\n    } else {\n      throw Exception(''Failed to create user'');\n    }\n  }\n}\n\n// Model with JSON serialization\nclass User {\n  final String id;\n  final String name;\n  final String email;\n\n  User({required this.id, required this.name, required this.email});\n\n  factory User.fromJson(Map<String, dynamic> json) {\n    return User(\n      id: json[''id''],\n      name: json[''name''],\n      email: json[''email''],\n    );\n  }\n\n  Map<String, dynamic> toJson() {\n    return {\n      ''id'': id,\n      ''name'': name,\n      ''email'': email,\n    };\n  }\n}\n```\n\n## Best Practices\n\n### Dart\n- Use const constructors when possible\n- Leverage null safety\n- Use final for immutable values\n- Prefer async/await over .then()\n- Use extensions for utility methods\n- Follow Effective Dart guidelines\n\n### Flutter\n- Keep widgets small and focused\n- Use const widgets for optimization\n- Avoid rebuilding entire trees\n- Implement proper state management\n- Handle errors gracefully\n- Test widgets thoroughly\n- Use keys when needed\n\n### Performance\n- Use ListView.builder for long lists\n- Implement pagination\n- Cache network images\n- Minimize widget rebuilds\n- Use const constructors\n- Profile app performance\n- Lazy load resources\n\n## Anti-Patterns\n\n❌ Large widget trees\n❌ State in StatelessWidget\n❌ Not disposing controllers\n❌ Ignoring null safety\n❌ Synchronous I/O in UI\n❌ No error handling\n❌ Hard-coded strings\n\n## Resources\n\n- Dart: https://dart.dev/\n- Flutter: https://flutter.dev/\n- Pub.dev: https://pub.dev/\n- Flutter Widget Catalog: https://flutter.dev/docs/development/ui/widgets\n- Effective Dart: https://dart.dev/guides/language/effective-dart\n"},"lastSynced":"2026-03-08T02:03:23.672Z","agentAnalysis":{"suitability":{"en":"Ideal for Mobile Development Agents seeking expertise in Dart programming and Flutter framework for building robust cross-platform applications.","zh":"适合于寻求Dart编程和Flutter框架专长的移动开发代理，用于构建强大的跨平台应用。","ja":"DartプログラミングとFlutterフレームワークの専門知識を求めるモバイル開発エージェントにとって最適です。強力なクロスプラットフォームアプリケーションを構築するために。","ko":"Dart 프로그래밍과 Flutter 프레임워크 전문성을寻求하는 모바일 개발 에이전트에게 적합합니다. 강력한 크로스 플랫폼 애플리케이션을 구축하기 위해","es":"Ideal para Agentes de Desarrollo Móvil que buscan experiencia en programación Dart y el framework Flutter para construir aplicaciones cross-platform robustas.","fr":"Idéal pour les Agents de Développement Mobile cherchant une expertise en programmation Dart et le framework Flutter pour créer des applications cross-platform robustes.","de":"Ideal für Mobile Development Agents, die Expertenwissen in Dart-Programmierung und Flutter-Framework für den Bau von robusten Cross-Platform-Anwendungen suchen.","pt":"Ideal para Agentes de Desenvolvimento Móvel que buscam especialização em programação Dart e framework Flutter para construir aplicações cross-platform robustas.","ru":"Идеально для Мобильных Разработчиков-Agentов, стремящихся к опыту в программировании на Dart и фреймворке Flutter для создания прочных кроссплатформенных приложений.","ar":"مثالي لعميل التطوير المحمول الذين يبحثون عن خبرة في برمجة Dart وإطار Flutter لبناء تطبيقات متعددة المنصات قوية."},"recommendation":{"en":"Empowers agents to craft scalable and maintainable mobile applications using strong typing, async/await, and null safety features of the Dart language, along with Flutter''s widgets, state management, and platform integration capabilities.","zh":"使代理能够使用Dart语言的强类型、异步/等待和空安全功能，以及Flutter的Widgets、状态管理和平台集成功能，来创建可扩展和可维护的移动应用。","ja":"Dart言語の強い型付け、async/await、null安全機能、およびFlutterのWidgets、状態管理、プラットフォーム統合機能を使用して、拡張可能で保守可能なモバイルアプリケーションを作成できるようにします。","ko":"Dart 언어의 강한 타이핑, async/await, null 안전 기능 및 Flutter의 위젯, 상태 관리, 플랫폼 통합 기능을 사용하여 확장 가능하고 유지 보수 가능한 모바일 애플리케이션을 만들 수 있도록 합니다.","es":"Habilita a los agentes a crear aplicaciones móviles escalables y mantenibles utilizando la tipificación fuerte, async/await y las características de seguridad de null del lenguaje Dart, junto con las capacidades de widgets, gestión de estado y integración de plataforma de Flutter.","fr":"Permet aux agents de créer des applications mobiles évolutives et maintenables en utilisant la typage fort, async/await et les fonctionnalités de sécurité de null du langage Dart, ainsi que les capacités de widgets, de gestion d''état et d''intégration de plate-forme de Flutter.","de":"Ermöglicht es den Agenten, skalierbare und wartbare mobile Anwendungen zu erstellen, indem sie die starke Typisierung, async/await und die Null-Sicherheitsfunktionen der Dart-Sprache sowie die Widget-, Zustandsverwaltungs- und Plattformintegrationsfunktionen von Flutter verwenden.","pt":"Habilita os agentes a criar aplicações móveis escaláveis e mantenedoras utilizando o tipo forte, async/await e recursos de segurança nula da linguagem Dart, juntamente com as capacidades de widgets, gerenciamento de estado e integração de plataforma do Flutter.","ru":"Наделяет агентов возможностью создавать масштабируемые и поддерживаемые мобильные приложения, используя сильную типизацию, async/await и функции безопасности нулевых значений языка Dart, а также возможности виджетов, управления состоянием и интеграции платформы Flutter.","ar":"تمكين الوكيل من إنشاء تطبيقات محمولة قابلة للتوسعة والصيانة باستخدام النوع القوي و async/await ومميزات أمان القيمة الصفرية للغة Dart، جنبًا إلى جنب مع قدرات widgets وإدارة الحالة وتكامل المنصة من Flutter."},"useCases":{"en":["Developing responsive and material-designed mobile applications with Flutter","Implementing null safety and type inference for robust Dart programming","Debugging and optimizing cross-platform applications with Dart and Flutter","Integrating third-party libraries and APIs into Flutter projects"],"zh":["使用Flutter开发响应式和材质设计的移动应用","为强大的Dart编程实现空安全和类型推断","使用Dart和Flutter调试和优化跨平台应用","将第三方库和API集成到Flutter项目中"],"ja":["Flutterを使用してレスポンシブでマテリアルデザインのモバイルアプリを開発する","強力なDartプログラミングのためにnull安全と型推論を実装する","DartとFlutterを使用してクロスプラットフォームアプリをデバッグして最適化する","サードパーティライブラリとAPIをFlutterプロジェクトに統合する"],"ko":["Flutter를 사용하여 반응형 및 물질 디자인 모바일 애플리케이션 개발","강력한 Dart 프로그래밍을 위한 null 안전 및 타입 추론 구현","Dart 및 Flutter를 사용하여 크로스 플랫폼 애플리케이션 디버깅 및 최적화","사드 파티 라이브러리 및 API를 Flutter 프로젝트에 통합"],"es":["Desarrollar aplicaciones móviles responsivas y con diseño de material con Flutter","Implementar la seguridad de null y la inferencia de tipo para una programación Dart robusta","Depurar y optimizar aplicaciones cross-platform con Dart y Flutter","Integrar bibliotecas y API de terceros en proyectos Flutter"],"fr":["Développer des applications mobiles réactives et conçues avec du matériel avec Flutter","Mettre en œuvre la sécurité de null et l''inférence de type pour une programmation Dart robuste","Déboguer et optimiser des applications cross-platform avec Dart et Flutter","Intégrer des bibliothèques et des API tierces dans des projets Flutter"],"de":["Entwickeln von responsiven und materialdesignten mobilen Anwendungen mit Flutter","Implementieren von Null-Sicherheit und Typinferenz für robuste Dart-Programmierung","Debuggen und Optimieren von Cross-Platform-Anwendungen mit Dart und Flutter","Integrieren von Drittanbieterbibliotheken und APIs in Flutter-Projekte"],"pt":["Desenvolver aplicações móveis responsivas e projetadas com material design com o Flutter","Implementar segurança nula e inferência de tipo para programação Dart robusta","Depurar e otimizar aplicações cross-platform com Dart e Flutter","Integrar bibliotecas e APIs de terceiros em projetos Flutter"],"ru":["Разраб