INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('vorluno/Vorluno-Planilla/dotnet-core-expert', 'dotnet-core-expert', 'vorluno', 'Vorluno-Planilla', 'community', 'dotnet-core-expert vorluno Vorluno-Planilla community The dotnet-core-expert skill provides expertise in .NET 8, modern C#, and cloud-native application development for building enterprise applications. It benefits senior .NET engineers and developers. 高级 .NET Core 专家，具有 .NET 8、C# 12、最小 API 和云原生应用开发的深入专业知识 .NET Core エキスパートは、.NET 8、C# 12、最小 API、クラウドネイティブ アプリケーション開発における深い専門知識を持つ .NET Core 전문가는 .NET 8, C# 12, 최소 API, 클라우드 네이티브 애플리케이션 개발에 대한 심도 있는 전문 지식을 갖춘 고급 전문가 El experto en dotnet-core es un especialista senior en .NET Core con experiencia en .NET 8, C# 12 y patrones de aplicaciones nativas de la nube L''expert en dotnet-core est un spécialiste senior en .NET Core avec une expérience en .NET 8, C# 12 et modèles d''applications natives de cloud Der dotnet-core-Experte ist ein Senior-Spezialist für .NET Core mit Erfahrung in .NET 8, C# 12 und Cloud-nativen AnwendungsMustern O .NET Core Expert é um especialista sênior em .NET Core com expertise em .NET 8, C# 12, minimal APIs e desenvolvimento de aplicações nativas de nuvem Эксперт .NET Core — это старший специалист по .NET Core с глубокими знаниями в области .NET 8, C# 12, минимальных API и разработки облачных приложений для ИИ Агентов خبير .NET Core هو خبير أول في .NET Core مع خبرة في .NET 8 و C# 12 و واجهات برمجة التطبيقات المُختَصرة و تطوير التطبيقات الأصلية السحابية للأدوات الذكية how to use dotnet-core-expert dotnet-core-expert alternative dotnet-core-expert setup guide what is dotnet-core-expert dotnet-core-expert vs .NET 8 dotnet-core-expert install dotnet-core-expert for cloud-native applications dotnet-core-expert for minimal APIs dotnet-core-expert for enterprise applications .NET Core 专家 .NET 8 C# 12 最小 API 云原生应用开发 Clean Architecture 高性能应用开发 企业应用开发 Builds high-performance, scalable applications with clean architecture Develops minimal APIs with .NET 8 Utilizes Entity Framework Core for data access Supports cloud-native patterns for application development Leverages C# 12 for modern application development Integrates with React 19 for frontend development dotnet-core-expert is a senior .NET Core specialist skill with deep expertise in .NET 8, minimal APIs, and cloud-native application development.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('DeL-TaiseiOzaki/claude-code-orchestra/team-implement', 'community', 'DeL-TaiseiOzaki', 'claude-code-orchestra', 'DeL-TaiseiOzaki/claude-code-orchestra', 'team-implement', 113, 18, 49, '2026-02-25T18:33:37Z', '2026-03-06T06:30:42.726Z', '29280e5cff1da8471a5700fc7441b83ad008c5de2149cdb447755eab27a0de3d', '{"id":"DeL-TaiseiOzaki/claude-code-orchestra/team-implement","name":"team-implement","description":{"en":"team-implement executes parallel implementation using Agent Teams based on approved plans in /startproject, benefiting developers and project managers. It analyzes task dependencies and determines team composition.","zh":"团队实施是使用Agent团队进行并行实现的技能，依据在 `/startproject` 中批准的计划执行","ja":"チーム実装は、 `/startproject` で承認されたプランに基づいてAIエージェントを使用して並列実装します","ko":"팀 구현은 에이전트 팀을 사용하여 병렬 구현하는 스킬로, `/startproject`에서 승인된 계획에 따라 실행됩니다","es":"Implementa equipos de agentes AI de manera paralela según el plan aprobado en /startproject","fr":"Mettez en œuvre des équipes d''agents IA en parallèle selon le plan approuvé dans /startproject","de":"Implementieren Sie AI-Agenten-Teams parallel zum genehmigten Plan in /startproject","pt":"O Team Implement permite a implementação paralela de projetos com base no plano aprovado. Analise dependências de tarefas e determine a composição da equipe.","ru":"Team Implement позволяет параллельную реализацию проектов на основе утвержденного плана. Анализируйте зависимости задач и определяйте состав команды.","ar":"يسمح فريق التنفيذ بتنفيذ المشاريع بالتوازي بناءً على الخطة المعتمدة. تحليل التبعيات بين المهام وتحديد تكوين الفريق"},"seo":{"title":{"en":"team-implement: Parallel Implementation Setup Guide | AI ...","zh":"团队实施设置指南 - 并行实现使用Agent团队","ja":"チーム実装ベストプラクティス - AIエージェントを使用した並列実装","ko":"팀 구현 가이드 - 에이전트 팀을 사용한 병렬 구현","es":"Guía de implementación de equipos de agentes AI","fr":"Guide de mise en œ