INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('DeL-TaiseiOzaki/claude-code-orchestra/team-implement', 'team-implement', 'DeL-TaiseiOzaki', 'claude-code-orchestra', 'community', 'team-implement DeL-TaiseiOzaki claude-code-orchestra community team-implement executes parallel implementation using Agent Teams based on approved plans in /startproject, benefiting developers and project managers. It analyzes task dependencies and determines team composition. 团队实施是使用Agent团队进行并行实现的技能，依据在 `/startproject` 中批准的计划执行 チーム実装は、 `/startproject` で承認されたプランに基づいてAIエージェントを使用して並列実装します 팀 구현은 에이전트 팀을 사용하여 병렬 구현하는 스킬로, `/startproject`에서 승인된 계획에 따라 실행됩니다 Implementa equipos de agentes AI de manera paralela según el plan aprobado en /startproject Mettez en œuvre des équipes d''agents IA en parallèle selon le plan approuvé dans /startproject Implementieren Sie AI-Agenten-Teams parallel zum genehmigten Plan in /startproject O Team Implement permite a implementação paralela de projetos com base no plano aprovado. Analise dependências de tarefas e determine a composição da equipe. Team Implement позволяет параллельную реализацию проектов на основе утвержденного плана. Анализируйте зависимости задач и определяйте состав команды. يسمح فريق التنفيذ بتنفيذ المشاريع بالتوازي بناءً على الخطة المعتمدة. تحليل التبعيات بين المهام وتحديد تكوين الفريق how to use team-implement team-implement setup guide parallel implementation with Agent Teams team-implement alternative team-implement vs competitor team-implement install what is team-implement team-implement documentation team-implement tutorial 团队实施 并行实现 Agent团队 `/startproject` `.claude/docs/DESIGN.md` 任务依赖分析 团队组成确定 Analyzes task dependencies from plans in /startproject Determines team composition based on task dependencies Spawns Agent Teams per module/layer Launches teammates per module/layer Executes parallel implementation based on approved plans team-implement is a skill that enables parallel implementation using Agent Teams, executing plans approved in /startproject with documented architecture in .claude/docs/DESIGN.md');
