INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('way-platform/tachograph-go/way-magefile', 'way-magefile', 'way-platform', 'tachograph-go', 'community', 'way-magefile way-platform tachograph-go community way-magefile是tachograph (.DDD) 文件的Go SDK，提供简单易用的API way-magefileはtachograph (.DDD) ファイル用のGo SDKです。シンプルで使いやすいAPIを提供します way-magefile은 tachograph (.DDD) 파일을 위한 Go SDK입니다. 간단하고 사용하기 쉬운 API를 제공합니다 way-magefile es un SDK de Go para trabajar con archivos tachográficos (.DDD). way-magefile est un SDK Go pour travailler avec des fichiers tachographiques (.DDD). way-magefile ist ein Go-SDK für die Arbeit mit Tachographen-Dateien (.DDD). O way-magefile é um SDK em Go para arquivos .DDD de tachógrafo, permitindo desenvolvedores trabalhar com esses arquivos de forma eficiente Way-magefile - это SDK для Go для файлов .DDD тахографа, позволяющий разработчикам работать с этими файлами эффективно way-magefile هو SDK بلغة Go لملفات .DDD للتخطيط، مما يسمح للمطورين بالعمل مع هذه الملفات بفعالية Go SDK for tachograph (.DDD) files way-magefile tachograph DDD文件 Go SDK 开发工具 tachograph文件处理 Go语言开发 开发效率 way-magefile安装 way-magefile使用 Go SDK for tachograph (.DDD) files');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('F3-Nation/f3-nation/f3-dev-servers', 'community', 'F3-Nation', 'f3-nation', 'F3-Nation/f3-nation', 'f3-dev-servers', 0, 0, 49, '2026-02-27T01:51:08.567Z', '2026-02-27T03:09:53.165Z', 'ad7ce5a929008190a3c4bcd4c2f4b7d9ff1989d7fc239b3cdc1bf998c958c0eb', '{"id":"F3-Nation/f3-nation/f3-dev-servers","name":"f3-dev-servers","description":{"zh":"F3 Nation Monorepo开发服务器是一个高效的开发环境，提供AI智能工具解决方案","ja":"F3 Nation Monorepo開発サーバーは、AIエージェントを使用した効率的な開発環境を提供します","ko":"F3 Nation Monorepo 개발 서버는 AI 에이전트를 활용한 효율적인 개발 환경을 제공합니다","es":"F3 Nation Monorepo ofrece herramientas de f3-dev-servers para desarrolladores, mejorando la eficiencia y productividad","fr":"F3 Nation Monorepo propose des outils f3-dev-servers pour les développeurs, améliorant l''efficacité et la productivité","de":"F3 Nation Monorepo bietet F3-Dev-Servers-Tools für Entwickler, um Effizienz und Produktivität zu verbessern","pt":"O f3-dev-servers é uma ferramenta de AI para desenvolvedores que trabalham com o monorepo F3 Nation, oferecendo recursos para desenvolver aplicações de forma eficiente.","ru":"ИИ Агент f3-dev-servers предназначен для разработчиков, работающих с монорепозиторием F3 Nation, и предоставляет функции для эффективного развития приложений.","ar":"أداة الذكاء الاصطناعي f3-dev-servers مصممة للمطورين الذين يعملون مع مونوريبو F3 Nation، وتقدم ميزات لتطوير التطبيقات بفعالية.","en":"F3 Nation Monorepo"},"seo":{"title":{"zh":"F3开发服务器 - AI智能工具","ja":"F3開発サーバー - AIエージェント","ko":"F3 개발 서버 - AI 에이전트","es":"Herramientas de f3-dev-servers para Desarrolladores","fr":"Outils f3-dev-servers pour Développeurs","de":"F3-Dev-Servers-Tools für Entwickler","pt":"Ferramentas de AI: f3-dev-servers para Desenvolvedores","ru":"ИИ Агенты: f3-dev-servers для Разработчиков","ar":"أدوات الذكاء الاصطناعي: f3-dev-servers للمطورين","en":"f3-dev-servers"},"description":{"zh":"F3 Nation Monorepo开发服务器是一个高效的开发环境，提供AI智能工具解决方案","ja":"F3 Nation Monorepo開発サーバーは、AIエージェントを使用した効率的な開発環境を提供します","ko":"F3 Nation Monorepo 개발 서버는 AI 에이전트를 활용한 효율적인 개발 환경을 제공합니다","es":"F3 Nation Monorepo ofrece herramientas de f3-dev-servers para desarrolladores, mejorando la eficiencia y productividad","fr":"F3 Nation Monorepo propose des outils f3-dev-servers pour les développeurs, améliorant l''efficacité et la productivité","de":"F3 Nation Monorepo bietet F3-Dev-Servers-Tools für Entwickler, um Effizienz und Produktivität zu verbessern","pt":"O f3-dev-servers é uma ferramenta de AI para desenvolvedores que trabalham com o monorepo F3 Nation, oferecendo recursos para desenvolver aplicações de forma...","ru":"ИИ Агент f3-dev-servers предназначен для разработчиков, работающих с монорепозиторием F3 Nation, и предоставляет функции для эффективного развития приложений.","ar":"أداة الذكاء الاصطناعي f3-dev-servers مصممة للمطورين الذين يعملون مع مونوريبو F3 Nation، وتقدم ميزات لتطوير التطبيقات بفعالية.","en":"F3 Nation Monorepo"},"definition":{"en":"F3 Nation Monorepo"},"features":{"zh":["支持多种开发语言","提供高效的开发环境","集成AI智能工具","支持CLI命令","提供Node.js和Python支持"],"ja":["複数の開発言語をサポート","効率的な開発環境を提供","AIエージェントを統合","CLIコマンドをサポート","Node.jsとPythonをサポート"],"ko":["다중 개발 언어 지원","효율적인 개발 환경 제공","AI 에이전트 통합","CLI 명령어 지원","Node.js와 Python 지원"],"es":["Mejora de la eficiencia del desarrollo","Integración con la nación monorepo de F3","Herramientas de desarrollo personalizadas","Soporte para múltiples plataformas","Integración con herramientas de desarrollo populares"],"fr":["Amélioration de l''efficacité du développement","Intégration avec la nation monorepo de F3","Outils de développement personnalisés","Prise en charge de plusieurs plateformes","Intégration avec des outils de développement populaires"],"de":["Verbesserung der EntwicklungsEffizienz","Integration mit der F3-Monorepo-Nation","Benutzerdefinierte Entwicklungstools","Unterstützung für mehrere Plattformen","Integration mit beliebten Entwicklungstools"],"pt":["Desenvolvimento de aplicações com monorepo F3 Nation","Recursos de AI para desenvolvedores","Integração com ferramentas de desenvolvimento","Suporte a linguagens de programação como React e Node.js","CLI para facilitar o desenvolvimento","Agent para automação de tarefas"],"ru":["Разработка приложений с монорепозиторием F3 Nation","Возможности ИИ для разработчиков","Интеграция с инструментами разработки","Поддержка языков программирования как React и Node.js","CLI для упрощения разработки","Агент для автоматизации задач"],"ar":["تطوير التطبيقات باستخدام مونوريبو F3 Nation","ميزات الذكاء الاصطناعي للمطورين","التكامل مع أدوات التطوير","دعم لغات البرمجة مثل React و Node.js","CLI لتسهيل التطوير","وكلاء للآليّة Tasks"]},"keywords":{"zh":["F3开发服务器","AI智能工具","开发环境","如何使用F3开发服务器","F3开发服务器安装","F3开发服务器教程"],"ja":["F3開発サーバー","AIエージェント","開発環境","F3開発サーバーの使い方","F3開発サーバーインストール","F3開発サーバーチュートリアル"],"ko":["F3 개발 서버","AI 에이전트","개발 환경","F3 개발 서버 사용법","F3 개발 서버 설치","F3 개발 서버 튜토리얼"],"es":["herramientas de desarrollo","f3-dev-servers","nación monorepo de F3","cómo usar f3-dev-servers","alternativas a f3-dev-servers","guía de instalación de f3-dev-servers","configuración de f3-dev-servers","desarrollo de software","herramientas de desarrollo de software"],"fr":["outils de développement","f3-dev-servers","nation monorepo de F3","comment utiliser f3-dev-servers","alternatives à f3-dev-servers","guide d''installation de f3-dev-servers","configuration de f3-dev-servers","développement de logiciels","outils de développement de logiciels"],"de":["Entwicklungstools","F3-Dev-Servers","F3-Monorepo-Nation","wie man F3-Dev-Servers verwendet","Alternativen zu F3-Dev-Servers","Installationsanleitung für F3-Dev-Servers","Konfiguration von F3-Dev-Servers","Software-Entwicklung","Software-Entwicklungstools"],"pt":["como usar f3-dev-servers","o que é f3-dev-servers","f3-dev-servers alternative","f3-dev-servers vs outros agentes","instalar f3-dev-servers","guia de configuração do f3-dev-servers","desenvolvimento de aplicações com AI","ferramentas de AI para desenvolvedores"],"ru":["как использовать f3-dev-servers","что такое f3-dev-servers","альтернативы f3-dev-servers","f3-dev-servers vs другие агенты","установка f3-dev-servers","руководство по настройке f3-dev-servers","разработка приложений с ИИ","инструменты ИИ для разработчиков"],"ar":["كيفية استخدام ف3-dev-servers","ما هو ف3-dev-servers","بديل ف3-dev-servers","ف3-dev-servers مقابل وكلاء آخرين","تثبيت ف3-dev-servers","دليل إعداد ف3-dev-servers","تطوير التطبيقات باستخدام الذكاء الاصطناعي","أدوات الذكاء الاصطناعي للمطورين"]}},"owner":"F3-Nation","repo":"f3-nation","repoPath":"F3-Nation/f3-nation","stars":0,"forks":0,"updatedAt":"2026-02-27T01:51:08.567Z","topics":[],"category":"community","skillMd":{"name":"f3-dev-servers","description":"Start and manage f3-nation development servers (Caddy, API, Map). Use when the user wants to start dev servers, check if services are running, or troubleshoot the local development environment.","bodyPreview":"# F3 Nation Development Servers\n\nStart the three dev servers needed for local f3-nation development.\n\n## Starting All Services (Agent Method)\n\nThe agent CAN start all three services by running Shell commands with `block_until_ms: 0` to background them immediately.\n\nRun these in parallel with `block_until_ms: 0` and `working_directory` set to the repo root:\n\n```bash\n# 1. Caddy\ncaddy run --config Caddyfile\n\n# 2. API\nPORT=3001 pnpm -F f3-nation-api dev\n\n# 3. Map\nPORT=3000 pnpm -F f3-nation-map dev","body":"# F3 Nation Development Servers\n\nStart the three dev servers needed for local f3-nation development.\n\n## Starting All Services (Agent Method)\n\nThe agent CAN start all three services by running Shell commands with `block_until_ms: 0` to background them immediately.\n\nRun these in parallel with `block_until_ms: 0` and `working_directory` set to the repo root:\n\n```bash\n# 1. Caddy\ncaddy run --config Caddyfile\n\n# 2. API\nPORT=3001 pnpm -F f3-nation-api dev\n\n# 3. Map\nPORT=3000 pnpm -F f3-nation-map dev\n```\n\nNote: nvm/rbenv/jenv should be auto-loaded via `~/.zshenv` so no prefix needed.\n\n**Agent workflow:**\n\n1. Run check-status.sh first to see what''s already running\n2. Start only the services that aren''t running (use `block_until_ms: 0` for each)\n3. Wait 5 seconds for services to initialize\n4. Run check-status.sh again to verify all services are up\n5. Optionally read terminal output files to check for startup errors\n\n## Quick Check: Are Services Running?\n\nRun the status check script from the repo root:\n\n```bash\n.cursor/skills/f3-dev-servers/scripts/check-status.sh\n```\n\nThis script uses `nc` (netcat) for fast port checking (~1 second). It checks ports 443, 3000, and 3001.\n\nOr check manually:\n\n```bash\n# Fast check with netcat\nnc -z localhost 443 && echo \"Caddy OK\" || echo \"Caddy DOWN\"\nnc -z localhost 3000 && echo \"Map OK\" || echo \"Map DOWN\"\nnc -z localhost 3001 && echo \"API OK\" || echo \"API DOWN\"\n```\n\nNote: Avoid using `lsof` for port checks on macOS - it takes 30+ seconds.\n\n## Manual Startup (User Method)\n\nIf the user prefers to start manually in named terminals:\n\n### 1. Caddy (reverse proxy) - in `caddy` terminal\n\n```bash\ncaddy run --config Caddyfile\n```\n\nCaddy proxies:\n\n- `https://map.f3nation.test` → `localhost:3000`\n- `https://api.f3nation.test` → `localhost:3001`\n\n### 2. API Server - in `api` terminal\n\n```bash\nPORT=3001 pnpm -F f3-nation-api dev\n```\n\n### 3. Map App - in `map` terminal\n\n```bash\nPORT=3000 pnpm -F f3-nation-map dev\n```\n\n## Startup Order\n\nStart in this order for best results:\n\n1. Caddy first (handles HTTPS)\n2. API second (the map app depends on API endpoints)\n3. Map app last\n\n## Verifying Startup Success\n\nAfter starting, check terminal outputs for these success indicators:\n\n- **Caddy**: Look for `\"msg\":\"serving initial configuration\"`\n- **API**: Look for `✓ Ready in X.Xs`\n- **Map**: Look for `✓ Ready in X.Xs`\n\n## Stopping Services\n\nTo stop services, use `pkill` (faster than lsof):\n\n```bash\npkill -f \"caddy run\"\npkill -f \"f3-nation-api dev\"\npkill -f \"f3-nation-map dev\"\n```\n\nOr kill by port (slower, lsof takes 30+ seconds on macOS):\n\n```bash\nkill -9 $(lsof -t -i :3000)  # Map\nkill -9 $(lsof -t -i :3001)  # API\nsudo kill -9 $(lsof -t -i :443)   # Caddy (needs sudo for port 443)\n```\n\nFor user-started services in IDE terminals, press `Ctrl+C` in the terminal.\n\n## Troubleshooting\n\n### Port already in use\n\n```bash\n# Find what''s using the port\nlsof -i :3000\n\n# Kill it\nkill -9 <PID>\n```\n\n### Node version warning\n\nIf you see this warning:\n\n```\nWARN  Unsupported engine: wanted: {\"node\":\">=20.19.0\"} (current: {\"node\":\"v18.20.4\"...})\n```\n\nThe `~/.zshenv` file may be missing or misconfigured. It should contain:\n\n```bash\nexport NVM_DIR=\"$HOME/.nvm\"\n[ -s \"$NVM_DIR/nvm.sh\" ] && \\. \"$NVM_DIR/nvm.sh\"\n```\n\nThis ensures nvm is loaded for all zsh shells, including non-interactive ones from Cursor.\n\n### Caddy certificate issues\n\nEnsure the certificate files exist in the project root:\n\n- `map.f3nation.test+1-cert.pem`\n- `map.f3nation.test+1-key.pem`\n\nIf missing, regenerate with mkcert:\n\n```bash\nmkcert map.f3nation.test api.f3nation.test\n```\n\n### Database not running\n\nIf you see database connection errors, ensure PostgreSQL/Docker is running:\n\n```bash\ndocker ps  # Check if postgres container is running\n```\n"},"lastSynced":"2026-02-27T03:09:53.165Z","agentAnalysis":{"suitability":{"en":"Perfect for Full-Stack Agents needing simultaneous development server management for Caddy, API, and Map services.","zh":"适合需要同时管理Caddy、API和Map服务的开发服务器的全栈代理。","ja":"Caddy、API、およびMapサービスを同時に開発サーバーを管理する必要があるフルスタックエージェントに最適です。","ko":"Caddy, API 및 Map 서비스의 동시 개발 서버 관리가 필요한 풀스택 에이전트에 적합합니다.","es":"Perfecto para Agentes Full-Stack que necesitan gestión simultánea de servidores de desarrollo para Caddy, API y servicios de Mapa.","fr":"Parfait pour les agents Full-Stack ayant besoin d''une gestion simultanée des serveurs de développement pour Caddy, API et services de carte.","de":"Perfekt für Full-Stack-Agents, die eine simultane Verwaltung von Entwicklungsservern für Caddy, API und Karten-Dienste benötigen.","pt":"Perfeito para Agentes Full-Stack que precisam de gerenciamento de servidor de desenvolvimento simultâneo para Caddy, API e serviços de Mapa.","ru":"Идеально подходит для агентов Full-Stack, которым требуется одновременное управление сервером разработки для Caddy, API и служб карт.","ar":"مثالي للوكلاء كامل الحزمة الذين يحتاجون إلى إدارة خادم التطوير المتزامن لخدمات Caddy و API و الخريطة."},"recommendation":{"en":"Empowers agents to run Caddy, API, and Map development servers in parallel using Shell commands, leveraging `block_until_ms: 0` for immediate backgrounding and `working_directory` for repo root setup, while utilizing protocols like pnpm for package management.","zh":"赋予代理同时运行Caddy、API和Map开发服务器的能力，使用Shell命令，利用`block_until_ms: 0`实现立即后台运行，并利用`working_directory`设置仓库根目录，同时利用像pnpm这样的协议进行包管理。","ja":"エージェントがCaddy、API、およびMap開発サーバーを同時に実行する能力を提供します。シェルコマンドを使用し、`block_until_ms: 0`を使用して即時のバックグラウンド実行を行い、`working_directory`を使用してリポジトリのルートディレクトリを設定し、pnpmなどのプロトコルを使用してパッケージ管理を実行します。","ko":"에이전트가 Caddy, API 및 Map 개발 서버를 동시에 실행할 수 있는 능력을 제공합니다. 셸 명령어를 사용하며 `block_until_ms: 0`를 사용하여 즉시 백그라운드 실행을 하며 `working_directory`를 사용하여 리포지토리 루트 디렉토리를 설정하며 pnpm과 같은 프로토콜을 사용하여 패키지 관리를 수행합니다.","es":"Permite a los agentes ejecutar servidores de desarrollo de Caddy, API y Mapa en paralelo utilizando comandos de Shell, aprovechando `block_until_ms: 0` para un segundo plano inmediato y `working_directory` para la configuración de la raíz del repositorio, mientras utiliza protocolos como pnpm para la gestión de paquetes.","fr":"Permet aux agents d''exécuter des serveurs de développement Caddy, API et Carte en parallèle en utilisant des commandes Shell, en exploitant `block_until_ms: 0` pour un arrière-plan immédiat et `working_directory` pour la configuration de la racine du référentiel, tout en utilisant des protocoles tels que pnpm pour la gestion des packages.","de":"Ermöglicht es Agents, Caddy-, API- und Karten-Entwicklungsserver parallel mit Shell-Befehlen auszuführen, indem `block_until_ms: 0` für eine sofortige Hintergrundausführung und `working_directory` für die Repository-Wurzelkonfiguration genutzt wird, während Protokolle wie pnpm für die Paketverwaltung verwendet werden.","pt":"Habilita os agentes a executar servidores de desenvolvimento Caddy, API e Mapa em paralelo usando comandos Shell, aproveitando `block_until_ms: 0` para background imediato e `working_directory` para configuração da raiz do repositório, enquanto utiliza protocolos como pnpm para gerenciamento de pacotes.","ru":"Позволяет агентам запускать серверы разработки Caddy, API и карт в параллели с помощью команд Shell, используя `block_until_ms: 0` для немедленного фонового режима и `working_directory` для настройки корневого каталога репозитория, а также использует протоколы, такие как pnpm, для управления пакетами.","ar":"يسمح للوكلاء بتشغيل خوادم التطوير Caddy و API و الخريطة بالتوازي باستخدام أوامر Shell ، مع الاستفادة من `block_until_ms: 0` للخلفية الفورية و `working_directory` لإعداد الجذر للمستودع ، مع استخدام بروتوكولات مثل pnpm لإدارة الحزم."},"useCases":{"en":["Starting Caddy servers for local development","Debugging API services with `pnpm -F f3-nation-api dev`","Launching Map development servers with `PORT=3000` configuration"],"zh":["启动Caddy服务器进行本地开发","使用`pnpm -F f3-nation-api dev`调试API服务","使用`PORT=3000`配置启动Map开发服务器"],"ja":["Caddyサーバーをローカル開発用に起動する","`pnpm -F f3-nation-api dev`を使用してAPIサービスをデバッグする","`PORT=3000`構成でMap開発サーバーを起動する"],"ko":["Caddy 서버를 로컬 개발용으로 시작하는 것","`pnpm -F f3-nation-api dev`를 사용하여 API 서비스를 디버깅하는 것","`PORT=3000` 구성으로 Map 개발 서버를 시작하는 것"],"es":["Inicio de servidores Caddy para desarrollo local","Depuración de servicios API con `pnpm -F f3-nation-api dev`","Lanzamiento de servidores de desarrollo de Mapa con configuración `PORT=3000`"],"fr":["Démarrage de serveurs Caddy pour le développement local","Débogage des services API avec `pnpm -F f3-nation-api dev`","Lancement de serveurs de développement de carte avec une configuration `PORT=3000`"],"de":["Starten von Caddy-Servern für die lokale Entwicklung","Debuggen von API-Diensten mit `pnpm -F f3-nation-api dev`","Starten von Karten-Entwicklungsservern mit `PORT=3000`-Konfiguration"],"pt":["Iniciar servidores Caddy para desenvolvimento local","Depurar serviços API com `pnpm -F f3-nation-api dev`","Iniciar servidores de desenvolvimento de Mapa com configuração `PORT=3000`"],"ru":["Запуск серверов Caddy для локальной разработки","Отладка служб API с помощью `pnpm -F f3-nation-api dev`","Запуск серверов разработки карт с конфигурацией `PORT=3000`"],"ar":["تشغيل خوادم Caddy للتطوير المحلي","تصحيح أخطاء خدمات API باستخدام `pnpm -F f3-nation-api dev`","تشغيل خوادم التطوير الخريطة مع تكوين `PORT=3000`"]},"limitations":{"en":["Requires Shell command execution capabilities","Dependent on pnpm package manager","Limited to local development environment"],"zh":["需要Shell命令执行能力","依赖于pnpm包管理器","仅限本地开发环境"],"ja":["シェルコマンドの実行能力が必要","pnpmパッケージマネージャーに依存する","ローカル開発環境に限定される"],"ko":["셸 명령어 실행 능력이 필요함","pnpm 패키지 매니저에 의존함","로컬 개발 환경으로 제한됨"],"es":["Requiere capacidad de ejecución de comandos de Shell","Dependiente del administrador de paquetes pnpm","Limitado al entorno de desarrollo local"],"fr":["Nécessite une capacité d''exécution de commandes Shell","Dépendant du gestionnaire de packages pnpm","Limité à l''environnement de développement local"],"de":["Erfordert die Ausführungsfähigkeit von Shell-Befehlen","Abhängig vom Paketmanager pnpm","Begrenzt auf die lokale Entwicklungsumgebung"],"pt":["Requer capacidades de execução de comandos Shell","Dependente do gerenciador de pacotes pnpm","Limitado ao ambiente de desenvolvimento local"],"ru":["Требует возможности выполнения команд Shell","Зависит от менеджера пакетов pnpm","Ограничен локальной средой разработки"],"ar":["يتطلب khảيّات تشغيل أوامر Shell","يعتمد على مدير الحزم pnpm","محدود بالبيئة المحلية للتطوير"]},"version":3},"contentHash":"ad7ce5a929008190a3c4bcd4c2f4b7d9ff1989d7fc239b3cdc1bf998c958c0eb","qualityScore":49}');
